n/interviews/levels/1','','2a09:bac1:36c0:128::2a7:70','Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/153.0.0.0 Safari/537.36',200,1,'','{\"data\":{\"created_at\":\"2026-09-17T07:44:11Z\",\"description\":\"Fundamental data structures and two-pointer techniques\",\"duration_minutes\":45,\"id\":1,\"level_number\":1,\"mode\":\"coding\",\"name\":\"Arrays, Strings \\u0026 HashMaps\",\"question_count\":1,\"questions_count\":0,\"track_id\":1,\"updated_at\":\"2026-09-17T07:44:25.437Z\"},\"status\":\"success\"}','','2026-09-17 07:50:40.452'),(182,2,'admin@bitsathy.ac.in','System Administrator','admin','GET','/api/v1/admin/interviews/levels/1/questions','','2a09:bac1:36c0:128::2a7:70','Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/153.0.0.0 Safari/537.36',200,1,'','{\"data\":[],\"status\":\"success\"}','','2026-09-17 07:50:40.500'),(183,2,'admin@bitsathy.ac.in','System Administrator','admin','GET','/api/v1/admin/interviews/tracks/1','','2a09:bac1:36c0:128::2a7:70','Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/153.0.0.0 Safari/537.36',200,3,'','{\"data\":{\"category\":\"Technical\",\"created_at\":\"2026-09-17T07:43:11Z\",\"description\":\"Core problem solving, arrays, trees, dynamic programming, and algorithmic complexity.\",\"icon\":\"Code\",\"id\":1,\"levels_count\":3,\"questions_count\":0,\"slug\":\"dsa\",\"title\":\"Data Structures \\u0026 Algorithms\",\"updated_at\":\"2026-09-17T07:43:11Z\"},\"status\":\"success\"}','','2026-09-17 07:50:40.500'),(184,2,'admin@bitsathy.ac.in','System Administrator','admin','POST','/api/v1/admin/interviews/levels/1/questions/bulk','','2a09:bac1:36c0:128::2a7:70','Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/153.0.0.0 Safari/537.36',200,757,'{\"questions\":[{\"title\":\"Two Sum with Target Lookup\",\"prompt\":\"Given an array of integers and a target integer, find the indices of two different elements whose sum equals the target. Print the two indices in increasing order. Exactly one valid pair exists.\",\"difficulty\":\"Easy\",\"type\":\"coding\",\"detail\":{\"constraints\":\"2 <= N <= 10^5\\n-10^9 <= nums[i] <= 10^9\\nExactly one valid answer exists.\\nTime Limit: 2.0s\\nMemory Limit: 256MB\",\"expected_approach\":\"Traverse the array once and use a HashMap to store previously visited numbers and their indices. For each number, check whether target - nums[i] already exists.\",\"expected_complexity\":\"Time: O(N), Space: O(N)\"},\"test_cases\":[{\"input\":\"4\\n2 7 11 15\\n9\",\"expected_output\":\"0 1\",\"is_hidden\":false},{\"input\":\"5\\n3 3 8 2 10\\n6\",\"expected_output\":\"0 1\",\"is_hidden\":true}],\"hints\":[{\"type\":\"hint\",\"content\":\"Can you store already visited numbers and look for target - current number?\"},{\"type\":\"interview_tip\",\"content\":\"Ask why a nested-loop solution becomes O(N^2).\"}],\"level_id\":1},{\"title\":\"Valid Anagram\",\"prompt\":\"Given two strings, determine whether they are anagrams of each other. Two strings are anagrams if they contain exactly the same characters with the same frequencies.\",\"difficulty\":\"Easy\",\"type\":\"coding\",\"detail\":{\"constraints\":\"1 <= s.length, t.length <= 10^5\\nStrings contain lowercase English letters.\\nTime Limit: 2.0s\\nMemory Limit: 256MB\",\"expected_approach\":\"Count the frequency of every character in the first string and compare it with the frequency of characters in the second string using a HashMap or frequency array.\",\"expected_complexity\":\"Time: O(N), Space: O(K)\"},\"test_cases\":[{\"input\":\"anagram\\nnagaram\",\"expected_output\":\"true\",\"is_hidden\":false},{\"input\":\"rat\\ncar\",\"expected_output\":\"false\",\"is_hidden\":true}],\"hints\":[{\"type\":\"hint\",\"content\":\"Think about how to count the frequency of each character.\"},{\"type\":\"interview_tip\",\"content\":\"Ask whether sorting both strings is necessary and what its complexity would be.\"}],\"level_id\":1},{\"title\":\"First Non-Repeating Character\",\"prompt\":\"Given a string, find the index of the first character that appears exactly once. If no such character exists, print -1.\",\"difficulty\":\"Easy\",\"type\":\"coding\",\"detail\":{\"constraints\":\"1 <= s.length <= 10^5\\ns consists of lowercase English letters.\\nTime Limit: 2.0s\\nMemory Limit: 256MB\",\"expected_approach\":\"Build a frequency map for all characters, then make a second pass through the string and return the index of the first character whose frequency is one.\",\"expected_complexity\":\"Time: O(N), Space: O(K)\"},\"test_cases\":[{\"input\":\"leetcode\",\"expected_output\":\"0\",\"is_hidden\":false},{\"input\":\"aabbcc\",\"expected_output\":\"-1\",\"is_hidden\":true}],\"hints\":[{\"type\":\"hint\",\"content\":\"First count how many times every character occurs.\"},{\"type\":\"interview_tip\",\"content\":\"Ask why two passes still result in O(N) time.\"}],\"level_id\":1},{\"title\":\"Group Anagrams\",\"prompt\":\"Given N strings, group strings that are anagrams of each other. Print each group on a separate line. Words within each group should remain in their original input order.\",\"difficulty\":\"Medium\",\"type\":\"coding\",\"detail\":{\"constraints\":\"1 <= N <= 10^4\\n1 <= word.length <= 100\\nWords contain lowercase English letters.\\nTime Limit: 2.0s\\nMemory Limit: 256MB\",\"expected_approach\":\"Create a character-frequency signature for each word and use that signature as a HashMap key. Words with the same signature belong to the same group.\",\"expected_complexity\":\"Time: O(N * L), Space: O(N * L)\"},\"test_cases\":[{\"input\":\"6\\neat tea tan ate nat bat\",\"expected_output\":\"eat tea ate\\ntan nat\\nbat\",\"is_hidden\":false},{\"input\":\"5\\nabc cba bac xyz zyx\",\"expected_output\":\"abc cba bac\\nxyz zyx\",\"is_hidden\":true}],\"hints\":[{\"type\":\"hint\",\"content\":\"Anagrams have the same character frequencies.\"},{\"type\":\"interview_tip\",\"content\":\"Ask the candidate to compare a sorted-string key with a frequency-based key.\"}],\"level_id\":1},{\"title\":\"Longest Substring Without Repeating Characters\",\"prompt\":\"Given a string, find the length of the longest substring that contains no repeated characters.\",\"difficulty\":\"Medium\",\"type\":\"coding\",\"detail\":{\"constraints\":\"0 <= s.length <= 10^5\\ns consists of printable ASCII characters.\\nTime Limit: 2.0s\\nMemory Limit: 256MB\",\"expected_approach\":\"Use a sliding window with two pointers and a HashMap storing the most recent index of each character.\",\"expected_complexity\":\"Time: O(N), Space: O(K)\"},\"test_cases\":[{\"input\":\"abcabcbb\",\"expected_output\":\"3\",\"is_hidden\":false},{\"input\":\"pwwkew\",\"expected_output\":\"3\",\"is_hidden\":true}],\"hints\":[{\"type\":\"hint\",\"content\":\"Maintain a window that contains only unique characters.\"},{\"type\":\"interview_tip\",\"content\":\"Ask how the left pointer should move when a duplicate character is found.\"}],\"level_id\":1},{\"title\":\"Majority Element\",\"prompt\":\"Given an array of integers, find the element that appears more than N/2 times. A majority element is guaranteed to exist.\",\"difficulty\":\"Easy\",\"type\":\"coding\",\"detail\":{\"constraints\":\"1 <= N <= 10^5\\n-10^9 <= nums[i] <= 10^9\\nA majority element always exists.\\nTime Limit: 2.0s\\nMemory Limit: 256MB\",\"expected_approach\":\"Use the Boyer-Moore Voting Algorithm to maintain a candidate and a count while traversing the array.\",\"expected_complexity\":\"Time: O(N), Space: O(1)\"},\"test_cases\":[{\"input\":\"7\\n2 2 1 1 1 2 2\",\"expected_output\":\"2\",\"is_hidden\":false},{\"input\":\"5\\n3 3 4 3 3\",\"expected_output\":\"3\",\"is_hidden\":true}],\"hints\":[{\"type\":\"hint\",\"content\":\"You can first think about counting frequencies with a HashMap.\"},{\"type\":\"interview_tip\",\"content\":\"Ask whether the candidate can reduce the auxiliary space to O(1).\"}],\"level_id\":1},{\"title\":\"Longest Consecutive Sequence\",\"prompt\":\"Given an unsorted array of integers, find the length of the longest sequence of consecutive integers. The elements do not need to appear next to each other in the input array.\",\"difficulty\":\"Medium\",\"type\":\"coding\",\"detail\":{\"constraints\":\"0 <= N <= 10^5\\n-10^9 <= nums[i] <= 10^9\\nDuplicate values may exist.\\nTime Limit: 2.0s\\nMemory Limit: 256MB\",\"expected_approach\":\"Insert all values into a HashSet. Start counting a sequence only when the current value has no predecessor, then repeatedly check for the next consecutive value.\",\"expected_complexity\":\"Time: O(N) average, Space: O(N)\"},\"test_cases\":[{\"input\":\"6\\n100 4 200 1 3 2\",\"expected_output\":\"4\",\"is_hidden\":false},{\"input\":\"8\\n0 3 7 2 5 8 4 6\",\"expected_output\":\"7\",\"is_hidden\":true}],\"hints\":[{\"type\":\"hint\",\"content\":\"Try putting all numbers into a HashSet.\"},{\"type\":\"interview_tip\",\"content\":\"Ask why sorting is not required and how duplicates are handled.\"}],\"level_id\":1},{\"title\":\"Product of Array Except Self\",\"prompt\":\"Given an integer array, return an array where each position contains the product of every element except the element at that position. Division is not allowed.\",\"difficulty\":\"Medium\",\"type\":\"coding\",\"detail\":{\"constraints\":\"2 <= N <= 10^5\\n-30 <= nums[i] <= 30\\nThe result fits within a 32-bit signed integer.\\nTime Limit: 2.0s\\nMemory Limit: 256MB\",\"expected_approach\":\"Calculate prefix products from left to right and suffix products from right to left without using division.\",\"expected_complexity\":\"Time: O(N), Space: O(1) auxiliary excluding the output array\"},\"test_cases\":[{\"input\":\"4\\n1 2 3 4\",\"expected_output\":\"24 12 8 6\",\"is_hidden\":false},{\"input\":\"4\\n-1 1 0 -3\",\"expected_output\":\"0 0 3 0\",\"is_hidden\":true}],\"hints\":[{\"type\":\"hint\",\"content\":\"For every position, think about the product of elements on its left and right.\"},{\"type\":\"interview_tip\",\"content\":\"Ask why division is problematic when the array contains zero.\"}],\"level_id\":1},{\"title\":\"Subarray Sum Equals K\",\"prompt\":\"Given an integer array and an integer K, count the number of contiguous subarrays whose sum equals K.\",\"difficulty\":\"Medium\",\"type\":\"coding\",\"detail\":{\"constraints\":\"1 <= N <= 10^5\\n-10^4 <= nums[i] <= 10^4\\n-10^9 <= K <= 10^9\\nTime Limit: 2.0s\\nMemory Limit: 256MB\",\"expected_approach\":\"Maintain a running prefix sum and use a HashMap to store the frequency of previous prefix sums. For the current sum S, look for S - K.\",\"expected_complexity\":\"Time: O(N), Space: O(N)\"},\"test_cases\":[{\"input\":\"3\\n1 1 1\\n2\",\"expected_output\":\"2\",\"is_hidden\":false},{\"input\":\"3\\n1 -1 0\\n0\",\"expected_output\":\"3\",\"is_hidden\":true}],\"hints\":[{\"type\":\"hint\",\"content\":\"Think about prefix sums and what previous sum would be needed to produce K.\"},{\"type\":\"interview_tip\",\"content\":\"Ask why a normal sliding-window approach does not work when negative numbers are present.\"}],\"level_id\":1},{\"title\":\"Valid Parentheses\",\"prompt\":\"Given a string containing only (), {}, and [], determine whether the brackets are valid. Every opening bracket must have the correct closing bracket, and brackets must close in the correct order.\",\"difficulty\":\"Easy\",\"type\":\"coding\",\"detail\":{\"constraints\":\"1 <= s.length <= 10^5\\ns contains only (, ), {, }, [, ].\\nTime Limit: 2.0s\\nMemory Limit: 256MB\",\"expected_approach\":\"Use a stack to store opening brackets and verify that every closing bracket matches the most recently opened bracket.\",\"expected_complexity\":\"Time: O(N), Space: O(N)\"},\"test_cases\":[{\"input\":\"{[()]}\",\"expected_output\":\"true\",\"is_hidden\":false},{\"input\":\"([)]\",\"expected_output\":\"false\",\"is_hidden\":true}],\"hints\":[{\"type\":\"hint\",\"content\":\"The most recently opened bracket must be closed first.\"},{\"type\":\"interview_tip\",\"content\":\"Ask why a stack is suitable for this problem and what happens when a closing bracket appears with an empty stack.\"}],\"level_id\":1}]}','{\"created_count\":10,\"data\":[{\"id\":1,\"level_id\":1,\"title\":\"Two Sum with Target Lookup\",\"prompt\":\"Given an array of integers and a target integer, find the indices of two different elements whose sum equals the target. Print the two indices in increasing order. Exactly one valid pair exists.\",\"difficulty\":\"Easy\",\"type\":\"coding\",\"created_at\":\"2026-09-17T07:52:39.705Z\",\"updated_at\":\"2026-09-17T07:52:39.705Z\"},{\"id\":2,\"level_id\":1,\"title\":\"Valid Anagram\",\"prompt\":\"Given two strings, determine whether they are anagrams of each other. Two strings are anagrams if they contain exactly the same characters with the same frequencies.\",\"difficulty\":\"Easy\",\"type\":\"coding\",\"created_at\":\"2026-09-17T07:52:39.811Z\",\"updated_at\":\"2026-09-17T07:52:39.811Z\"},{\"id\":3,\"level_id\":1,\"title\":\"First Non-Repeating Character\",\"prompt\":\"Given a string, find the index of the first character that appears exactly once. If no such character exists, print -1.\",\"difficulty\":\"Easy\",\"type\":\"coding\",\"created_at\":\"2026-09-17T07:52:39.891Z\",\"updated_at\":\"2026-09-17T07:52:39.891Z\"},{\"id\":4,\"level_id\":1,\"title\":\"Group Anagrams\",\"prompt\":\"Given N strings, group strings that are anagrams of each other. Print each group on a separate line. Words within each group should remain in their original input order.\",\"difficulty\":\"Medium\",\"type\":\"coding\",\"created_at\":\"2026-09-17T07:52:39.974Z\",\"updated_at\":\"2026-09-17T07:52:39.974Z\"},{\"id\":5,\"level_id\":1,\"title\":\"Longest Substring Without Repeating Characters\",\"prompt\":\"Given a string, find the length of the longest substring that contains no repeated characters.\",\"difficulty\":\"Medium\",\"type\":\"coding\",\"created_at\":\"2026-09-17T07:52:40.051Z\",\"updated_at\":\"2026-09-17T07:52:40.051Z\"},{\"id\":6,\"level_id\":1,\"title\":\"Majority Element\",\"prompt\":\"Given an array of integers, find the element that appears more than N/2 times. A majority element is guaranteed to exist.\",\"difficulty\":\"Easy\",\"type\":\"coding\",\"created_at\":\"2026-09-17T07:52:40.12Z\",\"updated_at\":\"2026-09-17T07:52:40.12Z\"},{\"id\":7,\"level_id\":1,\"title\":\"Longest Consecutive Sequence\",\"prompt\":\"Given an unsorted array of integers, find the length of the longest sequence of consecutive integers. The elements do not need to appear next to each other in the input array.\",\"difficulty\":\"Medium\",\"type\":\"coding\",\"created_at\":\"2026-09-17T07:52:40.194Z\",\"updated_at\":\"2026-09-17T07:52:40.194Z\"},{\"id\":8,\"level_id\":1,\"title\":\"Product of Array Except Self\",\"prompt\":\"Given an integer array, return an array where each position contains the product of every element except the element at that position. Division is not allowed.\",\"difficulty\":\"Medium\",\"type\":\"coding\",\"created_at\":\"2026-09-17T07:52:40.252Z\",\"updated_at\":\"2026-09-17T07:52:40.252Z\"},{\"id\":9,\"level_id\":1,\"title\":\"Subarray Sum Equals K\",\"prompt\":\"Given an integer array and an integer K, count the number of contiguous subarrays whose sum equals K.\",\"difficulty\":\"Medium\",\"type\":\"coding\",\"created_at\":\"2026-09-17T07:52:40.307Z\",\"updated_at\":\"2026-09-17T07:52:40.307Z\"},{\"id\":10,\"level_id\":1,\"title\":\"Valid Parentheses\",\"prompt\":\"Given a string containing only (), {}, and [], determine whether the brackets are valid. Every opening bracket must have the correct closing bracket, and brackets must close in the correct order.\",\"difficulty\":\"Easy\",\"type\":\"coding\",\"created_at\":\"2026-09-17T07:52:40.371Z\",\"updated_at\":\"2026-09-17T07:52:40.371Z\"}],\"message\":\"Bulk upload complete: 10 questions created, 0 skipped\",\"skipped_count\":0,\"skipped_details\":null,\"status\":\"success\"}','','2026-09-17 07:52:39.684'),(185,2,'admin@bitsathy.ac.in','System Administrator','admin','GET','/api/v1/admin/interviews/tracks/1','','2a09:bac1:36c0:128::2a7:70','Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/153.0.0.0 Safari/537.36',200,8,'','{\"data\":{\"category\":\"Technical\",\"created_at\":\"2026-09-17T07:43:11Z\",\"description\":\"Core problem solving, arrays, trees, dynamic programming, and algorithmic complexity.\",\"icon\":\"Code\",\"id\":1,\"levels_count\":3,\"questions_count\":10,\"slug\":\"dsa\",\"title\":\"Data Structures \\u0026 Algorithms\",\"updated_at\":\"2026-09-17T07:43:11Z\"},\"status\":\"success\"}','','2026-09-17 07:52:40.572'),(186,2,'admin@bitsathy.ac.in','System Administrator','admin','GET','/api/v1/admin/interviews/levels/1','','2a09:bac1:36c0:128::2a7:70','Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/153.0.0.0 Safari/537.36',200,5,'','{\"data\":{\"created_at\":\"2026-09-17T07:44:11Z\",\"description\":\"Fundamental data structures and two-pointer techniques\",\"duration_minutes\":45,\"id\":1,\"level_number\":1,\"mode\":\"coding\",\"name\":\"Arrays, Strings \\u0026 HashMaps\",\"question_count\":1,\"questions_count\":10,\"track_id\":1,\"updated_at\":\"2026-09-17T07:44:25.437Z\"},\"status\":\"success\"}','','2026-09-17 07:52:40.576'),(187,2,'admin@bitsathy.ac.in','System Administrator','admin','GET','/api/v1/admin/interviews/levels/1/questions','','2a09:bac1:36c0:128::2a7:70','Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/153.0.0.0 Safari/537.36',200,40,'','{\"data\":[{\"id\":1,\"level_id\":1,\"title\":\"Two Sum with Target Lookup\",\"prompt\":\"Given an array of integers and a target integer, find the indices of two different elements whose sum equals the target. Print the two indices in increasing order. Exactly one valid pair exists.\",\"difficulty\":\"Easy\",\"type\":\"coding\",\"detail\":{\"id\":1,\"question_id\":1,\"constraints\":\"2 \\u003c= N \\u003c= 10^5\\n-10^9 \\u003c= nums[i] \\u003c= 10^9\\nExactly one valid answer exists.\\nTime Limit: 2.0s\\nMemory Limit: 256MB\",\"expected_approach\":\"Traverse the array once and use a HashMap to store previously visited numbers and their indices. For each number, check whether target - nums[i] already exists.\",\"expected_complexity\":\"Time: O(N), Space: O(N)\",\"ideal_answer\":\"\",\"scenario\":\"\",\"correct_option\":\"\",\"explanation\":\"\",\"created_at\":\"2026-09-17T07:52:39.716Z\",\"updated_at\":\"2026-09-17T07:52:39.716Z\"},\"test_cases\":[{\"id\":1,\"question_id\":1,\"input\":\"4\\n2 7 11 15\\n9\",\"expected_output\":\"0 1\",\"is_hidden\":false,\"explanation\":\"\",\"order_index\":1,\"created_at\":\"2026-09-17T07:52:39.741Z\",\"updated_at\":\"2026-09-17T07:52:39.741Z\"},{\"id\":2,\"question_id\":1,\"input\":\"5\\n3 3 8 2 10\\n6\",\"expected_output\":\"0 1\",\"is_hidden\":true,\"explanation\":\"\",\"order_index\":2,\"created_at\":\"2026-09-17T07:52:39.747Z\",\"updated_at\":\"2026-09-17T07:52:39.747Z\"}],\"hints\":[{\"id\":1,\"question_id\":1,\"type\":\"hint\",\"content\":\"Can you store already visited numbers and look for target - current number?\",\"order_index\":1,\"created_at\":\"2026-09-17T07:52:39.753Z\",\"updated_at\":\"2026-09-17T07:52:39.753Z\"},{\"id\":2,\"question_id\":1,\"type\":\"interview_tip\",\"content\":\"Ask why a nested-loop solution becomes O(N^2).\",\"order_index\":2,\"created_at\":\"2026-09-17T07:52:39.761Z\",\"updated_at\":\"2026-09-17T07:52:39.761Z\"}],\"created_at\":\"2026-09-17T07:52:39.705Z\",\"updated_at\":\"2026-09-17T07:52:39.705Z\"},{\"id\":2,\"level_id\":1,\"title\":\"Valid Anagram\",\"prompt\":\"Given two strings, determine whether they are anagrams of each other. Two strings are anagrams if they contain exactly the same characters with the same frequencies.\",\"difficulty\":\"Easy\",\"type\":\"coding\",\"detail\":{\"id\":2,\"question_id\":2,\"constraints\":\"1 \\u003c= s.length, t.length \\u003c= 10^5\\nStrings contain lowercase English letters.\\nTime Limit: 2.0s\\nMemory Limit: 256MB\",\"expected_approach\":\"Count the frequency of every character in the first string and compare it with the frequency of characters in the second string using a HashMap or frequency array.\",\"expected_complexity\":\"Time: O(N), Space: O(K)\",\"ideal_answer\":\"\",\"scenario\":\"\",\"correct_option\":\"\",\"explanation\":\"\",\"created_at\":\"2026-09-17T07:52:39.82Z\",\"updated_at\":\"2026-09-17T07:52:39.82Z\"},\"test_cases\":[{\"id\":3,\"question_id\":2,\"input\":\"anagram\\nnagaram\",\"expected_output\":\"true\",\"is_hidden\":false,\"explanation\":\"\",\"order_index\":1,\"created_at\":\"2026-09-17T07:52:39.831Z\",\"updated_at\":\"2026-09-17T07:52:39.831Z\"},{\"id\":4,\"question_id\":2,\"input\":\"rat\\ncar\",\"expected_output\":\"false\",\"is_hidden\":true,\"explanation\":\"\",\"order_index\":2,\"created_at\":\"2026-09-17T07:52:39.833Z\",\"updated_at\":\"2026-09-17T07:52:39.833Z\"}],\"hints\":[{\"id\":3,\"question_id\":2,\"type\":\"hint\",\"content\":\"Think about how to count the frequency of each character.\",\"order_index\":1,\"created_at\":\"2026-09-17T07:52:39.846Z\",\"updated_at\":\"2026-09-17T07:52:39.846Z\"},{\"id\":4,\"question_id\":2,\"type\":\"interview_tip\",\"content\":\"Ask whether sorting both strings is necessary and what its complexity would be.\",\"order_index\":2,\"created_at\":\"2026-09-17T07:52:39.848Z\",\"updated_at\":\"2026-09-17T07:52:39.848Z\"}],\"created_at\":\"2026-09-17T07:52:39.811Z\",\"updated_at\":\"2026-09-17T07:52:39.811Z\"},{\"id\":3,\"level_id\":1,\"title\":\"First Non-Repeating Character\",\"prompt\":\"Given a string, find the index of the first character that appears exactly once. If no such character exists, print -1.\",\"difficulty\":\"Easy\",\"type\":\"coding\",\"detail\":{\"id\":3,\"question_id\":3,\"constraints\":\"1 \\u003c= s.length \\u003c= 10^5\\ns consists of lowercase English letters.\\nTime Limit: 2.0s\\nMemory Limit: 256MB\",\"expected_approach\":\"Build a frequency map for all characters, then make a second pass through the string and return the index of the first character whose frequency is one.\",\"expected_complexity\":\"Time: O(N), Space: O(K)\",\"ideal_answer\":\"\",\"scenario\":\"\",\"correct_option\":\"\",\"explanation\":\"\",\"created_at\":\"2026-09-17T07:52:39.9Z\",\"updated_at\":\"2026-09-17T07:52:39.9Z\"},\"test_cases\":[{\"id\":5,\"question_id\":3,\"input\":\"leetcode\",\"expected_output\":\"0\",\"is_hidden\":false,\"explanation\":\"\",\"order_index\":1,\"created_at\":\"2026-09-17T07:52:39.915Z\",\"updated_at\":\"2026-09-17T07:52:39.915Z\"},{\"id\":6,\"question_id\":3,\"input\":\"aabbcc\",\"expected_output\":\"-1\",\"is_hidden\":true,\"explanation\":\"\",\"order_index\":2,\"created_at\":\"2026-09-17T07:52:39.917Z\",\"updated_at\":\"2026-09-17T07:52:39.917Z\"}],\"hints\":[{\"id\":5,\"question_id\":3,\"type\":\"hint\",\"content\":\"First count how many times every character occurs.\",\"order_index\":1,\"created_at\":\"2026-09-17T07:52:39.926Z\",\"updated_at\":\"2026-09-17T07:52:39.926Z\"},{\"id\":6,\"question_id\":3,\"type\":\"interview_tip\",\"content\":\"Ask why two passes still result in O(N) time.\",\"order_index\":2,\"created_at\":\"2026-09-17T07:52:39.932Z\",\"updated_at\":\"2026-09-17T07:52:39.932Z\"}],\"created_at\":\"2026-09-17T07:52:39.891Z\",\"updated_at\":\"2026-09-17T07:52:39.891Z\"},{\"id\":4,\"level_id\":1,\"title\":\"Group Anagrams\",\"prompt\":\"Given N strings, group strings that are anagrams of each other. Print each group on a separate line. Words within each group should remain in their original input order.\",\"difficulty\":\"Medium\",\"type\":\"coding\",\"detail\":{\"id\":4,\"question_id\":4,\"constraints\":\"1 \\u003c= N \\u003c= 10^4\\n1 \\u003c= word.length \\u003c= 100\\nWords contain lowercase English letters.\\nTime Limit: 2.0s\\nMemory Limit: 256MB\",\"expected_approach\":\"Create a character-frequency signature for each word and use that signature as a HashMap key. Words with the same signature belong to the same group.\",\"expected_complexity\":\"Time: O(N * L), Space: O(N * L)\",\"ideal_answer\":\"\",\"scenario\":\"\",\"correct_option\":\"\",\"explanation\":\"\",\"created_at\":\"2026-09-17T07:52:39.983Z\",\"updated_at\":\"2026-09-17T07:52:39.983Z\"},\"test_cases\":[{\"id\":7,\"question_id\":4,\"input\":\"6\\neat tea tan ate nat bat\",\"expected_output\":\"eat tea ate\\ntan nat\\nbat\",\"is_hidden\":false,\"explanation\":\"\",\"order_index\":1,\"created_at\":\"2026-09-17T07:52:39.988Z\",\"updated_at\":\"2026-09-17T07:52:39.988Z\"},{\"id\":8,\"question_id\":4,\"input\":\"5\\nabc cba bac xyz zyx\",\"expected_output\":\"abc cba bac\\nxyz zyx\",\"is_hidden\":true,\"explanation\":\"\",\"order_index\":2,\"created_at\":\"2026-09-17T07:52:39.994Z\",\"updated_at\":\"2026-09-17T07:52:39.994Z\"}],\"hints\":[{\"id\":7,\"question_id\":4,\"type\":\"hint\",\"content\":\"Anagrams have the same character frequencies.\",\"order_index\":1,\"created_at\":\"2026-09-17T07:52:40Z\",\"updated_at\":\"2026-09-17T07:52:40Z\"},{\"id\":8,\"question_id\":4,\"type\":\"interview_tip\",\"content\":\"Ask the candidate to compare a sorted-string key with a frequency-based key.\",\"order_index\":2,\"created_at\":\"2026-09-17T07:52:40.002Z\",\"updated_at\":\"2026-09-17T07:52:40.002Z\"}],\"created_at\":\"2026-09-17T07:52:39.974Z\",\"updated_at\":\"2026-09-17T07:52:39.974Z\"},{\"id\":5,\"level_id\":1,\"title\":\"Longest Substring Without Repeating Characters\",\"prompt\":\"Given a string, find the length of the longest substring that contains no repeated characters.\",\"difficulty\":\"Medium\",\"type\":\"coding\",\"detail\":{\"id\":5,\"question_id\":5,\"constraints\":\"0 \\u003c= s.length \\u003c= 10^5\\ns consists of printable ASCII characters.\\nTime Limit: 2.0s\\nMemory Limit: 256MB\",\"expected_approach\":\"Use a sliding window with two pointers and a HashMap storing the most recent index of each character.\",\"expected_complexity\":\"Time: O(N), Space: O(K)\",\"ideal_answer\":\"\",\"scenario\":\"\",\"correct_option\":\"\",\"explanation\":\"\",\"created_at\":\"2026-09-17T07:52:40.058Z\",\"updated_at\":\"2026-09-17T07:52:40.058Z\"},\"test_cases\":[{\"id\":9,\"question_id\":5,\"input\":\"abcabcbb\",\"expected_output\":\"3\",\"is_hidden\":false,\"explanation\":\"\",\"order_index\":1,\"created_at\":\"2026-09-17T07:52:40.069Z\",\"updated_at\":\"2026-09-17T07:52:40.069Z\"},{\"id\":10,\"question_id\":5,\"input\":\"pwwkew\",\"expected_output\":\"3\",\"is_hidden\":true,\"explanation\":\"\",\"order_index\":2,\"created_at\":\"2026-09-17T07:52:40.073Z\",\"updated_at\":\"2026-09-17T07:52:40.073Z\"}],\"hints\":[{\"id\":9,\"question_id\":5,\"type\":\"hint\",\"content\":\"Maintain a window that contains only unique characters.\",\"order_index\":1,\"created_at\":\"2026-09-17T07:52:40.083Z\",\"updated_at\":\"2026-09-17T07:52:40.083Z\"},{\"id\":10,\"question_id\":5,\"type\":\"interview_tip\",\"content\":\"Ask how the left pointer should move when a duplicate character is found.\",\"order_index\":2,\"created_at\":\"2026-09-17T07:52:40.085Z\",\"updated_at\":\"2026-09-17T07:52:40.085Z\"}],\"created_at\":\"2026-09-17T07:52:40.051Z\",\"updated_at\":\"2026-09-17T07:52:40.051Z\"},{\"id\":6,\"level_id\":1,\"title\":\"Majority Element\",\"prompt\":\"Given an array of integers, find the element that appears more than N/2 times. A majority element is guaranteed to exist.\",\"difficulty\":\"Easy\",\"type\":\"coding\",\"detail\":{\"id\":6,\"question_id\":6,\"constraints\":\"1 \\u003c= N \\u003c= 10^5\\n-10^9 \\u003c= nums[i] \\u003c= 10^9\\nA majority element always exists.\\nTime Limit: 2.0s\\nMemory Limit: 256MB\",\"expected_approach\":\"Use the Boyer-Moore Voting Algorithm to maintain a candidate and a count while traversing the array.\",\"expected_complexity\":\"Time: O(N), Space: O(1)\",\"ideal_answer\":\"\",\"scenario\":\"\",\"correct_option\":\"\",\"explanation\":\"\",\"created_at\":\"2026-09-17T07:52:40.131Z\",\"updated_at\":\"2026-09-17T07:52:40.131Z\"},\"test_cases\":[{\"id\":11,\"question_id\":6,\"input\":\"7\\n2 2 1 1 1 2 2\",\"expected_output\":\"2\",\"is_hidden\":false,\"explanation\":\"\",\"order_index\":1,\"created_at\":\"2026-09-17T07:52:40.145Z\",\"updated_at\":\"2026-09-17T07:52:40.145Z\"},{\"id\":12,\"question_id\":6,\"input\":\"5\\n3 3 4 3 3\",\"expected_output\":\"3\",\"is_hidden\":true,\"explanation\":\"\",\"order_index\":2,\"created_at\":\"2026-09-17T07:52:40.148Z\",\"updated_at\":\"2026-09-17T07:52:40.148Z\"}],\"hints\":[{\"id\":11,\"question_id\":6,\"type\":\"hint\",\"content\":\"You can first think about counting frequencies with a HashMap.\",\"order_index\":1,\"created_at\":\"2026-09-17T07:52:40.155Z\",\"updated_at\":\"2026-09-17T07:52:40.155Z\"},{\"id\":12,\"question_id\":6,\"type\":\"interview_tip\",\"content\":\"Ask whether the candidate can reduce the auxiliary space to O(1).\",\"order_index\":2,\"created_at\":\"2026-09-17T07:52:40.162Z\",\"updated_at\":\"2026-09-17T07:52:40.162Z\"}],\"created_at\":\"2026-09-17T07:52:40.12Z\",\"updated_at\":\"2026-09-17T07:52:40.12Z\"},{\"id\":7,\"level_id\":1,\"title\":\"Longest Consecutive Sequence\",\"prompt\":\"Given an unsorted array of integers, find the length of the longest sequence of consecutive integers. The elements do not need to appear next to each other in the input array.\",\"difficulty\":\"Medium\",\"type\":\"coding\",\"detail\":{\"id\":7,\"question_id\":7,\"constraints\":\"0 \\u003c= N \\u003c= 10^5\\n-10^9 \\u003c= nums[i] \\u003c= 10^9\\nDuplicate values may exist.\\nTime Limit: 2.0s\\nMemory Limit: 256MB\",\"expected_approach\":\"Insert all values into a HashSet. Start counting a sequence only when the current value has no predecessor, then repeatedly check for the next consecutive value.\",\"expected_complexity\":\"Time: O(N) average, Space: O(N)\",\"ideal_answer\":\"\",\"scenario\":\"\",\"correct_option\":\"\",\"explanation\":\"\",\"created_at\":\"2026-09-17T07:52:40.2Z\",\"updated_at\":\"2026-09-17T07:52:40.2Z\"},\"test_cases\":[{\"id\":13,\"question_id\":7,\"input\":\"6\\n100 4 200 1 3 2\",\"expected_output\":\"4\",\"is_hidden\":false,\"explanation\":\"\",\"order_index\":1,\"created_at\":\"2026-09-17T07:52:40.206Z\",\"updated_at\":\"2026-09-17T07:52:40.206Z\"},{\"id\":14,\"question_id\":7,\"input\":\"8\\n0 3 7 2 5 8 4 6\",\"expected_output\":\"7\",\"is_hidden\":true,\"explanation\":\"\",\"order_index\":2,\"created_at\":\"2026-09-17T07:52:40.212Z\",\"updated_at\":\"2026-09-17T07:52:40.212Z\"}],\"hints\":[{\"id\":13,\"question_id\":7,\"type\":\"hint\",\"content\":\"Try putting all numbers into a HashSet.\",\"order_index\":1,\"created_at\":\"2026-09-17T07:52:40.217Z\",\"updated_at\":\"2026-09-17T07:52:40.217Z\"},{\"id\":14,\"question_id\":7,\"type\":\"interview_tip\",\"content\":\"Ask why sorting is not required and how duplicates are handled.\",\"order_index\":2,\"created_at\":\"2026-09-17T07:52:40.217Z\",\"updated_at\":\"2026-09-17T07:52:40.217Z\"}],\"created_at\":\"2026-09-17T07:52:40.194Z\",\"updated_at\":\"2026-09-17T07:52:40.194Z\"},{\"id\":8,\"level_id\":1,\"title\":\"Product of Array Except Self\",\"prompt\":\"Given an integer array, return an array where each position contains the product of every element except the element at that position. Division is not allowed.\",\"difficulty\":\"Medium\",\"type\":\"coding\",\"detail\":{\"id\":8,\"question_id\":8,\"constraints\":\"2 \\u003c= N \\u003c= 10^5\\n-30 \\u003c= nums[i] \\u003c= 30\\nThe result fits within a 32-bit signed integer.\\nTime Limit: 2.0s\\nMemory Limit: 256MB\",\"expected_approach\":\"Calculate prefix products from left to right and suffix products from right to left without using division.\",\"expected_complexity\":\"Time: O(N), Space: O(1) auxiliary excluding the output array\",\"ideal_answer\":\"\",\"scenario\":\"\",\"correct_option\":\"\",\"explanation\":\"\",\"created_at\":\"2026-09-17T07:52:40.261Z\",\"updated_at\":\"2026-09-17T07:52:40.261Z\"},\"test_cases\":[{\"id\":15,\"question_id\":8,\"input\":\"4\\n1 2 3 4\",\"expected_output\":\"24 12 8 6\",\"is_hidden\":false,\"explanation\":\"\",\"order_index\":1,\"created_at\":\"2026-09-17T07:52:40.267Z\",\"updated_at\":\"2026-09-17T07:52:40.267Z\"},{\"id\":16,\"question_id\":8,\"input\":\"4\\n-1 1 0 -3\",\"expected_output\":\"0 0 3 0\",\"is_hidden\":true,\"explanation\":\"\",\"order_index\":2,\"created_at\":\"2026-09-17T07:52:40.268Z\",\"updated_at\":\"2026-09-17T07:52:40.268Z\"}],\"hints\":[{\"id\":15,\"question_id\":8,\"type\":\"hint\",\"content\":\"For every position, think about the product of elements on its left and right.\",\"order_index\":1,\"created_at\":\"2026-09-17T07:52:40.273Z\",\"updated_at\":\"2026-09-17T07:52:40.273Z\"},{\"id\":16,\"question_id\":8,\"type\":\"interview_tip\",\"content\":\"Ask why division is problematic when the array contains zero.\",\"order_index\":2,\"created_at\":\"2026-09-17T07:52:40.278Z\",\"updated_at\":\"2026-09-17T07:52:40.278Z\"}],\"created_at\":\"2026-09-17T07:52:40.252Z\",\"updated_at\":\"2026-09-17T07:52:40.252Z\"},{\"id\":9,\"level_id\":1,\"title\":\"Subarray Sum Equals K\",\"prompt\":\"Given an integer array and an integer K, count the number of contiguous subarrays whose sum equals K.\",\"difficulty\":\"Medium\",\"type\":\"coding\",\"detail\":{\"id\":9,\"question_id\":9,\"constraints\":\"1 \\u003c= N \\u003c= 10^5\\n-10^4 \\u003c= nums[i] \\u003c= 10^4\\n-10^9 \\u003c= K \\u003c= 10^9\\nTime Limit: 2.0s\\nMemory Limit: 256MB\",\"expected_approach\":\"Maintain a running prefix sum and use a HashMap to store the frequency of previous prefix sums. For the current sum S, look for S - K.\",\"expected_complexity\":\"Time: O(N), Space: O(N)\",\"ideal_answer\":\"\",\"scenario\":\"\",\"correct_option\":\"\",\"explanation\":\"\",\"created_at\":\"2026-09-17T07:52:40.316Z\",\"updated_at\":\"2026-09-17T07:52:40.316Z\"},\"test_cases\":[{\"id\":17,\"question_id\":9,\"input\":\"3\\n1 1 1\\n2\",\"expected_output\":\"2\",\"is_hidden\":false,\"explanation\":\"\",\"order_index\":1,\"created_at\":\"2026-09-17T07:52:40.322Z\",\"updated_at\":\"2026-09-17T07:52:40.322Z\"},{\"id\":18,\"question_id\":9,\"input\":\"3\\n1 -1 0\\n0\",\"expected_output\":\"3\",\"is_hidden\":true,\"explanation\":\"\",\"order_index\":2,\"created_at\":\"2026-09-17T07:52:40.328Z\",\"updated_at\":\"2026-09-17T07:52:40.328Z\"}],\"hints\":[{\"id\":17,\"question_id\":9,\"type\":\"hint\",\"content\":\"Think about prefix sums and what previous sum would be needed to produce K.\",\"order_index\":1,\"created_at\":\"2026-09-17T07:52:40.334Z\",\"updated_at\":\"2026-09-17T07:52:40.334Z\"},{\"id\":18,\"question_id\":9,\"type\":\"interview_tip\",\"content\":\"Ask why a normal sliding-window approach does not work when negative numbers are present.\",\"order_index\":2,\"created_at\":\"2026-09-17T07:52:40.335Z\",\"updated_at\":\"2026-09-17T07:52:40.335Z\"}],\"created_at\":\"2026-09-17T07:52:40.307Z\",\"updated_at\":\"2026-09-17T07:52:40.307Z\"},{\"id\":10,\"level_id\":1,\"title\":\"Valid Parentheses\",\"prompt\":\"Given a string containing only (), {}, and [], determine whether the brackets are valid. Every opening bracket must have the correct closing bracket, and brackets must close in the correct order.\",\"difficulty\":\"Easy\",\"type\":\"coding\",\"detail\":{\"id\":10,\"question_id\":10,\"constraints\":\"1 \\u003c= s.length \\u003c= 10^5\\ns contains only (, ), {, }, [, ].\\nTime Limit: 2.0s\\nMemory Limit: 256MB\",\"expected_approach\":\"Use a stack to store opening brackets and verify that every closing bracket matches the most recently opened bracket.\",\"expected_complexity\":\"Time: O(N), Space: O(N)\",\"ideal_answer\":\"\",\"scenario\":\"\",\"correct_option\":\"\",\"explanation\":\"\",\"created_at\":\"2026-09-17T07:52:40.382Z\",\"updated_at\":\"2026-09-17T07:52:40.382Z\"},\"test_cases\":[{\"id\":19,\"question_id\":10,\"input\":\"{[()]}\",\"expected_output\":\"true\",\"is_hidden\":false,\"explanation\":\"\",\"order_index\":1,\"created_at\":\"2026-09-17T07:52:40.388Z\",\"updated_at\":\"2026-09-17T07:52:40.388Z\"},{\"id\":20,\"question_id\":10,\"input\":\"([)]\",\"expected_output\":\"false\",\"is_hidden\":true,\"explanation\":\"\",\"order_index\":2,\"created_at\":\"2026-09-17T07:52:40.395Z\",\"updated_at\":\"2026-09-17T07:52:40.395Z\"}],\"hints\":[{\"id\":19,\"question_id\":10,\"type\":\"hint\",\"content\":\"The most recently opened bracket must be closed first.\",\"order_index\":1,\"created_at\":\"2026-09-17T07:52:40.401Z\",\"updated_at\":\"2026-09-17T07:52:40.401Z\"},{\"id\":20,\"question_id\":10,\"type\":\"interview_tip\",\"content\":\"Ask why a stack is suitable for this problem and what happens when a closing bracket appears with an empty stack.\",\"order_index\":2,\"created_at\":\"2026-09-17T07:52:40.402Z\",\"updated_at\":\"2026-09-17T07:52:40.402Z\"}],\"created_at\":\"2026-09-17T07:52:40.371Z\",\"updated_at\":\"2026-09-17T07:52:40.371Z\"}],\"status\":\"success\"}','','2026-09-17 07:52:40.632'),(188,2,'admin@bitsathy.ac.in','System Administrator','admin','GET','/api/v1/admin/interviews/tracks/1','','2a09:bac1:36c0:128::2a7:70','Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/153.0.0.0 Safari/537.36',200,4,'','{\"data\":{\"category\":\"Technical\",\"created_at\":\"2026-09-17T07:43:11Z\",\"description\":\"Core problem solving, arrays, trees, dynamic programming, and algorithmic complexity.\",\"icon\":\"Code\",\"id\":1,\"levels_count\":3,\"questions_count\":10,\"slug\":\"dsa\",\"title\":\"Data Structures \\u0026 Algorithms\",\"updated_at\":\"2026-09-17T07:43:11Z\"},\"status\":\"success\"}','','2026-09-17 07:52:47.122'),(189,2,'admin@bitsathy.ac.in','System Administrator','admin','GET','/api/v1/admin/interviews/levels/1','','2a09:bac1:36c0:128::2a7:70','Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/153.0.0.0 Safari/537.36',200,6,'','{\"data\":{\"created_at\":\"2026-09-17T07:44:11Z\",\"description\":\"Fundamental data stru