747Z\"}],\"hints\":[{\"id\":1,\"question_id\":1,\"type\":\"hint\",\"content\":\"Can you store already visited numbers and look for target - current number?\",\"order_index\":1,\"created_at\":\"2026-09-17T07:52:39.753Z\",\"updated_at\":\"2026-09-17T07:52:39.753Z\"},{\"id\":2,\"question_id\":1,\"type\":\"interview_tip\",\"content\":\"Ask why a nested-loop solution becomes O(N^2).\",\"order_index\":2,\"created_at\":\"2026-09-17T07:52:39.761Z\",\"updated_at\":\"2026-09-17T07:52:39.761Z\"}],\"created_at\":\"2026-09-17T07:52:39.705Z\",\"updated_at\":\"2026-09-17T07:52:39.705Z\"},\"status\":\"success\"}','','2026-09-17 07:52:47.169'),(191,2,'admin@bitsathy.ac.in','System Administrator','admin','GET','/api/v1/admin/interviews/tracks/1','','2a09:bac1:36c0:128::2a7:70','Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/153.0.0.0 Safari/537.36',200,4,'','{\"data\":{\"category\":\"Technical\",\"created_at\":\"2026-09-17T07:43:11Z\",\"description\":\"Core problem solving, arrays, trees, dynamic programming, and algorithmic complexity.\",\"icon\":\"Code\",\"id\":1,\"levels_count\":3,\"questions_count\":10,\"slug\":\"dsa\",\"title\":\"Data Structures \\u0026 Algorithms\",\"updated_at\":\"2026-09-17T07:43:11Z\"},\"status\":\"success\"}','','2026-09-17 07:53:05.302'),(192,2,'admin@bitsathy.ac.in','System Administrator','admin','GET','/api/v1/admin/interviews/levels/1','','2a09:bac1:36c0:128::2a7:70','Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/153.0.0.0 Safari/537.36',200,1,'','{\"data\":{\"created_at\":\"2026-09-17T07:44:11Z\",\"description\":\"Fundamental data structures and two-pointer techniques\",\"duration_minutes\":45,\"id\":1,\"level_number\":1,\"mode\":\"coding\",\"name\":\"Arrays, Strings \\u0026 HashMaps\",\"question_count\":1,\"questions_count\":10,\"track_id\":1,\"updated_at\":\"2026-09-17T07:44:25.437Z\"},\"status\":\"success\"}','','2026-09-17 07:53:05.349'),(193,2,'admin@bitsathy.ac.in'