questions_count\":0,\"slug\":\"system-design\",\"title\":\"System Design \\u0026 Architecture\",\"updated_at\":\"2026-09-17T07:43:11Z\"},\"status\":\"success\"}','','2026-09-17 07:54:17.892'),(211,2,'admin@bitsathy.ac.in','System Administrator','admin','GET','/api/v1/admin/interviews/tracks/2','','2a09:bac1:36c0:128::2a7:70','Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/153.0.0.0 Safari/537.36',200,6,'','{\"data\":{\"category\":\"Architecture\",\"created_at\":\"2026-09-17T07:43:11Z\",\"description\":\"Scalable distributed systems, load balancers, caching, microservices, and whiteboard diagrams.\",\"icon\":\"Layers\",\"id\":2,\"levels_count\":2,\"questions_count\":0,\"slug\":\"system-design\",\"title\":\"System Design \\u0026 Architecture\",\"updated_at\":\"2026-09-17T07:43:11Z\"},\"status\":\"success\"}','','2026-09-17 07:55:02.418'),(212,2,'admin@bitsathy.ac.in','System Administrator','admin','GET','/api/v1/admin/interviews/levels/4/questions','','2a09:bac1:36c0:128::2a7:70','Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/153.0.0.0 Safari/537.36',200,5,'','{\"data\":[],\"status\":\"success\"}','','2026-09-17 07:55:02.467'),(213,2,'admin@bitsathy.ac.in','System Administrator','admin','GET','/api/v1/admin/interviews/levels/4','','2a09:bac1:36c0:128::2a7:70','Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/153.0.0.0 Safari/537.36',200,6,'','{\"data\":{\"created_at\":\"2026-09-17T07:44:11Z\",\"description\":\"Designing scalable URL shorteners, rate limiters, and cache layers\",\"duration_minutes\":45,\"id\":4,\"level_number\":1,\"mode\":\"whiteboard\",\"name\":\"High-Level System Design\",\"question_count\":1,\"questions_count\":0,\"track_id\":2,\"updated_at\":\"2026-09-17T07:44:11Z\"},\"status\":\"success\"}','','2026-09-17 07:55:02.467'),(214,2,'admin@bitsathy.ac.in','System Administrator','admin','POST','/api/v1/admin/interviews/levels/4/questions/bulk','','2a09:bac1:36c0:128::2a7:70','Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/153.0.0.0 Safari/537.36',200,696,'{\"questions\":[{\"title\":\"Design a URL Shortener\",\"prompt\":\"Design a scalable URL shortening service that converts long URLs into short aliases and redirects users to the original URL.\",\"difficulty\":\"Medium\",\"type\":\"whiteboard\",\"detail\":{\"scenario\":\"500M new URLs per month and 50B redirects per month. Read/write ratio is approximately 100:1. Redirect latency should be below 10ms with 99.99% availability.\"},\"hints\":[{\"type\":\"talking_point\",\"content\":\"Consider Base62 encoding with a distributed ID generator for creating short URLs.\"},{\"type\":\"talking_point\",\"content\":\"Use Redis caching for frequently accessed short URLs.\"},{\"type\":\"tradeoff\",\"content\":\"Discuss 301 versus 302 redirects and their impact on caching, server load, and analytics.\"},{\"type\":\"interview_tip\",\"content\":\"Ask how the database should be sharded as the number of URLs grows.\"}],\"level_id\":4},{\"title\":\"Design a Real-Time Chat System\",\"prompt\":\"Design a real-time messaging platform that supports one-to-one and group conversations with message delivery, online presence, and message history.\",\"difficulty\":\"Medium\",\"type\":\"whiteboard\",\"detail\":{\"scenario\":\"10M daily active users with up to 1M concurrent connections. Messages should normally be delivered within 500ms. The system must support message persistence and temporary offline users.\"},\"hints\":[{\"type\":\"talking_point\",\"content\":\"Consider WebSockets for persistent real-time connections.\"},{\"type\":\"talking_point\",\"content\":\"Use a message queue such as Kafka to decouple message ingestion from delivery.\"},{\"type\":\"tradeoff\",\"content\":\"Discuss at-most-once, at-least-once, and effectively-once message delivery.\"},{\"type\":\"interview_tip\",\"content\":\"Ask how messages are delivered when the recipient is temporarily offline.\"}],\"level_id\":4},{\"title\":\"Design a Video Streaming Platform\",\"prompt\":\"Design a video streaming service where users can upload videos, browse available content, and stream videos with minimal buffering.\",\"difficulty\":\"Medium\",\"type\":\"whiteboard\",\"detail\":{\"scenario\":\"5M daily active users and 500K video uploads per day. Popular videos may receive millions of views. The system should support adaptive streaming and high availability.\"},\"hints\":[{\"type\":\"talking_point\",\"content\":\"Use object storage for video files and a CDN for global delivery.\"},{\"type\":\"talking_point\",\"content\":\"Transcode uploaded videos into multiple resolutions and bitrates.\"},{\"type\":\"tradeoff\",\"content\":\"Discuss storage cost versus video quality and the number of generated resolutions.\"},{\"type\":\"interview_tip\",\"content\":\"Ask how the system handles a sudden traffic spike for a viral video.\"}],\"level_id\":4},{\"title\":\"Design an Online Food Delivery System\",\"prompt\":\"Design an online food delivery platform where customers can discover restaurants, place orders, make payments, and track delivery status in real time.\",\"difficulty\":\"Medium\",\"type\":\"whiteboard\",\"detail\":{\"scenario\":\"2M daily users, 100K concurrent users during peak hours, and 200K orders per day. Order creation and payment operations require strong consistency while restaurant discovery can tolerate eventual consistency.\"},\"hints\":[{\"type\":\"talking_point\",\"content\":\"Separate order management, payment, restaurant, and delivery services.\"},{\"type\":\"talking_point\",\"content\":\"Use asynchronous events for order status updates and delivery tracking.\"},{\"type\":\"tradeoff\",\"content\":\"Discuss strong consistency for orders and payments versus eventual consistency for restaurant availability and tracking.\"},{\"type\":\"interview_tip\",\"content\":\"Ask how duplicate payment requests and duplicate orders are prevented.\"}],\"level_id\":4},{\"title\":\"Design a Ride-Sharing System\",\"prompt\":\"Design a ride-sharing platform that allows passengers to request rides, matches them with nearby drivers, and tracks rides in real time.\",\"difficulty\":\"Hard\",\"type\":\"whiteboard\",\"detail\":{\"scenario\":\"5M daily active users and 500K concurrent drivers. Location updates can arrive every few seconds. Ride matching should normally complete within 2 seconds.\"},\"hints\":[{\"type\":\"talking_point\",\"content\":\"Use geospatial indexing to find nearby available drivers efficiently.\"},{\"type\":\"talking_point\",\"content\":\"Use WebSockets or similar persistent connections for real-time location updates.\"},{\"type\":\"tradeoff\",\"content\":\"Discuss location-update frequency versus network, CPU, and storage costs.\"},{\"type\":\"interview_tip\",\"content\":\"Ask how the system prevents two passengers from being assigned the same driver.\"}],\"level_id\":4},{\"title\":\"Design a Distributed Rate Limiter\",\"prompt\":\"Design a distributed rate-limiting service that protects APIs from excessive requests while supporting multiple application servers.\",\"difficulty\":\"Medium\",\"type\":\"whiteboard\",\"detail\":{\"scenario\":\"The platform receives 1M requests per second across multiple regions. Different APIs may have different limits per user, IP address, or API key. Rate-limit decisions should normally complete within 5ms.\"},\"hints\":[{\"type\":\"talking_point\",\"content\":\"Consider token bucket or sliding-window algorithms.\"},{\"type\":\"talking_point\",\"content\":\"Use Redis or another distributed store for shared counters.\"},{\"type\":\"tradeoff\",\"content\":\"Discuss exact global limits versus local limits with lower latency.\"},{\"type\":\"interview_tip\",\"content\":\"Ask what happens when the Redis cluster becomes temporarily unavailable.\"}],\"level_id\":4},{\"title\":\"Design a Notification System\",\"prompt\":\"Design a notification platform capable of sending push notifications, emails, and SMS messages based on events generated by different applications.\",\"difficulty\":\"Medium\",\"type\":\"whiteboard\",\"detail\":{\"scenario\":\"100M notifications per day with large traffic bursts. Notifications should be processed asynchronously, retried when providers fail, and should not block the application\'s main request path.\"},\"hints\":[{\"type\":\"talking_point\",\"content\":\"Use a message queue between event producers and notification workers.\"},{\"type\":\"talking_point\",\"content\":\"Use retry queues and dead-letter queues for failed notifications.\"},{\"type\":\"tradeoff\",\"content\":\"Discuss delivery guarantees versus duplicate notifications.\"},{\"type\":\"interview_tip\",\"content\":\"Ask how notification preferences and user-specific rate limits should be enforced.\"}],\"level_id\":4},{\"title\":\"Design a Distributed File Storage System\",\"prompt\":\"Design a cloud file-storage service where users can upload, download, organize, and share files across multiple devices.\",\"difficulty\":\"Hard\",\"type\":\"whiteboard\",\"detail\":{\"scenario\":\"50M users with 10PB of stored data. Individual files can range from a few KB to several GB. The system must provide durable storage and efficient downloads.\"},\"hints\":[{\"type\":\"talking_point\",\"content\":\"Use object storage with metadata stored separately in a database.\"},{\"type\":\"talking_point\",\"content\":\"Consider multipart uploads for large files and CDN caching for frequently downloaded files.\"},{\"type\":\"tradeoff\",\"content\":\"Discuss replication level, durability, storage cost, and access latency.\"},{\"type\":\"interview_tip\",\"content\":\"Ask how concurrent updates to the same file should be handled.\"}],\"level_id\":4},{\"title\":\"Design an E-Commerce Platform\",\"prompt\":\"Design a scalable e-commerce platform where users can browse products, search inventory, add items to carts, place orders, and complete payments.\",\"difficulty\":\"Medium\",\"type\":\"whiteboard\",\"detail\":{\"scenario\":\"10M daily users with 100K concurrent users during major sales. Product browsing is read-heavy, while inventory and order operations require strong consistency.\"},\"hints\":[{\"type\":\"talking_point\",\"content\":\"Use caching and read replicas for high-volume product browsing.\"},{\"type\":\"talking_point\",\"content\":\"Use atomic inventory operations to prevent overselling during high-demand sales.\"},{\"type\":\"tradeoff\",\"content\":\"Discuss database consistency versus availability for inventory and product information.\"},{\"type\":\"interview_tip\",\"content\":\"Ask how the system handles thousands of users attempting to purchase the last item simultaneously.\"}],\"level_id\":4},{\"title\":\"Design a Real-Time Collaborative Document Editor\",\"prompt\":\"Architect a real-time collaborative text editor that allows multiple users to edit the same document simultaneously while resolving conflicts and maintaining document history.\",\"difficulty\":\"Hard\",\"type\":\"whiteboard\",\"detail\":{\"scenario\":\"100 active collaborators per document with typing latency below 50ms. The system must support document revisions, concurrent edits, and users reconnecting after temporary network failures.\"},\"hints\":[{\"type\":\"talking_point\",\"content\":\"Consider Operational Transformation or Conflict-free Replicated Data Types for concurrent editing.\"},{\"type\":\"talking_point\",\"content\":\"Use WebSockets for real-time updates and a persistent store for document snapshots and history.\"},{\"type\":\"tradeoff\",\"content\":\"Discuss centralized operation ordering with OT versus client-side convergence with CRDTs.\"},{\"type\":\"interview_tip\",\"content\":\"Ask how document snapshotting prevents replaying a very large number of historical operations.\"}],\"level_id\":4}]}','{\"created_count\":10,\"data\":[{\"id\":11,\"level_id\":4,\"title\":\"Design a URL Shortener\",\"prompt\":\"Design a scalable URL shortening service that converts long URLs into short aliases and redirects users to the original URL.\",\"difficulty\":\"Medium\",\"type\":\"whiteboard\",\"created_at\":\"2026-09-17T07:55:23.367Z\",\"updated_at\":\"2026-09-17T07:55:23.367Z\"},{\"id\":12,\"level_id\":4,\"title\":\"Design a Real-Time Chat System\",\"prompt\":\"Design a real-time messaging platform that supports one-to-one and group conversations with message delivery, online presence, and message history.\",\"difficulty\":\"Medium\",\"type\":\"whiteboard\",\"created_at\":\"2026-09-17T07:55:23.431Z\",\"updated_at\":\"2026-09-17T07:55:23.431Z\"},{\"id\":13,\"level_id\":4,\"title\":\"Design a Video Streaming Platform\",\"prompt\":\"Design a video streaming service where users can upload videos, browse available content, and stream videos with minimal buffering.\",\"difficulty\":\"Medium\",\"type\":\"whiteboard\",\"created_at\":\"2026-09-17T07:55:23.477Z\",\"updated_at\":\"2026-09-17T07:55:23.477Z\"},{\"id\":14,\"level_id\":4,\"title\":\"Design an Online Food Delivery System\",\"prompt\":\"Design an online food delivery platform where customers can discover restaurants, place orders, make payments, and track delivery status in real time.\",\"difficulty\":\"Medium\",\"type\":\"whiteboard\",\"created_at\":\"2026-09-17T07:55:23.525Z\",\"updated_at\":\"2026-09-17T07:55:23.525Z\"},{\"id\":15,\"level_id\":4,\"title\":\"Design a Ride-Sharing System\",\"prompt\":\"Design a ride-sharing platform that allows passengers to request rides, matches them with nearby drivers, and tracks rides in real time.\",\"difficulty\":\"Hard\",\"type\":\"whiteboard\",\"created_at\":\"2026-09-17T07:55:23.618Z\",\"updated_at\":\"2026-09-17T07:55:23.618Z\"},{\"id\":16,\"level_id\":4,\"title\":\"Design a Distributed Rate Limiter\",\"prompt\":\"Design a distributed rate-limiting service that protects APIs from excessive requests while supporting multiple application servers.\",\"difficulty\":\"Medium\",\"type\":\"whiteboard\",\"created_at\":\"2026-09-17T07:55:23.717Z\",\"updated_at\":\"2026-09-17T07:55:23.717Z\"},{\"id\":17,\"level_id\":4,\"title\":\"Design a Notification System\",\"prompt\":\"Design a notification platform capable of sending push notifications, emails, and SMS messages based on events generated by different applications.\",\"difficulty\":\"Medium\",\"type\":\"whiteboard\",\"created_at\":\"2026-09-17T07:55:23.811Z\",\"updated_at\":\"2026-09-17T07:55:23.811Z\"},{\"id\":18,\"level_id\":4,\"title\":\"Design a Distributed File Storage System\",\"prompt\":\"Design a cloud file-storage service where users can upload, download, organize, and share files across multiple devices.\",\"difficulty\":\"Hard\",\"type\":\"whiteboard\",\"created_at\":\"2026-09-17T07:55:23.87Z\",\"updated_at\":\"2026-09-17T07:55:23.87Z\"},{\"id\":19,\"level_id\":4,\"title\":\"Design an E-Commerce Platform\",\"prompt\":\"Design a scalable e-commerce platform where users can browse products, search inventory, add items to carts, place orders, and complete payments.\",\"difficulty\":\"Medium\",\"type\":\"whiteboard\",\"created_at\":\"2026-09-17T07:55:23.935Z\",\"updated_at\":\"2026-09-17T07:55:23.935Z\"},{\"id\":20,\"level_id\":4,\"title\":\"Design a Real-Time Collaborative Document Editor\",\"prompt\":\"Architect a real-time collaborative text editor that allows multiple users to edit the same document simultaneously while resolving conflicts and maintaining document history.\",\"difficulty\":\"Hard\",\"type\":\"whiteboard\",\"created_at\":\"2026-09-17T07:55:23.988Z\",\"updated_at\":\"2026-09-17T07:55:23.988Z\"}],\"message\":\"Bulk upload complete: 10 questions created, 0 skipped\",\"skipped_count\":0,\"skipped_details\":null,\"status\":\"success\"}','','2026-09-17 07:55:23.365'),(215,2,'admin@bitsathy.ac.in','System Administrator','admin','GET','/api/v1/admin/interviews/levels/4','','2a09:bac1:36c0:128::2a7:70','Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/153.0.0.0 Safari/537.36',200,3,'','{\"data\":{\"created_at\":\"2026-09-17T07:44:11Z\",\"description\":\"Designing scalable URL shorteners, rate limiters, and cache layers\",\"duration_minutes\":45,\"id\":4,\"level_number\":1,\"mode\":\"whiteboard\",\"name\":\"High-Level System Design\",\"question_count\":1,\"questions_count\":10,\"track_id\":2,\"updated_at\":\"2026-09-17T07:44:11Z\"},\"status\":\"success\"}','','2026-09-17 07:55:24.237'),(216,2,'admin@bitsathy.ac.in','System Administrator','admin','GET','/api/v1/admin/interviews/tracks/2','','2a09:bac1:36c0:128::2a7:70','Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/153.0.0.0 Safari/537.36',200,15,'','{\"data\":{\"category\":\"Architecture\",\"created_at\":\"2026-09-17T07:43:11Z\",\"description\":\"Scalable distributed systems, load balancers, caching, microservices, and whiteboard diagrams.\",\"icon\":\"Layers\",\"id\":2,\"levels_count\":2,\"questions_count\":10,\"slug\":\"system-design\",\"title\":\"System Design \\u0026 Architecture\",\"updated_at\":\"2026-09-17T07:43:11Z\"},\"status\":\"success\"}','','2026-09-17 07:55:24.335'),(217,2,'admin@bitsathy.ac.in','System Administrator','admin','GET','/api/v1/admin/interviews/levels/4/questions','','2a09:bac1:36c0:128::2a7:70','Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/153.0.0.0 Safari/537.36',200,32,'','{\"data\":[{\"id\":11,\"level_id\":4,\"title\":\"Design a URL Shortener\",\"prompt\":\"Design a scalable URL shortening service that converts long URLs into short aliases and redirects users to the original URL.\",\"difficulty\":\"Medium\",\"type\":\"whiteboard\",\"detail\":{\"id\":11,\"question_id\":11,\"constraints\":\"\",\"expected_approach\":\"\",\"expected_complexity\":\"\",\"ideal_answer\":\"\",\"scenario\":\"500M new URLs per month and 50B redirects per month. Read/write ratio is approximately 100:1. Redirect latency should be below 10ms with 99.99% availability.\",\"correct_option\":\"\",\"explanation\":\"\",\"created_at\":\"2026-09-17T07:55:23.376Z\",\"updated_at\":\"2026-09-17T07:55:23.376Z\"},\"hints\":[{\"id\":21,\"question_id\":11,\"type\":\"talking_point\",\"content\":\"Consider Base62 encoding with a distributed ID generator for creating short URLs.\",\"order_index\":1,\"created_at\":\"2026-09-17T07:55:23.382Z\",\"updated_at\":\"2026-09-17T07:55:23.382Z\"},{\"id\":22,\"question_id\":11,\"type\":\"talking_point\",\"content\":\"Use Redis caching for frequently accessed short URLs.\",\"order_index\":2,\"created_at\":\"2026-09-17T07:55:23.383Z\",\"updated_at\":\"2026-09-17T07:55:23.383Z\"},{\"id\":23,\"question_id\":11,\"type\":\"tradeoff\",\"content\":\"Discuss 301 versus 302 redirects and their impact on caching, server load, and analytics.\",\"order_index\":3,\"created_at\":\"2026-09-17T07:55:23.384Z\",\"updated_at\":\"2026-09-17T07:55:23.384Z\"},{\"id\":24,\"question_id\":11,\"type\":\"interview_tip\",\"content\":\"Ask how the database should be sharded as the number of URLs grows.\",\"order_index\":4,\"created_at\":\"2026-09-17T07:55:23.385Z\",\"updated_at\":\"2026-09-17T07:55:23.385Z\"}],\"created_at\":\"2026-09-17T07:55:23.367Z\",\"updated_at\":\"2026-09-17T07:55:23.367Z\"},{\"id\":12,\"level_id\":4,\"title\":\"Design a Real-Time Chat System\",\"prompt\":\"Design a real-time messaging platform that supports one-to-one and group conversations with message delivery, online presence, and message history.\",\"difficulty\":\"Medium\",\"type\":\"whiteboard\",\"detail\":{\"id\":12,\"question_id\":12,\"constraints\":\"\",\"expected_approach\":\"\",\"expected_complexity\":\"\",\"ideal_answer\":\"\",\"scenario\":\"10M daily active users with up to 1M concurrent connections. Messages should normally be delivered within 500ms. The system must support message persistence and temporary offline users.\",\"correct_option\":\"\",\"explanation\":\"\",\"created_at\":\"2026-09-17T07:55:23.432Z\",\"updated_at\":\"2026-09-17T07:55:23.432Z\"},\"hints\":[{\"id\":25,\"question_id\":12,\"type\":\"talking_point\",\"content\":\"Consider WebSockets for persistent real-time connections.\",\"order_index\":1,\"created_at\":\"2026-09-17T07:55:23.436Z\",\"updated_at\":\"2026-09-17T07:55:23.436Z\"},{\"id\":26,\"question_id\":12,\"type\":\"talking_point\",\"content\":\"Use a message queue such as Kafka to decouple message ingestion from delivery.\",\"order_index\":2,\"created_at\":\"2026-09-17T07:55:23.445Z\",\"updated_at\":\"2026-09-17T07:55:23.445Z\"},{\"id\":27,\"question_id\":12,\"type\":\"tradeoff\",\"content\":\"Discuss at-most-once, at-least-once, and effectively-once message delivery.\",\"order_index\":3,\"created_at\":\"2026-09-17T07:55:23.446Z\",\"updated_at\":\"2026-09-17T07:55:23.446Z\"},{\"id\":28,\"question_id\":12,\"type\":\"interview_tip\",\"content\":\"Ask how messages are delivered when the recipient is temporarily offline.\",\"order_index\":4,\"created_at\":\"2026-09-17T07:55:23.447Z\",\"updated_at\":\"2026-09-17T07:55:23.447Z\"}],\"created_at\":\"2026-09-17T07:55:23.431Z\",\"updated_at\":\"2026-09-17T07:55:23.431Z\"},{\"id\":13,\"level_id\":4,\"title\":\"Design a Video Streaming Platform\",\"prompt\":\"Design a video streaming service where users can upload videos, browse available content, and stream videos with minimal buffering.\",\"difficulty\":\"Medium\",\"type\":\"whiteboard\",\"detail\":{\"id\":13,\"question_id\":13,\"constraints\":\"\",\"expected_approach\":\"\",\"expected_complexity\":\"\",\"ideal_answer\":\"\",\"scenario\":\"5M daily active users and 500K video uploads per day. Popular videos may receive millions of views. The system should support adaptive streaming and high availability.\",\"correct_option\":\"\",\"explanation\":\"\",\"created_at\":\"2026-09-17T07:55:23.48Z\",\"updated_at\":\"2026-09-17T07:55:23.48Z\"},\"hints\":[{\"id\":29,\"question_id\":13,\"type\":\"talking_point\",\"content\":\"Use object storage for video files and a CDN for global delivery.\",\"order_index\":1,\"created_at\":\"2026-09-17T07:55:23.483Z\",\"updated_at\":\"2026-09-17T07:55:23.483Z\"},{\"id\":30,\"question_id\":13,\"type\":\"talking_point\",\"content\":\"Transcode uploaded videos into multiple resolutions and bitrates.\",\"order_index\":2,\"created_at\":\"2026-09-17T07:55:23.483Z\",\"updated_at\":\"2026-09-17T07:55:23.483Z\"},{\"id\":31,\"question_id\":13,\"type\":\"tradeoff\",\"content\":\"Discuss storage cost versus video quality and the number of generated resolutions.\",\"order_index\":3,\"created_at\":\"2026-09-17T07:55:23.484Z\",\"updated_at\":\"2026-09-17T07:55:23.484Z\"},{\"id\":32,\"question_id\":13,\"type\":\"interview_tip\",\"content\":\"Ask how the system handles a sudden traffic spike for a viral video.\",\"order_index\":4,\"created_at\":\"2026-09-17T07:55:23.486Z\",\"updated_at\":\"2026-09-17T07:55:23.486Z\"}],\"created_at\":\"2026-09-17T07:55:23.477Z\",\"updated_at\":\"2026-09-17T07:55:23.477Z\"},{\"id\":14,\"level_id\":4,\"title\":\"Design an Online Food Delivery System\",\"prompt\":\"Design an online food delivery platform where customers can discover restaurants, place orders, make payments, and track delivery status in real time.\",\"difficulty\":\"Medium\",\"type\":\"whiteboard\",\"detail\":{\"id\":14,\"question_id\":14,\"constraints\":\"\",\"expected_approach\":\"\",\"expected_complexity\":\"\",\"ideal_answer\":\"\",\"scenario\":\"2M daily users, 100K concurrent users during peak hours, and 200K orders per day. Order creation and payment operations require strong consistency while restaurant discovery can tolerate eventual consistency.\",\"correct_option\":\"\",\"explanation\":\"\",\"created_at\":\"2026-09-17T07:55:23.532Z\",\"updated_at\":\"2026-09-17T07:55:23.532Z\"},\"hints\":[{\"id\":33,\"question_id\":14,\"type\":\"talking_point\",\"content\":\"Separate order management, payment, restaurant, and delivery services.\",\"order_index\":1,\"created_at\":\"2026-09-17T07:55:23.545Z\",\"updated_at\":\"2026-09-17T07:55:23.545Z\"},{\"id\":34,\"question_id\":14,\"type\":\"talking_point\",\"content\":\"Use asynchronous events for order status updates and delivery tracking.\",\"order_index\":2,\"created_at\":\"2026-09-17T07:55:23.549Z\",\"updated_at\":\"2026-09-17T07:55:23.549Z\"},{\"id\":35,\"question_id\":14,\"type\":\"tradeoff\",\"content\":\"Discuss strong consistency for orders and payments versus eventual consistency for restaurant availability and tracking.\",\"order_index\":3,\"created_at\":\"2026-09-17T07:55:23.55Z\",\"updated_at\":\"2026-09-17T07:55:23.55Z\"},{\"id\":36,\"question_id\":14,\"type\":\"interview_tip\",\"content\":\"Ask how duplicate payment requests and duplicate orders are prevented.\",\"order_index\":4,\"created_at\":\"2026-09-17T07:55:23.553Z\",\"updated_at\":\"2026-09-17T07:55:23.553Z\"}],\"created_at\":\"2026-09-17T07:55:23.525Z\",\"updated_at\":\"2026-09-17T07:55:23.525Z\"},{\"id\":15,\"level_id\":4,\"title\":\"Design a Ride-Sharing System\",\"prompt\":\"Design a ride-sharing platform that allows passengers to request rides, matches them with nearby drivers, and tracks rides in real time.\",\"difficulty\":\"Hard\",\"type\":\"whiteboard\",\"detail\":{\"id\":15,\"question_id\":15,\"constraints\":\"\",\"expected_approach\":\"\",\"expected_complexity\":\"\",\"ideal_answer\":\"\",\"scenario\":\"5M daily active users and 500K concurrent drivers. Location updates can arrive every few seconds. Ride matching should normally complete within 2 seconds.\",\"correct_option\":\"\",\"explanation\":\"\",\"created_at\":\"2026-09-17T07:55:23.635Z\",\"updated_at\":\"2026-09-17T07:55:23.635Z\"},\"hints\":[{\"id\":37,\"question_id\":15,\"type\":\"talking_point\",\"content\":\"Use geospatial indexing to find nearby available drivers efficiently.\",\"order_index\":1,\"created_at\":\"2026-09-17T07:55:23.648Z\",\"updated_at\":\"2026-09-17T07:55:23.648Z\"},{\"id\":38,\"question_id\":15,\"type\":\"talking_point\",\"content\":\"Use WebSockets or similar persistent connections for real-time location updates.\",\"order_index\":2,\"created_at\":\"2026-09-17T07:55:23.65Z\",\"updated_at\":\"2026-09-17T07:55:23.65Z\"},{\"id\":39,\"question_id\":15,\"type\":\"tradeoff\",\"content\":\"Discuss location-update frequency versus network, CPU, and storage costs.\",\"order_index\":3,\"created_at\":\"2026-09-17T07:55:23.653Z\",\"updated_at\":\"2026-09-17T07:55:23.653Z\"},{\"id\":40,\"question_id\":15,\"type\":\"interview_tip\",\"content\":\"Ask how the system prevents two passengers from being assigned the same driver.\",\"order_index\":4,\"created_at\":\"2026-09-17T07:55:23.666Z\",\"updated_at\":\"2026-09-17T07:55:23.666Z\"}],\"created_at\":\"2026-09-17T07:55:23.618Z\",\"updated_at\":\"2026-09-17T07:55:23.618Z\"},{\"id\":16,\"level_id\":4,\"title\":\"Design a Distributed Rate Limiter\",\"prompt\":\"Design a distributed rate-limiting service that protects APIs from excessive requests while supporting multiple application servers.\",\"difficulty\":\"Medium\",\"type\":\"whiteboard\",\"detail\":{\"id\":16,\"question_id\":16,\"constraints\":\"\",\"expected_approach\":\"\",\"expected_complexity\":\"\",\"ideal_answer\":\"\",\"scenario\":\"The platform receives 1M requests per second across multiple regions. Different APIs may have different limits per user, IP address, or API key. Rate-limit decisions should normally complete within 5ms.\",\"correct_option\":\"\",\"explanation\":\"\",\"created_at\":\"2026-09-17T07:55:23.732Z\",\"updated_at\":\"2026-09-17T07:55:23.732Z\"},\"hints\":[{\"id\":41,\"question_id\":16,\"type\":\"talking_point\",\"content\":\"Consider token bucket or sliding-window algorithms.\",\"order_index\":1,\"created_at\":\"2026-09-17T07:55:23.749Z\",\"updated_at\":\"2026-09-17T07:55:23.749Z\"},{\"id\":42,\"question_id\":16,\"type\":\"talking_point\",\"content\":\"Use Redis or another distributed store for shared counters.\",\"order_index\":2,\"created_at\":\"2026-09-17T07:55:23.754Z\",\"updated_at\":\"2026-09-17T07:55:23.754Z\"},{\"id\":43,\"question_id\":16,\"type\":\"tradeoff\",\"content\":\"Discuss exact global limits versus local limits with lower latency.\",\"order_index\":3,\"created_at\":\"2026-09-17T07:55:23.762Z\",\"updated_at\":\"2026-09-17T07:55:23.762Z\"},{\"id\":44,\"question_id\":16,\"type\":\"interview_tip\",\"content\":\"Ask what happens when the Redis cluster becomes temporarily unavailable.\",\"order_index\":4,\"created_at\":\"2026-09-17T07:55:23.765Z\",\"updated_at\":\"2026-09-17T07:55:23.765Z\"}],\"created_at\":\"2026-09-17T07:55:23.717Z\",\"updated_at\":\"2026-09-17T07:55:23.717Z\"},{\"id\":17,\"level_id\":4,\"title\":\"Design a Notification System\",\"prompt\":\"Design a notification platform capable of sending push notifications, emails, and SMS messages based on events generated by different applications.\",\"difficulty\":\"Medium\",\"type\":\"whiteboard\",\"detail\":{\"id\":17,\"question_id\":17,\"constraints\":\"\",\"expected_approach\":\"\",\"expected_complexity\":\"\",\"ideal_answer\":\"\",\"scenario\":\"100M notifications per day with large traffic bursts. Notifications should be processed asynchronously, retried when providers fail, and should not block the application\'s main request path.\",\"correct_option\":\"\",\"explanation\":\"\",\"created_at\":\"2026-09-17T07:55:23.814Z\",\"updated_at\":\"2026-09-17T07:55:23.814Z\"},\"hints\":[{\"id\":45,\"question_id\":17,\"type\":\"talking_point\",\"content\":\"Use a message queue between event producers and notification workers.\",\"order_index\":1,\"created_at\":\"2026-09-17T07:55:23.825Z\",\"updated_at\":\"2026-09-17T07:55:23.825Z\"},{\"id\":46,\"question_id\":17,\"type\":\"talking_point\",\"content\":\"Use retry queues and dead-letter queues for failed notifications.\",\"order_index\":2,\"created_at\":\"2026-09-17T07:55:23.83Z\",\"updated_at\":\"2026-09-17T07:55:23.83Z\"},{\"id\":47,\"question_id\":17,\"type\":\"tradeoff\",\"content\":\"Discuss delivery guarantees versus duplicate notifications.\",\"order_index\":3,\"created_at\":\"2026-09-17T07:55:23.831Z\",\"updated_at\":\"2026-09-17T07:55:23.831Z\"},{\"id\":48,\"question_id\":17,\"type\":\"interview_tip\",\"content\":\"Ask how notification preferences and user-specific rate limits should be enforced.\",\"order_index\":4,\"created_at\":\"2026-09-17T07:55:23.832Z\",\"updated_at\":\"2026-09-17T07:55:23.832Z\"}],\"created_at\":\"2026-09-17T07:55:23.811Z\",\"updated_at\":\"2026-09-17T07:55:23.811Z\"},{\"id\":18,\"level_id\":4,\"title\":\"Design a Distributed File Storage System\",\"prompt\":\"Design a cloud file-storage service where users can upload, download, organize, and share files across multiple devices.\",\"difficulty\":\"Hard\",\"type\":\"whiteboard\",\"detail\":{\"id\":18,\"question_id\":18,\"constraints\":\"\",\"expected_approach\":\"\",\"expected_complexity\":\"\",\"ideal_answer\":\"\",\"scenario\":\"50M users with 10PB of stored data. Individual files can range from a few KB to several GB. The system must provide durable storage and efficient downloads.\",\"correct_option\":\"\",\"explanation\":\"\",\"created_at\":\"2026-09-17T07:55:23.882Z\",\"updated_at\":\"2026-09-17T07:55:23.882Z\"},\"hints\":[{\"id\":49,\"question_id\":18,\"type\":\"talking_point\",\"content\":\"Use object storage with metadata stored separately in a database.\",\"order_index\":1,\"created_at\":\"2026-09-17T07:55:23.897Z\",\"updated_at\":\"2026-09-17T07:55:23.897Z\"},{\"id\":50,\"question_id\":18,\"type\":\"talking_point\",\"content\":\"Consider multipart uploads for large files and CDN caching for frequently downloaded files.\",\"order_index\":2,\"created_at\":\"2026-09-17T07:55:23.899Z\",\"updated_at\":\"2026-09-17T07:55:23.899Z\"},{\"id\":51,\"question_id\":18,\"type\":\"tradeoff\",\"content\":\"Discuss replication level, durability, storage cost, and access latency.\",\"order_index\":3,\"created_at\":\"2026-09-17T07:55:23.9Z\",\"updated_at\":\"2026-09-17T07:55:23.9Z\"},{\"id\":52,\"question_id\":18,\"type\":\"interview_tip\",\"content\":\"Ask how concurrent updates to the same file should be handled.\",\"order_index\":4,\"created_at\":\"2026-09-17T07:55:23.902Z\",\"updated_at\":\"2026-09-17T07:55:23.902Z\"}],\"created_at\":\"2026-09-17T07:55:23.87Z\",\"updated_at\":\"2026-09-17T07:55:23.87Z\"},{\"id\":19,\"level_id\":4,\"title\":\"Design an E-Commerce Platform\",\"prompt\":\"Design a scalable e-commerce platform where users can browse products, search inventory, add items to carts, place orders, and complete payments.\",\"difficulty\":\"Medium\",\"type\":\"whiteboard\",\"detail\":{\"id\":19,\"question_id\":19,\"constraints\":\"\",\"expected_approach\":\"\",\"expected_complexity\":\"\",\"ideal_answer\":\"\",\"scenario\":\"10M daily users with 100K concurrent users during major sales. Product browsing is read-heavy, while inventory and order operations require strong consistency.\",\"correct_option\":\"\",\"explanation\":\"\",\"created_at\":\"2026-09-17T07:55:23.946Z\",\"updated_at\":\"2026-09-17T07:55:23.946Z\"},\"hints\":[{\"id\":53,\"question_id\":19,\"type\":\"talking_point\",\"content\":\"Use caching and read replicas for high-volume product browsing.\",\"order_index\":1,\"created_at\":\"2026-09-17T07:55:23.948Z\",\"updated_at\":\"2026-09-17T07:55:23.948Z\"},{\"id\":54,\"question_id\":19,\"type\":\"talking_point\",\"content\":\"Use atomic inventory operations to prevent overselling during high-demand sales.\",\"order_index\":2,\"created_at\":\"2026-09-17T07:55:23.949Z\",\"updated_at\":\"2026-09-17T07:55:23.949Z\"},{\"id\":55,\"question_id\":19,\"type\":\"tradeoff\",\"content\":\"Discuss database consistency versus availability for inventory and product information.\",\"order_index\":3,\"created_at\":\"2026-09-17T07:55:23.95Z\",\"updated_at\":\"2026-09-17T07:55:23.95Z\"},{\"id\":56,\"question_id\":19,\"type\":\"interview_tip\",\"content\":\"Ask how the system handles thousands of users attempting to purchase the last item simultaneously.\",\"order_index\":4,\"created_at\":\"2026-09-17T07:55:23.95Z\",\"updated_at\":\"2026-09-17T07:55:23.95Z\"}],\"created_at\":\"2026-09-17T07:55:23.935Z\",\"updated_at\":\"2026-09-17T07:55:23.935Z\"},{\"id\":20,\"level_id\":4,\"title\":\"Design a Real-Time Collaborative Document Editor\",\"prompt\":\"Architect a real-time collaborative text editor that allows multiple users to edit the same document simultaneously while resolving conflicts and maintaining document history.\",\"difficulty\":\"Hard\",\"type\":\"whiteboard\",\"detail\":{\"id\":20,\"question_id\":20,\"constraints\":\"\",\"expected_approach\":\"\",\"expected_complexity\":\"\",\"ideal_answer\":\"\",\"scenario\":\"100 active collaborators per document with typing latency below 50ms. The system must support document revisions, concurrent edits, and users reconnecting after temporary network failures.\",\"correct_option\":\"\",\"explanation\":\"\",\"created_at\":\"2026-09-17T07:55:23.998Z\",\"updated_at\":\"2026-09-17T07:55:23.998Z\"},\"hints\":[{\"id\":57,\"question_id\":20,\"type\":\"talking_point\",\"content\":\"Consider Operational Transformation or Conflict-free Replicated Data Types for concurrent editing.\",\"order_index\":1,\"created_at\":\"2026-09-17T07:55:24.009Z\",\"updated_at\":\"2026-09-17T07:55:24.009Z\"},{\"id\":58,\"question_id\":20,\"type\":\"talking_point\",\"content\":\"Use WebSockets for real-time updates and a persistent store for document snapshots and history.\",\"order_index\":2,\"created_at\":\"2026-09-17T07:55:24.014Z\",\"updated_at\":\"2026-09-17T07:55:24.014Z\"},{\"id\":59,\"question_id\":20,\"type\":\"tradeoff\",\"content\":\"Discuss centralized operation ordering with OT versus client-side convergence with CRDTs.\",\"order_index\":3,\"created_at\":\"2026-09-17T07:55:24.016Z\",\"updated_at\":\"2026-09-17T07:55:24.016Z\"},{\"id\":60,\"question_id\":20,\"type\":\"interview_tip\",\"content\":\"Ask how document snapshotting prevents replaying a very large number of historical operations.\",\"order_index\":4,\"created_at\":\"2026-09-17T07:55:24.017Z\",\"updated_at\":\"2026-09-17T07:55:24.017Z\"}],\"created_at\":\"2026-09-17T07:55:23.988Z\",\"updated_at\":\"2026-09-17T07:55:23.988Z\"}],\"status\":\"success\"}','','2026-09-17 07:55:24.334'),(218,2,'admin@bitsathy.ac.in','System Administrator','admin','GET','/api/v1/admin/interviews/tracks/2','','2a09:bac1:36c0:128::2a7:70','Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/153.0.0.0 Safari/537.36',200,2,'','{\"data\":{\"category\":\"Architecture\",\"created_at\":\"2026-09-17T07:43:11Z\",\"description\":\"Scalable distributed systems, load balancers, caching, microservices, and whiteboard diagrams.\",\"icon\":\"Layers\",\"id\":2,\"levels_count\":2,\"questions_count\":10,\"slug\":\"system-design\",\"title\":\"System Design \\u0026 Architecture\",\"updated_at\":\"2026-09-17T07:43:11Z\"},\"status\":\"success\"}','','2026-09-17 07:55:28.396'),(219,2,'admin@bitsathy.ac.in','System Administrator','admin','GET','/api/v1/admin/interviews/levels/4','','2a09:bac1:36c0:128::2a7:70','Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/153.0.0.0 Safari/537.36',200,3,'','{\"data\":{\"created_at\":\"2026-09-17T07:44:11Z\",\"description\":\"Designing scalable URL shorteners, rate limiters, and cache layers\",\"duration_minutes\":45,\"id\":4,\"level_number\":1,\"mode\":\"whiteboard\",\"name\":\"High-Level System Design\",\"question_count\":1,\"questions_count\":10,\"track_id\":2,\"updated_at\":\"2026-09-17T07:44:11Z\"},\"status\":\"success\"}','','2026-09-17 07:55:28.439'),(220,2,'admin@bitsathy.ac.in','System Administrator','admin','GET','/api/v1/admin/feedback/questions','','2a09:bac1:36c0:128::2a7:70','Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/153.0.0.0 Safari/537.36',200,9,'','{\"data\":[{\"id\":1,\"question_text\":\"How would you rate the student\'s technical knowledge?\",\"short_label\":\"Technical\",\"question_type\":\"mcq\",\"is_required\":true,\"max_marks\":10,\"order_index\":1,\"is_active\":true,\"