AppleWebKit/537.36 (KHTML, like Gecko) Chrome/153.0.0.0 Safari/537.36',200,4,'','{\"data\":{\"created_at\":\"2026-09-17T07:44:11Z\",\"description\":\"Interactive SQL playground: aggregations, subqueries, and window functions\",\"duration_minutes\":45,\"id\":6,\"level_number\":1,\"mode\":\"database\",\"name\":\"Relational Queries \\u0026 Complex Joins\",\"question_count\":1,\"questions_count\":0,\"track_id\":3,\"updated_at\":\"2026-09-17T07:55:49.616Z\"},\"status\":\"success\"}','','2026-09-17 07:57:58.246'),(303,2,'admin@bitsathy.ac.in','System Administrator','admin','GET','/api/v1/admin/interviews/tracks/3','','2a09:bac1:36c0:128::2a7:70','Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/153.0.0.0 Safari/537.36',200,6,'','{\"data\":{\"category\":\"Databases\",\"created_at\":\"2026-09-17T07:43:11Z\",\"description\":\"Interactive SQL playground, schema design, indexes, transactions, and query optimization.\",\"icon\":\"Database\",\"id\":3,\"levels_count\":2,\"questions_count\":0,\"slug\":\"database-engineering\",\"title\":\"Database Engineering \\u0026 SQL\",\"updated_at\":\"2026-09-17T07:43:11Z\"},\"status\":\"success\"}','','2026-09-17 07:57:58.246'),(304,2,'admin@bitsathy.ac.in','System Administrator','admin','POST','/api/v1/admin/interviews/levels/6/questions/bulk','','2a09:bac1:36c0:128::2a7:70','Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/153.0.0.0 Safari/537.36',200,215,'{\"questions\":[{\"title\":\"Employee Department Salary Analysis\",\"prompt\":\"Write a SQL query to find the top 3 highest-paid employees in each department, including the employee name, department name, and salary.\",\"difficulty\":\"Medium\",\"type\":\"database\",\"detail\":{\"scenario\":\"Tables required: employees, departments. Employees belong to departments and have salary information. Return the top 3 employees per department.\",\"expected_approach\":\"Use JOIN between employees and departments, then use ROW_NUMBER() or DENSE_RANK() with PARTITION BY department_id to identify the highest-paid employees in each department.\",\"constraints\":\"Employees without a valid department should not appear. Handle salary ties appropriately.\"},\"templates\":[{\"language\":\"sql\",\"starter_code\":\"CREATE TABLE departments (\\n  id INTEGER PRIMARY KEY,\\n  name VARCHAR(100) NOT NULL\\n);\\n\\nCREATE TABLE employees (\\n  id INTEGER PRIMARY KEY,\\n  name VARCHAR(100) NOT NULL,\\n  department_id INTEGER,\\n  salary DECIMAL(10,2) NOT NULL,\\n  FOREIGN KEY (department_id) REFERENCES departments(id)\\n);\\n\\nINSERT INTO departments VALUES\\n(1, \'Engineering\'),\\n(2, \'HR\'),\\n(3, \'Finance\');\\n\\nINSERT INTO employees VALUES\\n(101, \'Alice\', 1, 90000),\\n(102, \'Bob\', 1, 110000),\\n(103, \'Charlie\', 1, 105000),\\n(104, \'David\', 2, 70000),\\n(105, \'Eva\', 2, 85000),\\n(106, \'Frank\', 3, 95000);\"}],\"hints\":[{\"type\":\"hint\",\"content\":\"Use a window function with PARTITION BY department_id and ORDER BY salary DESC.\"},{\"type\":\"interview_tip\",\"content\":\"Evaluate whether the candidate understands the difference between ROW_NUMBER(), RANK(), and DENSE_RANK().\"}],\"level_id\":6},{\"title\":\"Customers Without Recent Orders\",\"prompt\":\"Write a SQL query to find customers who have not placed any completed orders during the last 6 months.\",\"difficulty\":\"Medium\",\"type\":\"database\",\"detail\":{\"scenario\":\"Tables required: customers and orders. A customer can have multiple orders. Only completed orders should be considered.\",\"expected_approach\":\"Use LEFT JOIN with the date and status conditions applied correctly, then identify customers whose matching order is NULL.\",\"constraints\":\"Customers with only pending or refunded orders should also be included.\"},\"templates\":[{\"language\":\"sql\",\"starter_code\":\"CREATE TABLE customers (\\n  id INTEGER PRIMARY KEY,\\n  name VARCHAR(100) NOT NULL,\\n  email VARCHAR(255) UNIQUE NOT NULL\\n);\\n\\nCREATE TABLE orders (\\n  id INTEGER PRIMARY KEY,\\n  customer_id INTEGER,\\n  status VARCHAR(50) NOT NULL,\\n  total_amount DECIMAL(10,2) NOT NULL,\\n  created_at TIMESTAMP NOT NULL,\\n  FOREIGN KEY (customer_id) REFERENCES customers(id)\\n);\"}],\"hints\":[{\"type\":\"hint\",\"content\":\"A LEFT JOIN can preserve customers even when they have no matching recent completed order.\"},{\"type\":\"interview_tip\",\"content\":\"Check whether the candidate understands why putting the filtering condition in WHERE instead of ON can change LEFT JOIN behavior.\"}],\"level_id\":6},{\"title\":\"Product Sales With Category Ranking\",\"prompt\":\"Write a SQL query to find the highest-selling product in each category based on total quantity sold.\",\"difficulty\":\"Hard\",\"type\":\"database\",\"detail\":{\"scenario\":\"Tables required: products, categories, order_items, and orders. Only completed orders should contribute to sales calculations.\",\"expected_approach\":\"Join products with categories and order_items, filter completed orders, aggregate quantity by product, and use a window function to rank products within each category.\",\"constraints\":\"Products with no completed sales should not be considered. Handle multiple products having the same total quantity.\"},\"templates\":[{\"language\":\"sql\",\"starter_code\":\"CREATE TABLE categories (\\n  id INTEGER PRIMARY KEY,\\n  name VARCHAR(100) NOT NULL\\n);\\n\\nCREATE TABLE products (\\n  id INTEGER PRIMARY KEY,\\n  name VARCHAR(150) NOT NULL,\\n  category_id INTEGER,\\n  FOREIGN KEY (category_id) REFERENCES categories(id)\\n);\\n\\nCREATE TABLE orders (\\n  id INTEGER PRIMARY KEY,\\n  status VARCHAR(50) NOT NULL\\n);\\n\\nCREATE TABLE order_items (\\n  order_id INTEGER,\\n  product_id INTEGER,\\n  quantity INTEGER NOT NULL,\\n  FOREIGN KEY (order_id) REFERENCES orders(id),\\n  FOREIGN KEY (product_id) REFERENCES products(id)\\n);\"}],\"hints\":[{\"type\":\"hint\",\"content\":\"First calculate total quantity for each product, then rank products inside each category.\"},{\"type\":\"interview_tip\",\"content\":\"Evaluate the candidate\'s ability to combine multiple JOINs, GROUP BY, aggregation, and window functions.\"}],\"level_id\":6},{\"title\":\"Department Average Salary Comparison\",\"prompt\":\"Write a SQL query to find employees whose salary is greater than the average salary of their own department.\",\"difficulty\":\"Medium\",\"type\":\"database\",\"detail\":{\"scenario\":\"Tables required: employees and departments. Each employee belongs to a department and has a salary.\",\"expected_approach\":\"Calculate the department-level average salary using a subquery or window function, then compare each employee\'s salary against the corresponding department average.\",\"constraints\":\"Return employee name, department name, salary, and department average salary.\"},\"templates\":[{\"language\":\"sql\",\"starter_code\":\"CREATE TABLE departments (\\n  id INTEGER PRIMARY KEY,\\n  name VARCHAR(100) NOT NULL\\n);\\n\\nCREATE TABLE employees (\\n  id INTEGER PRIMARY KEY,\\n  name VARCHAR(100) NOT NULL,\\n  department_id INTEGER,\\n  salary DECIMAL(10,2) NOT NULL,\\n  FOREIGN KEY (department_id) REFERENCES departments(id)\\n);\"}],\"hints\":[{\"type\":\"hint\",\"content\":\"You can calculate the department average using AVG() with PARTITION BY department_id.\"},{\"type\":\"interview_tip\",\"content\":\"Check whether the candidate can avoid unnecessary correlated subqueries when a window function can solve the problem.\"}],\"level_id\":6},{\"title\":\"Multi-Level Order Customer Analysis\",\"prompt\":\"Write a SQL query to find customers who have purchased at least 3 different products across at least 2 different categories, and calculate their total spending.\",\"difficulty\":\"Hard\",\"type\":\"database\",\"detail\":{\"scenario\":\"Tables required: customers, orders, order_items, products, and categories. Only completed orders should be included.\",\"expected_approach\":\"Join all related tables, filter completed orders, group by customer, calculate COUNT(DISTINCT product_id), COUNT(DISTINCT category_id), and SUM of item quantity multiplied by product price.\",\"constraints\":\"A customer must have purchased at least 3 distinct products and products from at least 2 distinct categories.\"},\"templates\":[{\"language\":\"sql\",\"starter_code\":\"CREATE TABLE customers (\\n  id INTEGER PRIMARY KEY,\\n  name VARCHAR(100) NOT NULL\\n);\\n\\nCREATE TABLE categories (\\n  id INTEGER PRIMARY KEY,\\n  name VARCHAR(100) NOT NULL\\n);\\n\\nCREATE TABLE products (\\n  id INTEGER PRIMARY KEY,\\n  name VARCHAR(150) NOT NULL,\\n  category_id INTEGER,\\n  price DECIMAL(10,2) NOT NULL,\\n  FOREIGN KEY (category_id) REFERENCES categories(id)\\n);\\n\\nCREATE TABLE orders (\\n  id INTEGER PRIMARY KEY,\\n  customer_id INTEGER,\\n  status VARCHAR(50) NOT NULL,\\n  FOREIGN KEY (customer_id) REFERENCES customers(id)\\n);\\n\\nCREATE TABLE order_items (\\n  order_id INTEGER,\\n  product_id INTEGER,\\n  quantity INTEGER NOT NULL,\\n  FOREIGN KEY (order_id) REFERENCES orders(id),\\n  FOREIGN KEY (product_id) REFERENCES products(id)\\n);\"}],\"hints\":[{\"type\":\"hint\",\"content\":\"Use COUNT(DISTINCT product_id) and COUNT(DISTINCT category_id) with HAVING.\"},{\"type\":\"interview_tip\",\"content\":\"Evaluate whether the candidate understands the difference between WHERE and HAVING when filtering aggregated results.\"}],\"level_id\":6}]}','{\"created_count\":5,\"data\":[{\"id\":21,\"level_id\":6,\"title\":\"Employee Department Salary Analysis\",\"prompt\":\"Write a SQL query to find the top 3 highest-paid employees in each department, including the employee name, department name, and salary.\",\"difficulty\":\"Medium\",\"type\":\"database\",\"created_at\":\"2026-09-17T07:59:35.693Z\",\"updated_at\":\"2026-09-17T07:59:35.693Z\"},{\"id\":22,\"level_id\":6,\"title\":\"Customers Without Recent Orders\",\"prompt\":\"Write a SQL query to find customers who have not placed any completed orders during the last 6 months.\",\"difficulty\":\"Medium\",\"type\":\"database\",\"created_at\":\"2026-09-17T07:59:35.728Z\",\"updated_at\":\"2026-09-17T07:59:35.728Z\"},{\"id\":23,\"level_id\":6,\"title\":\"Product Sales With Category Ranking\",\"prompt\":\"Write a SQL query to find the highest-selling product in each category based on total quantity sold.\",\"difficulty\":\"Hard\",\"type\":\"database\",\"created_at\":\"2026-09-17T07:59:35.767Z\",\"updated_at\":\"2026-09-17T07:59:35.767Z\"},{\"id\":24,\"level_id\":6,\"title\":\"Department Average Salary Comparison\",\"prompt\":\"Write a SQL query to find employees whose salary is greater than the average salary of their own department.\",\"difficulty\":\"Medium\",\"type\":\"database\",\"created_at\":\"2026-09-17T07:59:35.814Z\",\"updated_at\":\"2026-09-17T07:59:35.814Z\"},{\"id\":25,\"level_id\":6,\"title\":\"Multi-Level Order Customer Analysis\",\"prompt\":\"Write a SQL query to find customers who have purchased at least 3 different products across at least 2 different categories, and calculate their total spending.\",\"difficulty\":\"Hard\",\"type\":\"database\",\"created_at\":\"2026-09-17T07:59:35.867Z\",\"updated_at\":\"2026-09-17T07:59:35.867Z\"}],\"message\":\"Bulk upload complete: 5 questions created, 0 skipped\",\"skipped_count\":0,\"skipped_details\":null,\"status\":\"success\"}','','2026-09-17 07:59:35.691'),(305,2,'admin@bitsathy.ac.in','System Administrator','admin','GET','/api/v1/admin/interviews/levels/6','','2a09:bac1:36c0:128::2a7:70','Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/153.0.0.0 Safari/537.36',200,2,'','{\"data\":{\"created_at\":\"2026-09-17T07:44:11Z\",\"description\":\"Interactive SQL playground: aggregations, subqueries, and window functions\",\"duration_minutes\":45,\"id\":6,\"level_number\":1,\"mode\":\"database\",\"name\":\"Relational Queries \\u0026 Complex Joins\",\"question_count\":1,\"questions_count\":5,\"track_id\":3,\"updated_at\":\"2026-09-17T07:55:49.616Z\"},\"status\":\"success\"}','','2026-09-17 07:59:36.360'),(306,2,'admin@bitsathy.ac.in','System Administrator','admin','GET','/api/v1/admin/interviews/tracks/3','','2a09:bac1:36c0:128::2a7:70','Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/153.0.0.0 Safari/537.36',200,3,'','{\"data\":{\"category\":\"Databases\",\"created_at\":\"2026-09-17T07:43:11Z\",\"description\":\"Interactive SQL playground, schema design, indexes, transactions, and query optimization.\",\"icon\":\"Database\",\"id\":3,\"levels_count\":2,\"questions_count\":5,\"slug\":\"database-engineering\",\"title\":\"Database Engineering \\u0026 SQL\",\"updated_at\":\"2026-09-17T07:43:11Z\"},\"status\":\"success\"}','','2026-09-17 07:59:36.360'),(307,2,'admin@bitsathy.ac.in','System Administrator','admin','GET','/api/v1/admin/interviews/levels/6/questions','','2a09:bac1:36c0:128::2a7:70','Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/153.0.0.0 Safari/537.36',200,16,'','{\"data\":[{\"id\":21,\"level_id\":6,\"title\":\"Employee Department Salary Analysis\",\"prompt\":\"Write a SQL query to find the top 3 highest-paid employees in each department, including the employee name, department name, and salary.\",\"difficulty\":\"Medium\",\"type\":\"database\",\"detail\":{\"id\":21,\"question_id\":21,\"constraints\":\"Employees without a valid department should not appear. Handle salary ties appropriately.\",\"expected_approach\":\"Use JOIN between employees and departments, then use ROW_NUMBER() or DENSE_RANK() with PARTITION BY department_id to identify the highest-paid employees in each department.\",\"expected_complexity\":\"\",\"ideal_answer\":\"\",\"scenario\":\"Tables required: employees, departments. Employees belong to departments and have salary information. Return the top 3 employees per department.\",\"correct_option\":\"\",\"explanation\":\"\",\"created_at\":\"2026-09-17T07:59:35.694Z\",\"updated_at\":\"2026-09-17T07:59:35.694Z\"},\"templates\":[{\"id\":1,\"question_id\":21,\"language\":\"sql\",\"starter_code\":\"CREATE TABLE departments (\\n  id INTEGER PRIMARY KEY,\\n  name VARCHAR(100) NOT NULL\\n);\\n\\nCREATE TABLE employees (\\n  id INTEGER PRIMARY KEY,\\n  name VARCHAR(100) NOT NULL,\\n  department_id INTEGER,\\n  salary DECIMAL(10,2) NOT NULL,\\n  FOREIGN KEY (department_id) REFERENCES departments(id)\\n);\\n\\nINSERT INTO departments VALUES\\n(1, \'Engineering\'),\\n(2, \'HR\'),\\n(3, \'Finance\');\\n\\nINSERT INTO employees VALUES\\n(101, \'Alice\', 1, 90000),\\n(102, \'Bob\', 1, 110000),\\n(103, \'Charlie\', 1, 105000),\\n(104, \'David\', 2, 70000),\\n(105, \'Eva\', 2, 85000),\\n(106, \'Frank\', 3, 95000);\",\"created_at\":\"2026-09-17T07:59:35.695Z\",\"updated_at\":\"2026-09-17T07:59:35.695Z\"}],\"hints\":[{\"id\":61,\"question_id\":21,\"type\":\"hint\",\"content\":\"Use a window function with PARTITION BY department_id and ORDER BY salary DESC.\",\"order_index\":1,\"created_at\":\"2026-09-17T07:59:35.699Z\",\"updated_at\":\"2026-09-17T07:59:35.699Z\"},{\"id\":62,\"question_id\":21,\"type\":\"interview_tip\",\"content\":\"Evaluate whether the candidate understands the difference between ROW_NUMBER(), RANK(), and DENSE_RANK().\",\"order_index\":2,\"created_at\":\"2026-09-17T07:59:35.703Z\",\"updated_at\":\"2026-09-17T07:59:35.703Z\"}],\"created_at\":\"2026-09-17T07:59:35.693Z\",\"updated_at\":\"2026-09-17T07:59:35.693Z\"},{\"id\":22,\"level_id\":6,\"title\":\"Customers Without Recent Orders\",\"prompt\":\"Write a SQL query to find customers who have not placed any completed orders during the last 6 months.\",\"difficulty\":\"Medium\",\"type\":\"database\",\"detail\":{\"id\":22,\"question_id\":22,\"constraints\":\"Customers with only pending or refunded orders should also be included.\",\"expected_approach\":\"Use LEFT JOIN with the date and status conditions applied correctly, then identify customers whose matching order is NULL.\",\"expected_complexity\":\"\",\"ideal_answer\":\"\",\"scenario\":\"Tables required: customers and orders. A customer can have multiple orders. Only completed orders should be considered.\",\"correct_option\":\"\",\"explanation\":\"\",\"created_at\":\"2026-09-17T07:59:35.73Z\",\"updated_at\":\"2026-09-17T07:59:35.73Z\"},\"templates\":[{\"id\":2,\"question_id\":22,\"language\":\"sql\",\"starter_code\":\"CREATE TABLE customers (\\n  id INTEGER PRIMARY KEY,\\n  name VARCHAR(100) NOT NULL,\\n  email VARCHAR(255) UNIQUE NOT NULL\\n);\\n\\nCREATE TABLE orders (\\n  id INTEGER PRIMARY KEY,\\n  customer_id INTEGER,\\n  status VARCHAR(50) NOT NULL,\\n  total_amount DECIMAL(10,2) NOT NULL,\\n  created_at TIMESTAMP NOT NULL,\\n  FOREIGN KEY (customer_id) REFERENCES customers(id)\\n);\",\"created_at\":\"2026-09-17T07:59:35.734Z\",\"updated_at\":\"2026-09-17T07:59:35.734Z\"}],\"hints\":[{\"id\":63,\"question_id\":22,\"type\":\"hint\",\"content\":\"A LEFT JOIN can preserve customers even when they have no matching recent completed order.\",\"order_index\":1,\"created_at\":\"2026-09-17T07:59:35.74Z\",\"updated_at\":\"2026-09-17T07:59:35.74Z\"},{\"id\":64,\"question_id\":22,\"type\":\"interview_tip\",\"content\":\"Check whether the candidate understands why putting the filtering condition in WHERE instead of ON can change LEFT JOIN behavior.\",\"order_index\":2,\"created_at\":\"2026-09-17T07:59:35.741Z\",\"updated_at\":\"2026-09-17T07:59:35.741Z\"}],\"created_at\":\"2026-09-17T07:59:35.728Z\",\"updated_at\":\"2026-09-17T07:59:35.728Z\"},{\"id\":23,\"level_id\":6,\"title\":\"Product Sales With Category Ranking\",\"prompt\":\"Write a SQL query to find the highest-selling product in each category based on total quantity sold.\",\"difficulty\":\"Hard\",\"type\":\"database\",\"detail\":{\"id\":23,\"question_id\":23,\"constraints\":\"Products with no completed sales should not be considered. Handle multiple products having the same total quantity.\",\"expected_approach\":\"Join products with categories and order_items, filter completed orders, aggregate quantity by product, and use a window function to rank products within each category.\",\"expected_complexity\":\"\",\"ideal_answer\":\"\",\"scenario\":\"Tables required: products, categories, order_items, and orders. Only completed orders should contribute to sales calculations.\",\"correct_option\":\"\",\"explanation\":\"\",\"created_at\":\"2026-09-17T07:59:35.774Z\",\"updated_at\":\"2026-09-17T07:59:35.774Z\"},\"templates\":[{\"id\":3,\"question_id\":23,\"language\":\"sql\",\"starter_code\":\"CREATE TABLE categories (\\n  id INTEGER PRIMARY KEY,\\n  name VARCHAR(100) NOT NULL\\n);\\n\\nCREATE TABLE products (\\n  id INTEGER PRIMARY KEY,\\n  name VARCHAR(150) NOT NULL,\\n  category_id INTEGER,\\n  FOREIGN KEY (category_id) REFERENCES categories(id)\\n);\\n\\nCREATE TABLE orders (\\n  id INTEGER PRIMARY KEY,\\n  status VARCHAR(50) NOT NULL\\n);\\n\\nCREATE TABLE order_items (\\n  order_id INTEGER,\\n  product_id INTEGER,\\n  quantity INTEGER NOT NULL,\\n  FOREIGN KEY (order_id) REFERENCES orders(id),\\n  FOREIGN KEY (product_id) REFERENCES products(id)\\n);\",\"created_at\":\"2026-09-17T07:59:35.776Z\",\"updated_at\":\"2026-09-17T07:59:35.776Z\"}],\"hints\":[{\"id\":65,\"question_id\":23,\"type\":\"hint\",\"content\":\"First calculate total quantity for each product, then rank products inside each category.\",\"order_index\":1,\"created_at\":\"2026-09-17T07:59:35.779Z\",\"updated_at\":\"2026-09-17T07:59:35.779Z\"},{\"id\":66,\"question_id\":23,\"type\":\"interview_tip\",\"content\":\"Evaluate the candidate\'s ability to combine multiple JOINs, GROUP BY, aggregation, and window functions.\",\"order_index\":2,\"created_at\":\"2026-09-17T07:59:35.78Z\",\"updated_at\":\"2026-09-17T07:59:35.78Z\"}],\"created_at\":\"2026-09-17T07:59:35.767Z\",\"updated_at\":\"2026-09-17T07:59:35.767Z\"},{\"id\":24,\"level_id\":6,\"title\":\"Department Average Salary Comparison\",\"prompt\":\"Write a SQL query to find employees whose salary is greater than the average salary of their own department.\",\"difficulty\":\"Medium\",\"type\":\"database\",\"detail\":{\"id\":24,\"question_id\":24,\"constraints\":\"Return employee name, department name, salary, and department average salary.\",\"expected_approach\":\"Calculate the department-level average salary using a subquery or window function, then compare each employee\'s salary against the corresponding department average.\",\"expected_complexity\":\"\",\"ideal_answer\":\"\",\"scenario\":\"Tables required: employees and departments. Each employee belongs to a department and has a salary.\",\"correct_option\":\"\",\"explanation\":\"\",\"created_at\":\"2026-09-17T07:59:35.821Z\",\"updated_at\":\"2026-09-17T07:59:35.821Z\"},\"templates\":[{\"id\":4,\"question_id\":24,\"language\":\"sql\",\"starter_code\":\"CREATE TABLE departments (\\n  id INTEGER PRIMARY KEY,\\n  name VARCHAR(100) NOT NULL\\n);\\n\\nCREATE TABLE employees (\\n  id INTEGER PRIMARY KEY,\\n  name VARCHAR(100) NOT NULL,\\n  department_id INTEGER,\\n  salary DECIMAL(10,2) NOT NULL,\\n  FOREIGN KEY (department_id) REFERENCES departments(id)\\n);\",\"created_at\":\"2026-09-17T07:59:35.824Z\",\"updated_at\":\"2026-09-17T07:59:35.824Z\"}],\"hints\":[{\"id\":67,\"question_id\":24,\"type\":\"hint\",\"content\":\"You can calculate the department average using AVG() with PARTITION BY department_id.\",\"order_index\":1,\"created_at\":\"2026-09-17T07:59:35.826Z\",\"updated_at\":\"2026-09-17T07:59:35.826Z\"},{\"id\":68,\"question_id\":24,\"type\":\"interview_tip\",\"content\":\"Check whether the candidate can avoid unnecessary correlated subqueries when a window function can solve the problem.\",\"order_index\":2,\"created_at\":\"2026-09-17T07:59:35.828Z\",\"updated_at\":\"2026-09-17T07:59:35.828Z\"}],\"created_at\":\"2026-09-17T07:59:35.814Z\",\"updated_at\":\"2026-09-17T07:59:35.814Z\"},{\"id\":25,\"level_id\":6,\"title\":\"Multi-Level Order Customer Analysis\",\"prompt\":\"Write a SQL query to find customers who have purchased at least 3 different products across at least 2 different categories, and calculate their total spending.\",\"difficulty\":\"Hard\",\"type\":\"database\",\"detail\":{\"id\":25,\"question_id\":25,\"constraints\":\"A customer must have purchased at least 3 distinct products and products from at least 2 distinct categories.\",\"expected_approach\":\"Join all related tables, filter completed orders, group by customer, calculate COUNT(DISTINCT product_id), COUNT(DISTINCT category_id), and SUM of item quantity multiplied by product price.\",\"expected_complexity\":\"\",\"ideal_answer\":\"\",\"scenario\":\"Tables required: customers, orders, order_items, products, and categories. Only completed orders should be included.\",\"correct_option\":\"\",\"explanation\":\"\",\"created_at\":\"2026-09-17T07:59:35.873Z\",\"updated_at\":\"2026-09-17T07:59:35.873Z\"},\"templates\":[{\"id\":5,\"question_id\":25,\"language\":\"sql\",\"starter_code\":\"CREATE TABLE customers (\\n  id INTEGER PRIMARY KEY,\\n  name VARCHAR(100) NOT NULL\\n);\\n\\nCREATE TABLE categories (\\n  id INTEGER PRIMARY KEY,\\n  name VARCHAR(100) NOT NULL\\n);\\n\\nCREATE TABLE products (\\n  id INTEGER PRIMARY KEY,\\n  name VARCHAR(150) NOT NULL,\\n  category_id INTEGER,\\n  price DECIMAL(10,2) NOT NULL,\\n  FOREIGN KEY (category_id) REFERENCES categories(id)\\n);\\n\\nCREATE TABLE orders (\\n  id INTEGER PRIMARY KEY,\\n  customer_id INTEGER,\\n  status VARCHAR(50) NOT NULL,\\n  FOREIGN KEY (customer_id) REFERENCES customers(id)\\n);\\n\\nCREATE TABLE order_items (\\n  order_id INTEGER,\\n  product_id INTEGER,\\n  quantity INTEGER NOT NULL,\\n  FOREIGN KEY (order_id) REFERENCES orders(id),\\n  FOREIGN KEY (product_id) REFERENCES products(id)\\n);\",\"created_at\":\"2026-09-17T07:59:35.875Z\",\"updated_at\":\"2026-09-17T07:59:35.875Z\"}],\"hints\":[{\"id\":69,\"question_id\":25,\"type\":\"hint\",\"content\":\"Use COUNT(DISTINCT product_id) and COUNT(DISTINCT category_id) with HAVING.\",\"order_index\":1,\"created_at\":\"2026-09-17T07:59:35.877Z\",\"updated_at\":\"2026-09-17T07:59:35.877Z\"},{\"id\":70,\"question_id\":25,\"type\":\"interview_tip\",\"content\":\"Evaluate whether the candidate understands the difference between WHERE and HAVING when filtering aggregated results.\",\"order_index\":2,\"created_at\":\"2026-09-17T07:59:35.88Z\",\"updated_at\":\"2026-09-17T07:59:35.88Z\"}],\"created_at\":\"2026-09-17T07:59:35.867Z\",\"updated_at\":\"2026-09-17T07:59:35.867Z\"}],\"status\":\"success\"}','','2026-09-17 07:59:36.361'),(308,2,'admin@bitsathy.ac.in','System Administrator','admin','GET','/api/v1/admin/interviews/tracks','','2a09:bac1:36c0:128::2a7:70','Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/153.0.0.0 Safari/537.36',200,13,'','{\"data\":[{\"id\":1,\"title\":\"Data Structures \\u0026 Algorithms\",\"slug\":\"dsa\",\"category\":\"Technical\",\"icon\":\"Code\",\"description\":\"Core problem solving, arrays, trees, dynamic programming, and algorithmic complexity.\",\"created_at\":\"2026-09-17T07:43:11Z\",\"updated_at\":\"2026-09-17T07:43:11Z\",\"levels_count\":3,\"questions_count\":10},{\"id\":2,\"title\":\"System Design \\u0026 Architecture\",\"slug\":\"system-design\",\"category\":\"Architecture\",\"icon\":\"Layers\",\"description\":\"Scalable distributed systems, load balancers, caching, microservices, and whiteboard diagrams.\",\"created_at\":\"2026-09-17T07:43:11Z\",\"updated_at\":\"2026-09-17T07:43:11Z\",\"levels_count\":2,\"questions_count\":10},{\"id\":3,\"title\":\"Database Engineering \\u0026 SQL\",\"slug\":\"database-engineering\",\"category\":\"Databases\",\"icon\":\"Database\",\"description\":\"Interactive SQL playground, schema design, indexes, transactions, and query optimization.\",\"created_at\":\"2026-09-17T07:43:11Z\",\"updated_at\":\"2026-09-17T07:43:11Z\",\"levels_count\":2,\"questions_count\":5},{\"id\":4,\"title\":\"Frontend \\u0026 Web Development\",\"slug\":\"frontend-dev