duct name and price.\",\"constraints\":\"Use React and map() to render the products.\"},\"templates\":[{\"language\":\"javascript\",\"starter_code\":\"import React from \'react\';\\n\\nconst products = [\\n  { id: 1, name: \'Laptop\', price: 50000 },\\n  { id: 2, name: \'Mouse\', price: 1000 },\\n  { id: 3, name: \'Keyboard\', price: 2000 }\\n];\\n\\nexport default function App() {\\n  return (\\n    <div>\\n      <h1>Products</h1>\\n      {/* Display products here */}\\n    </div>\\n  );\\n}\"}],\"hints\":[{\"type\":\"hint\",\"content\":\"Use products.map() to display each product.\"}],\"level_id\":8},{\"title\":\"Counter Button\",\"prompt\":\"Build a React counter with a number displayed on the screen and buttons to increase and decrease the value.\",\"difficulty\":\"Easy\",\"type\":\"frontend\",\"detail\":{\"scenario\":\"The counter starts at 0. Clicking + increases the value by 1 and clicking - decreases it by 1.\",\"constraints\":\"Use React useState for the counter value.\"},\"templates\":[{\"language\":\"javascript\",\"starter_code\":\"import React, { useState } from \'react\';\\n\\nexport default function App() {\\n  const [count, setCount] = useState(0);\\n\\n  return (\\n    <div>\\n      <h1>Counter</h1>\\n      <p>{count}</p>\\n      {/* Add buttons here */}\\n    </div>\\n  );\\n}\"}],\"hints\":[{\"type\":\"hint\",\"content\":\"Use setCount(count + 1) for increasing and setCount(count - 1) for decreasing.\"}],\"level_id\":8},{\"title\":\"Search Users\",\"prompt\":\"Build a React search box that filters a list of users based on the entered name.\",\"difficulty\":\"Easy\",\"type\":\"frontend\",\"detail\":{\"scenario\":\"Display the users in a list. When the user types in the search box, show only matching names.\",\"constraints\":\"Filtering should work without reloading the page.\"},\"templates\":[{\"language\":\"javascript\",\"starter_code\":\"import React, { useState } from \'react\';\\n\\nconst users = [\'Alice\', \'Bob\', \'Charlie\', \'David\'];\\n\\nexport default function App() {\\n  const [search, setSearch] = useState(\'\');\\n\\n  return (\\n    <div>\\n      <h1>Users</h1>\\n      <input\\n        type=\\\"text\\\"\\n        placeholder=\\\"Search user\\\"\\n        value={search}\\n        onChange={(e) => setSearch(e.target.value)}\\n      />\\n      {/* Display filtered users here */}\\n    </div>\\n  );\\n}\"}],\"hints\":[{\"type\":\"hint\",\"content\":\"Use filter() and includes() to find matching users.\"}],\"level_id\":8},{\"title\":\"Todo List\",\"prompt\":\"Build a simple React todo list where the user can enter a task and add it to the list.\",\"difficulty\":\"Easy\",\"type\":\"frontend\",\"detail\":{\"scenario\":\"Provide an input and Add button. When the button is clicked, add the entered task to the todo list.\",\"constraints\":\"Use useState to store the todo items.\"},\"templates\":[{\"language\":\"javascript\",\"starter_code\":\"import React, { useState } from \'react\';\\n\\nexport default function App() {\\n  const [task, setTask] = useState(\'\');\\n  const [todos, setTodos] = useState([]);\\n\\n  return (\\n    <div>\\n      <h1>Todo List</h1>\\n      <input\\n        value={task}\\n        onChange={(e) => setTask(e.target.value)}\\n        placeholder=\\\"Enter a task\\\"\\n      />\\n      <button>Add</button>\\n      {/* Display todos here */}\\n    </div>\\n  );\\n}\"}],\"hints\":[{\"type\":\"hint\",\"content\":\"Use setTodos([...todos, task]) to add a new task.\"}],\"level_id\":8},{\"title\":\"Show Hide Password\",\"prompt\":\"Build a React password input with a button that toggles the password between visible and hidden.\",\"difficulty\":\"Easy\",\"type\":\"frontend\",\"detail\":{\"scenario\":\"Initially show the password as hidden. Clicking the button should switch between password and text input types.\",\"constraints\":\"Use React state to control the input type.\"},\"templates\":[{\"language\":\"javascript\",\"starter_code\":\"import React, { useState } from \'react\';\\n\\nexport default function App() {\\n  const [showPassword, setShowPassword] = useState(false);\\n\\n  return (\\n    <div>\\n      <h1>Password</h1>\\n      <input\\n        type={showPassword ? \'text\' : \'password\'}\\n        placeholder=\\\"Enter password\\\"\\n      />\\n      <button onClick={() => setShowPassword(!showPassword)}>\\n        Show / Hide\\n      </button>\\n    </div>\\n  );\\n}\"}],\"hints\":[{\"type\":\"hint\",\"content\":\"Change the input type between \'text\' and \'password\' using the showPassword state.\"}],\"level_id\":8}]}','{\"created_count\":5,\"data\":[{\"id\":26,\"level_id\":8,\"title\":\"Simple Product List\",\"prompt\":\"Build a React component that displays a list of products with their names and prices.\",\"difficulty\":\"Easy\",\"type\":\"frontend\",\"created_at\":\"2026-09-17T08:01:12.094Z\",\"updated_at\":\"2026-09-17T08:01:12.094Z\"},{\"id\":27,\"level_id\":8,\"title\":\"Counter Button\",\"prompt\":\"Build a React counter with a number displayed on the screen and buttons to increase and decrease the value.\",\"difficulty\":\"Easy\",\"type\":\"frontend\",\"created_at\":\"2026-09-17T08:01:12.128Z\",\"updated_at\":\"2026-09-17T08:01:12.128Z\"},{\"id\":28,\"level_id\":8,\"title\":\"Search Users\",\"prompt\":\"Build a React search box that filters a list of users based on the entered name.\",\"difficulty\":\"Easy\",\"type\":\"frontend\",\"created_at\":\"2026-09-17T08:01:12.194Z\",\"updated_at\":\"2026-09-17T08:01:12.194Z\"},{\"id\":29,\"level_id\":8,\"title\":\"Todo List\",\"prompt\":\"Build a simple React todo list where the user can enter a task and add it to the list.\",\"difficulty\":\"Easy\",\"type\":\"frontend\",\"created_at\":\"2026-09-17T08:01:12.245Z\",\"updated_at\":\"2026-09-17T08:01:12.245Z\"},{\"id\":30,\"level_id\":8,\"title\":\"Show Hide Password\",\"prompt\":\"Build a React password input with a button that toggles the password between visible and hidden.\",\"difficulty\":\"Easy\",\"type\":\"frontend\",\"created_a