\":26,\"constraints\":\"Use React and map() to render the products.\",\"expected_approach\":\"\",\"expected_complexity\":\"\",\"ideal_answer\":\"\",\"scenario\":\"Display the given products as simple cards. Each card should show the product name and price.\",\"correct_option\":\"\",\"explanation\":\"\",\"created_at\":\"2026-09-17T08:01:12.095Z\",\"updated_at\":\"2026-09-17T08:01:12.095Z\"},\"templates\":[{\"id\":6,\"question_id\":26,\"language\":\"javascript\",\"starter_code\":\"import React from \'react\';\\n\\nconst products = [\\n  { id: 1, name: \'Laptop\', price: 50000 },\\n  { id: 2, name: \'Mouse\', price: 1000 },\\n  { id: 3, name: \'Keyboard\', price: 2000 }\\n];\\n\\nexport default function App() {\\n  return (\\n    \\u003cdiv\\u003e\\n      \\u003ch1\\u003eProducts\\u003c/h1\\u003e\\n      {/* Display products here */}\\n    \\u003c/div\\u003e\\n  );\\n}\",\"created_at\":\"2026-09-17T08:01:12.096Z\",\"updated_at\":\"2026-09-17T08:01:12.096Z\"}],\"hints\":[{\"id\":71,\"question_id\":26,\"type\":\"hint\",\"content\":\"Use products.map() to display each product.\",\"order_index\":1,\"created_at\":\"2026-09-17T08:01:12.106Z\",\"updated_at\":\"2026-09-17T08:01:12.106Z\"}],\"created_at\":\"2026-09-17T08:01:12.094Z\",\"updated_at\":\"2026-09-17T08:01:12.094Z\"},{\"id\":27,\"level_id\":8,\"title\":\"Counter Button\",\"prompt\":\"Build a React counter with a number displayed on the screen and buttons to increase and decrease the value.\",\"difficulty\":\"Easy\",\"type\":\"frontend\",\"detail\":{\"id\":27,\"question_id\":27,\"constraints\":\"Use React useState for the counter value.\",\"expected_approach\":\"\",\"expected_complexity\":\"\",\"ideal_answer\":\"\",\"scenario\":\"The counter starts at 0. Clicking + increases the value by 1 and clicking - decreases it by 1.\",\"correct_option\":\"\",\"explanation\":\"\",\"created_at\":\"2026-09-17T08:01:12.133Z\",\"updated_at\":\"2026-09-17T08:01:12.133Z\"},\"templates\":[{\"id\":7,\"question_id\":27,\"language\":\"javascript\",\"starter_code\":\"import React, { useState } from \'react\';\\n\\nexport default function App() {\\n  const [count, setCount] = useState(0);\\n\\n  return (\\n    \\u003cdiv\\u003e\\n      \\u003ch1\\u003eCounter\\u003c/h1\\u003e\\n      \\u003cp\\u003e{count}\\u003c/p\\u003e\\n      {/* Add buttons here */}\\n    \\u003c/div\\u003e\\n  );\\n}\",\"created_at\":\"2026-09-17T08:01:12.143Z\",\"updated_at\":\"2026-09-17T08:01:12.143Z\"}],\"hints\":[{\"id\":72,\"question_id\":27,\"type\":\"hint\",\"content\":\"Use setCount(count + 1) for increasing and setCount(count - 1) for decreasing.\",\"order_index\":1,\"created_at\":\"2026-09-17T08:01:12.147Z\",\"updated_at\":\"2026-09-17T08:01:12.147Z\"}],\"created_at\":\"2026-09-17T08:01:12.128Z\",\"updated_at\":\"2026-09-17T08:01:12.128Z\"},{\"id\":28,\"level_id\":8,\"title\":\"Search Users\",\"prompt\":\"Build a React search box that filters a list of users based on the entered name.\",\"difficulty\":\"Easy\",\"type\":\"frontend\",\"detail\":{\"id\":28,\"question_id\":28,\"constraints\":\"Filtering should work without reloading the page.\",\"expected_approach\":\"\",\"expected_complexity\":\"\",\"ideal_answer\":\"\",\"scenario\":\"Display the users in a list. When the user types in the search box, show only matching names.\",\"correct_option\":\"\",\"explanation\":\"\",\"created_at\":\"2026-09-17T08:01:12.195Z\",\"updated_at\":\"2026-09-17T08:01:12.195Z\"},\"templates\":[{\"id\":8,\"question_id\":28,\"language\":\"javascript\",\"starter_code\":\"import React, { useState } from \'react\';\\n\\nconst users = [\'Alice\', \'Bob\', \'Charlie\', \'David\'];\\n\\nexport default function App() {\\n  const [search, setSearch] = useState(\'\');\\n\\n  return (\\n    \\u003cdiv\\u003e\\n      \\u003ch1\\u003eUsers\\u003c/h1\\u003e\\n      \\u003cinput\\n        type=\\\"text\\\"\\n        placeholder=\\\"Search user\\\"\\n        value={search}\\n        onChange={(e) =\\u003e setSearch(e.target.value)}\\n      /\\u003e\\n      {/* Display filtered users here */}\\n    \\u003c/div\\u003e\\n  );\\n}\",\"created_at\":\"2026-09-17T08:01:12.197Z\",\"updated_at\":\"2026-09-17T08:01:12.197Z\"}],\"hints\":[{\"id\":73,\"question_id\":28,\"type\":\"hint\",\"content\":\"Use filter() and includes() to find matching users.\",\"order_index\":1,\"created_at\":\"2026-09-17T08:01:12.21Z\",\"updated_at\":\"2026-09-17T08:01:12.21Z\"}],\"created_at\":\"2026-09-17T08:01:12.194Z\",\"updated_at\":\"2026-09-17T08:01:12.194Z\"},{\"id\":29,\"level_id\":8,\"title\":\"Todo List\",\"prompt\":\"Build a simple React todo list where the user can enter a task and add it to the list.\",\"difficulty\":\"Easy\",\"type\":\"frontend\",\"detail\":{\"id\":29,\"question_id\":29,\"constraints\":\"Use useState to store the todo items.\",\"expected_approach\":\"\",\"expected_complexity\":\"\",\"ideal_answer\":\"\",\"scenario\":\"Provide an input and Add button. When the button is clicked, add the entered task to the todo list.\",\"correct_option\":\"\",\"explanation\":\"\",\"created_at\":\"2026-09-17T08:01:12.248Z\",\"updated_at\":\"2026-09-17T08:01:12.248Z\"},\"templates\":[{\"id\":9,\"question_id\":29,\"language\":\"javascript\",\"starter_code\":\"import React, { useState } from \'react\';\\n\\nexport default function App() {\\n  const [task, setTask] = useState(\'\');\\n  const [todos, setTodos] = useState([]);\\n\\n  return (\\n    \\u003cdiv\\u003e\\n      \\u003ch1\\u003eTodo List\\u003c/h1\\u003e\\n      \\u003cinput\\n        value={task}\\n        onChange={(e) =\\u003e setTask(e.target.value)}\\n        placeholder=\\\"Enter a task\\\"\\n      /\\u003e\\n      \\u003cbutton\\u003eAdd\\u003c/button\\u003e\\n      {/* Display todos here */}\\n    \\u003c/div\\u003e\\n  );\\n}\",\"created_at\":\"2026-09-17T08:01:12.26Z\",\"updated_at\":\"2026-09-17T08:01:12.26Z\"}],\"hints\":[{\"id\":74,\"question_id\":29,\"type\":\"hint\",\"content\":\"Use setTodos([...todos, task]) to add a new task.\",\"order_index\":1,\"created_at\":\"2026-09-17T08:01:12.261Z\",\"updated_at\":\"2026-09-17T08:01:12.261Z\"}],\"created_at\":\"2026-09-17T08:01:12.245Z\",\"updated_at\":\"2026-09-17T08:01:12.245Z\"},{\"id\":30,\"level_id\":8,\"title\":\"Show Hide Password\",\"prompt\":\"Build a React password input with a button that toggles the password between visible and hidden.\",\"difficulty\":\"Easy\",\"type\":\"frontend\",\"detail\":{\"id\":30,\"question_id\":30,\"constraints\":\"Use React state to control the input type.\",\"expected_approach\":\"\",\"expected_complexity\":\"\",\"ideal_answer\":\"\",\"scenario\":\"Initially show the password as hidden. Clicking the button should switch between password and text input types.\",\"correct_option\":\"\",\"explanation\":\"\",\"created_at\":\"2026-09-17T08:01:12.295Z\",\"updated_at\":\"2026-09-17T08:01:12.295Z\"},\"templates\":[{\"id\":10,\"question_id\":30,\"language\":\"javascript\",\"starter_code\":\"import React, { useState } from \'react\';\\n\\nexport default function App() {\\n  const [showPassword, setShowPassword] = useState(false);\\n\\n  return (\\n    \\u003cdiv\\u003e\\n      \\u003ch1\\u003ePassword\\u003c/h1\\u003e\\n      \\u003cinput\\n        type={showPassword ? \'text\' : \'password\'}\\n        placeholder=\\\"Enter password\\\"\\n      /\\u003e\\n      \\u003cbutton onClick={() =\\u003e setShowPassword(!showPassword)}\\u003e\\n        Show / Hide\\n      \\u003c/button\\u003e\\n    \\u003c/div\\u003e\\n  );\\n}\",\"created_at\":\"2026-09-17T08:01:12.296Z\",\"updated_at\":\"2026-09-17T08:01:12.296Z\"}],\"hints\":[{\"id\":75,\"question_id\":30,\"type\":\"hint\",\"content\":\"Change the input type between \'text\' and \'password\' using the showPassword state.\",\"order_index\":1,\"created_at\":\"2026-09-17T08:01:12.306Z\",\"updated_at\":\"2026-09-17T08:01:12.306Z\"}],\"created_at\":\"2026-09-17T08:01:12.293Z\",\"updated_at\":\"2026-09-17T08:01:12.293Z\"}],\"status\":\"success\"}','','2026-09-17 08:04:37.207'),(371,2,'admin@bitsathy.ac.in','System A