 the created user with an auto-generated ID.\",\"difficulty\":\"Easy\",\"type\":\"backend\",\"detail\":{\"id\":31,\"question_id\":31,\"constraints\":\"User name must not be empty. Return HTTP 400 for an empty name and HTTP 201 when a user is created.\",\"expected_approach\":\"Store users in memory and handle POST /users.\",\"expected_complexity\":\"\",\"ideal_answer\":\"\",\"scenario\":\"\",\"correct_option\":\"\",\"explanation\":\"\",\"created_at\":\"2026-09-17T08:02:22.678Z\",\"updated_at\":\"2026-09-17T08:02:22.678Z\"},\"test_cases\":[{\"id\":21,\"question_id\":31,\"input\":\"POST /users {\\\"name\\\":\\\"Alice\\\"}\",\"expected_output\":\"201 {\\\"id\\\":1,\\\"name\\\":\\\"Alice\\\"}\",\"is_hidden\":false,\"explanation\":\"\",\"order_index\":1,\"created_at\":\"2026-09-17T08:02:22.68Z\",\"updated_at\":\"2026-09-17T08:02:22.68Z\"},{\"id\":22,\"question_id\":31,\"input\":\"POST /users {\\\"name\\\":\\\"\\\"}\",\"expected_output\":\"400 {\\\"error\\\":\\\"Name required\\\"}\",\"is_hidden\":true,\"explanation\":\"\",\"order_index\":2,\"created_at\":\"2026-09-17T08:02:22.683Z\",\"updated_at\":\"2026-09-17T08:02:22.683Z\"}],\"hints\":[{\"id\":76,\"question_id\":31,\"type\":\"hint\",\"content\":\"Check the request method and validate the user name before creating the user.\",\"order_index\":1,\"created_at\":\"2026-09-17T08:02:22.687Z\",\"updated_at\":\"2026-09-17T08:02:22.687Z\"}],\"created_at\":\"2026-09-17T08:02:22.674Z\",\"updated_at\":\"2026-09-17T08:02:22.674Z\"},{\"id\":32,\"level_id\":10,\"title\":\"Get User By ID\",\"prompt\":\"Implement a REST API that returns a user when given their ID.\",\"difficulty\":\"Easy\",\"type\":\"backend\",\"detail\":{\"id\":32,\"question_id\":32,\"constraints\":\"Return HTTP 200 when the user exists and HTTP 404 when the user does not exist.\",\"expected_approach\":\"Find the user by ID from an in-memory list.\",\"expected_complexity\":\"\",\"ideal_answer\":\"\",\"scenario\":\"\",\"correct_option\":\"\",\"explanation\":\"\",\"created_at\":\"2026-09-17T08:02:22.725Z\",\"updated_at\":\"2026-09-17T08:02:22.725Z\"},\"test_cases\":[{\"id\":23,\"question_id\":32,\"input\":\"GET /users/1\",\"expected_output\":\"200 {\\\"id\\\":1,\\\"name\\\":\\\"Alice\\\"}\",\"is_hidden\":false,\"explanation\":\"\",\"order_index\":1,\"created_at\":\"2026-09-17T08:02:22.727Z\",\"updated_at\":\"2026-09-17T08:02:22.727Z\"},{\"id\":24,\"question_id\":32,\"input\":\"GET /users/99\",\"expected_output\":\"404 {\\\"error\\\":\\\"User not found\\\"}\",\"is_hidden\":true,\"explanation\":\"\",\"order_index\":2,\"created_at\":\"2026-09-17T08:02:22.728Z\",\"updated_at\":\"2026-09-17T08:02:22.728Z\"}],\"hints\":[{\"id\":77,\"question_id\":32,\"type\":\"hint\",\"content\":\"Extract the ID from the URL and search for the matching user.\",\"order_index\":1,\"created_at\":\"2026-09-17T08:02:22.729Z\",\"updated_at\":\"2026-09-17T08:02:22.729Z\"}],\"created_at\":\"2026-09-17T08:02:22.724Z\",\"updated_at\":\"2026-09-17T08:02:22.724Z\"},{\"id\":33,\"level_id\":10,\"title\":\"List Products\",\"prompt\":\"Implement a REST API that returns all products and optionally filters them by category.\",\"difficulty\":\"Easy\",\"type\":\"backend\",\"detail\":{\"id\":33,\"question_id\":33,\"constraints\":\"GET /products should return all products. A category query parameter should return only matching products.\",\"expected_approach\":\"Read the category query parameter and filter the products when it is provided.\",\"expected_complexity\":\"\",\"ideal_answer\":\"\",\"scenario\":\"\",\"correct_option\":\"\",\"explanation\":\"\",\"created_at\":\"2026-09-17T08:02:22.761Z\",\"updated_at\":\"2026-09-17T08:02:22.761Z\"},\"test_cases\":[{\"id\":25,\"question_id\":33,\"input\":\"GET /products\",\"expected_output\":\"200 [{\\\"id\\\":1,\\\"name\\\":\\\"Laptop\\\",\\\"category\\\":\\\"Electronics\\\"},{\\\"id\\\":2,\\\"name\\\":\\\"Chair\\\",\\\"category\\\":\\\"Furniture\\\"}]\",\"is_hidden\":false,\"explanation\":\"\",\"order_index\":1,\"created_at\":\"2026-09-17T08:02:22.769Z\",\"updated_at\":\"2026-09-17T08:02:22.769Z\"},{\"id\":26,\"question_id\":33,\"input\":\"GET /products?category=Electronics\",\"expected_output\":\"200 [{\\\"id\\\":1,\\\"name\\\":\\\"Laptop\\\",\\\"category\\\":\\\"Electronics\\\"}]\",\"is_hidden\":true,\"explanation\":\"\",\"order_index\":2,\"created_at\":\"2026-09-17T08:02:22.771Z\",\"updated_at\":\"2026-09-17T08:02:22.771Z\"}],\"hints\":[{\"id\":78,\"question_id\":33,\"type\":\"hint\",\"content\":\"Use filter() when a category is provided.\",\"order_index\":1,\"created_at\":\"2026-09-17T08:02:22.775Z\",\"updated_at\":\"2026-09-17T08:02:22.775Z\"}],\"created_at\":\"2026-09-17T08:02:22.76Z\",\"updated_at\":\"2026-09-17T08:02:22.76Z\"},{\"id\":34,\"level_id\":10,\"title\":\"Update User\",\"prompt\":\"Implement a REST API that updates the name of an existing user.\",\"difficulty\":\"Easy\",\"type\":\"backend\",\"detail\":{\"id\":34,\"question_id\":34,\"constraints\":\"Use PATCH /users/:id. Return HTTP 200 after a successful update and HTTP 404 when the user does not exist.\",\"expected_approach\":\"Find the user by ID and update the name using the request body.\",\"expected_complexity\":\"\",\"ideal_answer\":\"\",\"scenario\":\"\",\"correct_option\":\"\",\"explanation\":\"\",\"created_at\":\"2026-09-17T08:02:22.804Z\",\"updated_at\":\"2026-09-17T08:02:22.804Z\"},\"test_cases\":[{\"id\":27,\"question_id\":34,\"input\":\"PATCH /users/1 {\\\"name\\\":\\\"John\\\"}\",\"expected_output\":\"200 {\\\"id\\\":1,\\\"name\\\":\\\"John\\\"}\",\"is_hidden\":false,\"explanation\":\"\",\"order_index\":1,\"created_at\":\"2026-09-17T08:02:22.809Z\",\"updated_at\":\"2026-09-17T08:02:22.809Z\"},{\"id\":28,\"question_id\":34,\"input\":\"PATCH /users/99 {\\\"name\\\":\\\"John\\\"}\",\"expected_output\":\"404 {\\\"error\\\":\\\"User not found\\\"}\",\"is_hidden\":true,\"explanation\":\"\",\"order_index\":2,\"created_at\":\"2026-09-17T08:02:22.81Z\",\"updated_at\":\"2026-09-17T08:02:22.81Z\"}],\"hints\":[{\"id\":79,\"q