6.381'),(392,2,'admin@bitsathy.ac.in','System Administrator','admin','GET','/api/v1/admin/interviews/levels/12','','2a09:bac1:36c0:128::2a7:70','Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/153.0.0.0 Safari/537.36',200,5,'','{\"data\":{\"created_at\":\"2026-09-17T07:44:11Z\",\"description\":\"OS scheduling, memory management, TCP/IP, and SQL concepts\",\"duration_minutes\":25,\"id\":12,\"level_number\":1,\"mode\":\"mcq\",\"name\":\"Core CS Quick Quiz\",\"question_count\":15,\"questions_count\":0,\"track_id\":6,\"updated_at\":\"2026-09-17T07:44:11Z\"},\"status\":\"success\"}','','2026-09-17 08:26:56.381'),(393,2,'admin@bitsathy.ac.in','System Administrator','admin','POST','/api/v1/admin/interviews/levels/12/questions/bulk','','2a09:bac1:36c0:128::2a7:70','Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/153.0.0.0 Safari/537.36',200,1065,'{\"questions\":[{\"title\":\"Operating System\",\"prompt\":\"Which of the following is an operating system?\",\"difficulty\":\"Easy\",\"type\":\"mcq\",\"detail\":{\"correct_option\":\"A\",\"explanation\":\"Linux is an operating system used to manage computer hardware and software resources.\"},\"mcq_options\":[{\"option_key\":\"A\",\"option_text\":\"Linux\",\"is_correct\":true},{\"option_key\":\"B\",\"option_text\":\"MySQL\",\"is_correct\":false},{\"option_key\":\"C\",\"option_text\":\"HTML\",\"is_correct\":false},{\"option_key\":\"D\",\"option_text\":\"Git\",\"is_correct\":false}],\"hints\":[{\"type\":\"interview_tip\",\"content\":\"An operating system manages hardware and provides services to applications.\"}],\"level_id\":12},{\"title\":\"Process\",\"prompt\":\"What is a process in an operating system?\",\"difficulty\":\"Easy\",\"type\":\"mcq\",\"detail\":{\"correct_option\":\"B\",\"explanation\":\"A process is a program that is currently being executed.\"},\"mcq_options\":[{\"option_key\":\"A\",\"option_text\":\"A stored file\",\"is_correct\":false},{\"option_key\":\"B\",\"option_text\":\"A program in execution\",\"is_correct\":true},{\"option_key\":\"C\",\"option_text\":\"A database table\",\"is_correct\":false},{\"option_key\":\"D\",\"option_text\":\"A network cable\",\"is_correct\":false}],\"hints\":[{\"type\":\"interview_tip\",\"content\":\"Think about what happens when you run a program.\"}],\"level_id\":12},{\"title\":\"Thread\",\"prompt\":\"What is a thread?\",\"difficulty\":\"Easy\",\"type\":\"mcq\",\"detail\":{\"correct_option\":\"C\",\"explanation\":\"A thread is the smallest unit of execution within a process.\"},\"mcq_options\":[{\"option_key\":\"A\",\"option_text\":\"A database\",\"is_correct\":false},{\"option_key\":\"B\",\"option_text\":\"A compiler\",\"is_correct\":false},{\"option_key\":\"C\",\"option_text\":\"A unit of execution\",\"is_correct\":true},{\"option_key\":\"D\",\"option_text\":\"A storage device\",\"is_correct\":false}],\"hints\":[{\"type\":\"interview_tip\",\"content\":\"A process can contain one or more threads.\"}],\"level_id\":12},{\"title\":\"RAM\",\"prompt\":\"Which type of memory is volatile?\",\"difficulty\":\"Easy\",\"type\":\"mcq\",\"detail\":{\"correct_option\":\"A\",\"explanation\":\"RAM is volatile memory, so its contents are lost when power is turned off.\"},\"mcq_options\":[{\"option_key\":\"A\",\"option_text\":\"RAM\",\"is_correct\":true},{\"option_key\":\"B\",\"option_text\":\"ROM\",\"is_correct\":false},{\"option_key\":\"C\",\"option_text\":\"SSD\",\"is_correct\":false},{\"option_key\":\"D\",\"option_text\":\"Hard Disk\",\"is_correct\":false}],\"hints\":[{\"type\":\"interview_tip\",\"content\":\"Volatile memory loses its data when power is removed.\"}],\"level_id\":12},{\"title\":\"CPU\",\"prompt\":\"What is the main function of the CPU?\",\"difficulty\":\"Easy\",\"type\":\"mcq\",\"detail\":{\"correct_option\":\"D\",\"explanation\":\"The CPU executes instructions and performs calculations required by programs.\"},\"mcq_options\":[{\"option_key\":\"A\",\"option_text\":\"Store files permanently\",\"is_correct\":false},{\"option_key\":\"B\",\"option_text\":\"Connect computers to the internet\",\"is_correct\":false},{\"option_key\":\"C\",\"option_text\":\"Display images\",\"is_correct\":false},{\"option_key\":\"D\",\"option_text\":\"Execute instructions\",\"is_correct\":true}],\"hints\":[{\"type\":\"interview_tip\",\"content\":\"The CPU is responsible for executing program instructions.\"}],\"level_id\":12},{\"title\":\"Stack\",\"prompt\":\"Which principle does a stack follow?\",\"difficulty\":\"Easy\",\"type\":\"mcq\",\"detail\":{\"correct_option\":\"B\",\"explanation\":\"A stack follows Last In, First Out (LIFO).\"},\"mcq_options\":[{\"option_key\":\"A\",\"option_text\":\"FIFO\",\"is_correct\":false},{\"option_key\":\"B\",\"option_text\":\"LIFO\",\"is_correct\":true},{\"option_key\":\"C\",\"option_text\":\"Random order\",\"is_correct\":false},{\"option_key\":\"D\",\"option_text\":\"Priority order\",\"is_correct\":false}],\"hints\":[{\"type\":\"interview_tip\",\"content\":\"Think about a stack of plates.\"}],\"level_id\":12},{\"title\":\"Queue\",\"prompt\":\"Which principle does a queue follow?\",\"difficulty\":\"Easy\",\"type\":\"mcq\",\"detail\":{\"correct_option\":\"A\",\"explanation\":\"A queue follows First In, First Out (FIFO).\"},\"mcq_options\":[{\"option_key\":\"A\",\"option_text\":\"FIFO\",\"is_correct\":true},{\"option_key\":\"B\",\"option_text\":\"LIFO\",\"is_correct\":false},{\"option_key\":\"C\",\"option_text\":\"Random order\",\"is_correct\":false},{\"option_key\":\"D\",\"option_text\":\"Reverse order\",\"is_correct\":false}],\"hints\":[{\"type\":\"interview_tip\",\"content\":\"Think about people waiting in a line.\"}],\"level_id\":12},{\"title\":\"Binary Search\",\"prompt\":\"What is the time complexity of binary search on a sorted array?\",\"difficulty\":\"Easy\",\"type\":\"mcq\",\"detail\":{\"correct_option\":\"C\",\"explanation\":\"Binary search eliminates half of the remaining elements at each step, giving O(log N) time.\"},\"mcq_options\":[{\"option_key\":\"A\",\"option_text\":\"O(1)\",\"is_correct\":false},{\"option_key\":\"B\",\"option_text\":\"O(N)\",\"is_correct\":false},{\"option_key\":\"C\",\"option_text\":\"O(log N)\",\"is_correct\":true},{\"option_key\":\"D\",\"option_text\":\"O(N^2)\",\"is_correct\":false}],\"hints\":[{\"type\":\"interview_tip\",\"content\":\"Each search step removes approximately half of the elements.\"}],\"level_id\":12},{\"title\":\"Array Access\",\"prompt\":\"What is the average time complexity of accessing an element by index in an array?\",\"difficulty\":\"Easy\",\"type\":\"mcq\",\"detail\":{\"correct_option\":\"A\",\"explanation\":\"Arrays provide direct access using an index, which takes O(1) time.\"},\"mcq_options\":[{\"option_key\":\"A\",\"option_text\":\"O(1)\",\"is_correct\":true},{\"option_key\":\"B\",\"option_text\":\"O(log N)\",\"is_correct\":false},{\"option_key\":\"C\",\"option_text\":\"O(N)\",\"is_correct\":false},{\"option_key\":\"D\",\"option_text\":\"O(N^2)\",\"is_correct\":false}],\"hints\":[{\"type\":\"interview_tip\",\"content\":\"Array indexing allows direct access to an element.\"}],\"level_id\":12},{\"title\":\"Linked List\",\"prompt\":\"Which data structure stores elements using nodes connected by links?\",\"difficulty\":\"Easy\",\"type\":\"mcq\",\"detail\":{\"correct_option\":\"D\",\"explanation\":\"A linked list consists of nodes where each node stores data and a reference to another node.\"},\"mcq_options\":[{\"option_key\":\"A\",\"option_text\":\"Array\",\"is_correct\":false},{\"option_key\":\"B\",\"option_text\":\"Stack\",\"is_correct\":false},{\"option_key\":\"C\",\"option_text\":\"Heap\",\"is_correct\":false},{\"option_key\":\"D\",\"option_text\":\"Linked List\",\"is_correct\":true}],\"hints\":[{\"type\":\"interview_tip\",\"content\":\"Linked list nodes are connected using references or pointers.\"}],\"level_id\":12},{\"title\":\"Hash Table\",\"prompt\":\"What is the average time complexity of searching for a key in a hash table?\",\"difficulty\":\"Medium\",\"type\":\"mcq\",\"detail\":{\"correct_option\":\"B\",\"explanation\":\"With a good hash function and low collision rate, hash table lookup is O(1) on average.\"},\"mcq_options\":[{\"option_key\":\"A\",\"option_text\":\"O(N)\",\"is_correct\":false},{\"option_key\":\"B\",\"option_text\":\"O(1)\",\"is_correct\":true},{\"option_key\":\"C\",\"option_text\":\"O(log N)\",\"is_correct\":false},{\"option_key\":\"D\",\"option_text\":\"O(N^2)\",\"is_correct\":false}],\"hints\":[{\"type\":\"interview_tip\",\"content\":\"Hashing is designed for fast key-based lookup.\"}],\"level_id\":12},{\"title\":\"Binary Tree\",\"prompt\":\"What is the maximum number of children a node can have in a binary tree?\",\"difficulty\":\"Easy\",\"type\":\"mcq\",\"detail\":{\"correct_option\":\"C\",\"explanation\":\"Each node in a binary tree can have at most two children.\"},\"mcq_options\":[{\"option_key\":\"A\",\"option_text\":\"1\",\"is_correct\":false},{\"option_key\":\"B\",\"option_text\":\"3\",\"is_correct\":false},{\"option_key\":\"C\",\"option_text\":\"2\",\"is_correct\":true},{\"option_key\":\"D\",\"option_text\":\"Unlimited\",\"is_correct\":false}],\"hints\":[{\"type\":\"interview_tip\",\"content\":\"The name binary refers to two.\"}],\"level_id\":12},{\"title\":\"BFS\",\"prompt\":\"Which data structure is commonly used to implement Breadth-First Search?\",\"difficulty\":\"Easy\",\"type\":\"mcq\",\"detail\":{\"correct_option\":\"A\",\"explanation\":\"BFS uses a queue to process nodes level by level.\"},\"mcq_options\":[{\"option_key\":\"A\",\"option_text\":\"Queue\",\"is_correct\":true},{\"option_key\":\"B\",\"option_text\":\"Stack\",\"is_correct\":false},{\"option_key\":\"C\",\"option_text\":\"Heap\",\"is_correct\":false},{\"option_key\":\"D\",\"option_text\":\"Array only\",\"is_correct\":false}],\"hints\":[{\"type\":\"interview_tip\",\"content\":\"BFS processes nodes level by level.\"}],\"level_id\":12},{\"title\":\"DFS\",\"prompt\":\"Which data structure is commonly used by iterative Depth-First Search?\",\"difficulty\":\"Easy\",\"type\":\"mcq\",\"detail\":{\"correct_option\":\"D\",\"explanation\":\"Iterative DFS commonly uses a stack. Recursive DFS uses the call stack.\"},\"mcq_options\":[{\"option_key\":\"A\",\"option_text\":\"Queue\",\"is_correct\":false},{\"option_key\":\"B\",\"option_text\":\"Hash table\",\"is_correct\":false},{\"option_key\":\"C\",\"option_text\":\"Priority queue\",\"is_correct\":false},{\"option_key\":\"D\",\"option_text\":\"Stack\",\"is_correct\":true}],\"hints\":[{\"type\":\"interview_tip\",\"content\":\"DFS explores one path deeply before moving to another.\"}],\"level_id\":12},{\"title\":\"SQL\",\"prompt\":\"Which language is commonly used to query relational databases?\",\"difficulty\":\"Easy\",\"type\":\"mcq\",\"detail\":{\"correct_option\":\"B\",\"explanation\":\"SQL is used to create, read, update, and delete data in relational databases.\"},\"mcq_options\":[{\"option_key\":\"A\",\"option_text\":\"HTML\",\"is_correct\":false},{\"option_key\":\"B\",\"option_text\":\"SQL\",\"is_correct\":true},{\"option_key\":\"C\",\"option_text\":\"CSS\",\"is_correct\":false},{\"option_key\":\"D\",\"option_text\":\"XML\",\"is_correct\":false}],\"hints\":[{\"type\":\"interview_tip\",\"content\":\"SQL stands for Structured Query Language.\"}],\"level_id\":12},{\"title\":\"Primary Key\",\"prompt\":\"What is the purpose of a primary key in a database table?\",\"difficulty\":\"Easy\",\"type\":\"mcq\",\"detail\":{\"correct_option\":\"C\",\"explanation\":\"A primary key uniquely identifies each row in a table.\"},\"mcq_options\":[{\"option_key\":\"A\",\"option_text\":\"Store duplicate rows\",\"is_correct\":false},{\"option_key\":\"B\",\"option_text\":\"Sort the table\",\"is_correct\":false},{\"option_key\":\"C\",\"option_text\":\"Uniquely identify a row\",\"is_correct\":true},{\"option_key\":\"D\",\"option_text\":\"Delete the table\",\"is_correct\":false}],\"hints\":[{\"type\":\"interview_tip\",\"content\":\"A primary key value must uniquely identify a record.\"}],\"level_id\":12},{\"title\":\"Foreign Key\",\"prompt\":\"What is the main purpose of a foreign key?\",\"difficulty\":\"Easy\",\"type\":\"mcq\",\"detail\":{\"correct_option\":\"A\",\"explanation\":\"A foreign key creates a relationship between tables by referencing a key in another table.\"},\"mcq_options\":[{\"option_key\":\"A\",\"option_text\":\"Create a relationship between tables\",\"is_correct\":true},{\"option_key\":\"B\",\"option_text\":\"Encrypt a table\",\"is_correct\":false},{\"option_key\":\"C\",\"option_text\":\"Sort records\",\"is_correct\":false},{\"option_key\":\"D\",\"option_text\":\"Create indexes only\",\"is_correct\":false}],\"hints\":[{\"type\":\"interview_tip\",\"content\":\"A foreign key usually references a primary or unique key.\"}],\"level_id\":12},{\"title\":\"Normalization\",\"prompt\":\"What is the main goal of database normalization?\",\"difficulty\":\"Medium\",\"type\":\"mcq\",\"detail\":{\"correct_option\":\"D\",\"explanation\":\"Normalization reduces unnecessary data duplication and helps maintain data consistency.\"},\"mcq_options\":[{\"option_key\":\"A\",\"option_text\":\"Increase duplicate data\",\"is_correct\":false},{\"option_key\":\"B\",\"option_text\":\"Make queries slower\",\"is_correct\":false},{\"option_key\":\"C\",\"option_text\":\"Remove all tables\",\"is_correct\":false},{\"option_key\":\"D\",\"option_text\":\"Reduce data redundancy\",\"is_correct\":true}],\"hints\":[{\"type\":\"interview_tip\",\"content\":\"Normalization organizes data to reduce unnecessary repetition.\"}],\"level_id\":12},{\"title\":\"HTTP GET\",\"prompt\":\"Which HTTP method is commonly used to retrieve data?\",\"difficulty\":\"Easy\",\"type\":\"mcq\",\"detail\":{\"correct_option\":\"B\",\"explanation\":\"GET is commonly used to request and retrieve data from a server.\"},\"mcq_options\":[{\"option_key\":\"A\",\"option_text\":\"POST\",\"is_correct\":false},{\"option_key\":\"B\",\"option_text\":\"GET\",\"is_correct\":true},{\"option_key\":\"C\",\"option_text\":\"DELETE\",\"is_correct\":false},{\"option_key\":\"D\",\"option_text\":\"PATCH\",\"is_correct\":false}],\"hints\":[{\"type\":\"interview_tip\",\"content\":\"GET is generally used when the client wants to read data.\"}],\"level_id\":12},{\"title\":\"HTTP POST\",\"prompt\":\"Which HTTP method is commonly used to create a new resource?\",\"difficulty\":\"Easy\",\"type\":\"mcq\",\"detail\":{\"correct_option\":\"A\",\"explanation\":\"POST is commonly used to submit data and create a new resource.\"},\"mcq_options\":[{\"option_key\":\"A\",\"option_text\":\"POST\",\"is_correct\":true},{\"option_key\":\"B\",\"option_text\":\"GET\",\"is_correct\":false},{\"option_key\":\"C\",\"option_text\":\"DELETE\",\"is_correct\":false},{\"option_key\":\"D\",\"option_text\":\"HEAD\",\"is_correct\":false}],\"hints\":[{\"type\":\"interview_tip\",\"content\":\"Think about submitting a form to create something on a server.\"}],\"level_id\":12},{\"title\":\"HTTP Status 404\",\"prompt\":\"What does HTTP status code 404 usually mean?\",\"difficulty\":\"Easy\",\"type\":\"mcq\",\"detail\":{\"correct_option\":\"C\",\"explanation\":\"404 means that the requested resource could not be found.\"},\"mcq_options\":[{\"option_key\":\"A\",\"option_text\":\"Request successful\",\"is_correct\":false},{\"option_key\":\"B\",\"option_text\":\"Server error\",\"is_correct\":false},{\"option_key\":\"C\",\"option_text\":\"Resource not found\",\"is_correct\":true},{\"option_key\":\"D\",\"option_text\":\"Unauthorized request\",\"is_correct\":false}],\"hints\":[{\"type\":\"interview_tip\",\"content\":\"Remember the common \'Not Found\' response.\"}],\"level_id\":12},{\"title\":\"HTTP Status 500\",\"prompt\":\"What does HTTP status code 500 usually indicate?\",\"difficulty\":\"Easy\",\"type\":\"mcq\",\"detail\":{\"correct_option\":\"D\",\"explanation\":\"500 indicates an internal server error.\"},\"mcq_options\":[{\"option_key\":\"A\",\"option_text\":\"Resource found\",\"is_correct\":false},{\"option_key\":\"B\",\"option_text\":\"Bad request from client\",\"is_correct\":false},{\"option_key\":\"C\",\"option_text\":\"Unauthorized\",\"is_correct\":false},{\"option_key\":\"D\",\"option_text\":\"Internal server error\",\"is_correct\":true}],\"hints\":[{\"type\":\"interview_tip\",\"content\":\"5xx status codes generally indicate server-side errors.\"}],\"level_id\":12},{\"title\":\"TCP\",\"prompt\":\"Which protocol provides reliable, connection-oriented communication?\",\"difficulty\":\"Easy\",\"type\":\"mcq\",\"detail\":{\"correct_option\":\"A\",\"explanation\":\"TCP provides reliable, ordered, connection-oriented data transmission.\"},\"mcq_options\":[{\"option_key\":\"A\",\"option_text\":\"TCP\",\"is_correct\":true},{\"option_key\":\"B\",\"option_text\":\"UDP\",\"is_correct\":false},{\"option_key\":\"C\",\"option_text\":\"DNS\",\"is_correct\":false},{\"option_key\":\"D\",\"option_text\":\"HTTP\",\"is_correct\":false}],\"hints\":[{\"type\":\"interview_tip\",\"content\":\"TCP focuses on reliable and ordered delivery.\"}],\"level_id\":12},{\"title\":\"UDP\",\"prompt\":\"Which protocol is generally faster but does not guarantee delivery?\",\"difficulty\":\"Easy\",\"type\":\"mcq\",\"detail\":{\"correct_option\":\"C\",\"explanation\":\"UDP is connectionless and does not provide TCP-style guarantees of delivery and ordering.\"},\"mcq_options\":[{\"option_key\":\"A\",\"option_text\":\"TCP\",\"is_correct\":false},{\"option_key\":\"B\",\"option_text\":\"HTTPS\",\"is_correct\":false},{\"option_key\":\"C\",\"option_text\":\"UDP\",\"is_correct\":true},{\"option_key\":\"D\",\"option_text\":\"SSH\",\"is_correct\":false}],\"hints\":[{\"type\":\"interview_tip\",\"content\":\"UDP trades some reliability features for lower overhead.\"}],\"level_id\":12},{\"title\":\"DNS\",\"prompt\":\"What is the main purpose of DNS?\",\"difficulty\":\"Easy\",\"type\":\"mcq\",\"detail\":{\"correct_option\":\"B\",\"explanation\":\"DNS translates domain names such as example.com into IP addresses.\"},\"mcq_options\":[{\"option_key\":\"A\",\"option_text\":\"Encrypt files\",\"is_correct\":false},{\"option_key\":\"B\",\"option_text\":\"Translate domain names to IP addresses\",\"is_correct\":true},{\"option_key\":\"C\",\"option_text\":\"Store passwords\",\"is_correct\":false},{\"option_key\":\"D\",\"option_text\":\"Compile programs\",\"is_correct\":false}],\"hints\":[{\"type\":\"interview_tip\",\"content\":\"DNS acts like a naming system for network resources.\"}],\"level_id\":12},{\"title\":\"OOP Encapsulation\",\"prompt\":\"Which OOP concept combines data and methods that operate on that data?\",\"difficulty\":\"Easy\",\"type\":\"mcq\",\"detail\":{\"correct_option\":\"A\",\"explanation\":\"Encapsulation bundles data and related methods together and can restrict direct access to internal state.\"},\"mcq_options\":[{\"option_key\":\"A\",\"option_text\":\"Encapsulation\",\"is_correct\":true},{\"option_key\":\"B\",\"option_text\":\"Inheritance\",\"is_correct\":false},{\"option_key\":\"C\",\"option_text\":\"Polymorphism\",\"is_correct\":false},{\"option_key\":\"D\",\"option_text\":\"Recursion\",\"is_correct\":false}],\"hints\":[{\"type\":\"interview_tip\",\"content\":\"Think about keeping an object\'s data and behavior together.\"}],\"level_id\":12},{\"title\":\"Inheritance\",\"prompt\":\"Which OOP concept allows a class to acquire properties and methods from another class?\",\"difficulty\":\"Easy\",\"type\":\"mcq\",\"detail\":{\"correct_option\":\"D\",\"explanation\":\"Inheritance allows a class to reuse or extend the properties and methods of another class.\"},\"mcq_options\":[{\"option_key\":\"A\",\"option_text\":\"Encapsulation\",\"is_correct\":false},{\"option_key\":\"B\",\"option_text\":\"Abstraction\",\"is_correct\":false},{\"option_key\":\"C\",\"option_text\":\"Compilation\",\"is_correct\":false},{\"option_key\":\"D\",\"option_text\":\"Inheritance\",\"is_correct\":true}],\"hints\":[{\"type\":\"interview_tip\",\"content\":\"A child class can reuse functionality from a parent class.\"}],\"level_id\":12},{\"title\":\"Polymorphism\",\"prompt\":\"What does polymorphism generally mean in OOP?\",\"difficulty\":\"Medium\",\"type\":\"mcq\",\"detail\":{\"correct_option\":\"C\",\"explanation\":\"Polymorphism allows the same interface or method call to have different behavior depending on the object.\"},\"mcq_options\":[{\"option_key\":\"A\",\"option_text\":\"One class only\",\"is_correct\":false},{\"option_key\":\"B\",\"option_text\":\"Hiding all data\",\"is_correct\":false},{\"option_key\":\"C\",\"option_text\":\"Same interface with different behavior\",\"is_correct\":true},{\"option_key\":\"D\",\"option_text\":\"Deleting objects\",\"is_correct\":false}],\"hints\":[{\"type\":\"interview_tip\",\"content\":\"Think of the same method call behaving differently for different objects.\"}],\"level_id\":12},{\"title\":\"Compiler\",\"prompt\":\"What does a compiler generally do?\",\"difficulty\":\"Easy\",\"type\":\"mcq\",\"detail\":{\"correct_option\":\"B\",\"explanation\":\"A compiler translates source code into another form, commonly machine code or an intermediate representation.\"},\"mcq_options\":[{\"option_key\":\"A\",\"option_text\":\"Store database records\",\"is_correct\":false},{\"option_key\":\"B\",\"option_text\":\"Translate source code\",\"is_correct\":true},{\"option_key\":\"C\",\"option_text\":\"Connect to Wi-Fi\",\"is_correct\":false},{\"option_key\":\"D\",\"option_text\":\"Manage files only\",\"is_correct\":false}],\"hints\":[{\"type\":\"interview_tip\",\"content\":\"A compiler processes source code before or during program execution.\"}],\"level_id\":12}]}','{\"created_count\":29,\"data\":[{\"id\":36,\"level_id\":12,\"title\":\"Operating System\",\"prompt\":\"Which of the following is an operating system?\",\"difficulty\":\"Easy\",\"type\":\"mcq\",\"created_at\":\"2026-09-17T08:27:36.25Z\",\"updated_at\":\"2026-09-17T08:27:36.25Z\"},{\"id\":37,\"level_id\":12,\"title\":\"Process\",\"prompt\":\"What is a process in an operating system?\",\"difficulty\":\"Easy\",\"type\":\"mcq\",\"created_at\":\"2026-09-17T08:27:36.291Z\",\"updated_at\":\"2026-09-17T08:27:36.291Z\"},{\"id\":38,\"level_id\":12,\"title\":\"Thread\",\"prompt\":\"What is a thread?\",\"difficulty\":\"Easy\",\"type\":\"mcq\",\"created_at\":\"2026-09-17T08:27:36.326Z\",\"updated_at\":\"2026-09-17T08:27:36.326Z\"},{\"id\":39,\"level_id\":12,\"title\":\"RAM\",\"prompt\":\"Which type of memory is volatile?\",\"difficulty\":\"Easy\",\"type\":\"mcq\",\"created_at\":\"2026-09-17T08:27:36.365Z\",\"updated_at\":\"2026-09-17T08:27:36.365Z\"},{\"id\":40,\"level_id\":12,\"title\":\"CPU\",\"prompt\":\"What is the main function of the CPU?\",\"difficulty\":\"Easy\",\"type\":\"mcq\",\"created_at\":\"2026-09-17T08:27:36.405Z\",\"updated_at\":\"2026-09-17T08:27:36.405Z\"},{\"id\":41,\"level_id\":12,\"title\":\"Stack\",\"prompt\":\"Which principle does a stack follow?\",\"difficulty\":\"Easy\",\"type\":\"mcq\",\"created_at\":\"2026-09-17T08:27:36.449Z\",\"updated_at\":\"2026-09-17T08:27:36.449Z\"},{\"id\":42,\"level_id\":12,\"title\":\"Queue\",\"prompt\":\"Which principle does a queue follow?\",\"difficulty\":\"Easy\",\"type\":\"mcq\",\"created_at\":\"2026-09-17T08:27:36.482Z\",\"updated_at\":\"2026-09-17T08:27:36.482Z\"},{\"id\":43,\"level_id\":12,\"title\":\"Binary Search\",\"prompt\":\"What is the time complexity of binary search on a sorted array?\",\"difficulty\":\"Easy\",\"type\":\"mcq\",\"created_at\":\"2026-09-17T08:27:36.517Z\",\"updated_at\":\"2026-09-17T08:27:36.517Z\"},{\"id\":44,\"level_id\":12,\"title\":\"Array Access\",\"prompt\":\"What is the average time complexity of accessing an element by index in an array?\",\"difficulty\":\"Easy\",\"type\":\"mcq\",\"created_at\":\"2026-09-17T08:27:36.548Z\",\"updated_at\":\"2026-09-17T08:27:36.548Z\"},{\"id\":45,\"level_id\":12,\"title\":\"Linked List\",\"prompt\":\"Which data structure stores elements using nodes connected by links?\",\"difficulty\":\"Easy\",\"type\":\"mcq\",\"created_at\":\"2026-09-17T08:27:36.582Z\",\"updated_at\":\"2026-09-17T08:27:36.582Z\"},{\"id\":46,\"level_id\":12,\"title\":\"Hash Table\",\"prompt\":\"What is the average time complexity of searching for a key in a hash table?\",\"difficulty\":\"Medium\",\"type\":\"mcq\",\"created_at\":\"2026-09-17T08:27:36.611Z\",\"updated_at\":\"2026-09-17T08:27:36.611Z\"},{\"id\":47,\"level_id\":12,\"title\":\"Binary Tree\",\"prompt\":\"What is the maximum number of children a node can have in a binary tree?\",\"difficulty\":\"Easy\",\"type\":\"mcq\",\"created_at\":\"2026-09-17T08:27:36.654Z\",\"updated_at\":\"2026-09-17T08:27:36.654Z\"},{\"id\":48,\"level_id\":12,\"title\":\"BFS\",\"prompt\":\"Which data structure is commonly used to implement Breadth-First Search?\",\"difficulty\":\"Easy\",\"type\":\"mcq\",\"created_at\":\"2026-09-17T08:27:36.687Z\",\"updated_at\":\"2026-09-17T08:27:36.687Z\"},{\"id\":49,\"level_id\":12,\"title\":\"DFS\",\"prompt\":\"Which data structure is commonly used by iterative Depth-First Search?\",\"difficulty\":\"Easy\",\"type\":\"mcq\",\"created_at\":\"2026-09-17T08:27:36.715Z\",\"updated_at\":\"2026-09-17T08:27:36.715Z\"},{\"id\":50,\"level_id\":12,\"title\":\"SQL\",\"prompt\":\"Which language is commonly used to query relational databases?\",\"difficulty\":\"Easy\",\"type\":\"mcq\",\"created_at\":\"2026-09-17T08:27:36.753Z\",\"updated_at\":\"2026-09-17T08:27:36.753Z\"},{\"id\":51,\"level_id\":12,\"title\":\"Primary Key\",\"prompt\":\"What is the purpose of a primary key in a database table?\",\"difficulty\":\"Easy\",\"type\":\"mcq\",\"created_at\":\"2026-09-17T08:27:36.774Z\",\"updated_at\":\"2026-09-17T08:27:36.774Z\"},{\"id\":52,\"level_id\":12,\"title\":\"Foreign Key\",\"prompt\":\"What is the main purpose of a foreign key?\",\"difficulty\":\"Easy\",\"type\":\"mcq\",\"created_at\":\"2026-09-17T08:27:36.805Z\",\"updated_at\":\"2026-09-17T08:27:36.805Z\"},{\"id\":53,\"level_id\":12,\"title\