-17T08:27:36.291Z\",\"updated_at\":\"2026-09-17T08:27:36.291Z\"},{\"id\":38,\"level_id\":12,\"title\":\"Thread\",\"prompt\":\"What is a thread?\",\"difficulty\":\"Easy\",\"type\":\"mcq\",\"detail\":{\"id\":38,\"question_id\":38,\"constraints\":\"\",\"expected_approach\":\"\",\"expected_complexity\":\"\",\"ideal_answer\":\"\",\"scenario\":\"\",\"correct_option\":\"C\",\"explanation\":\"A thread is the smallest unit of execution within a process.\",\"created_at\":\"2026-09-17T08:27:36.33Z\",\"updated_at\":\"2026-09-17T08:27:36.33Z\"},\"hints\":[{\"id\":83,\"question_id\":38,\"type\":\"interview_tip\",\"content\":\"A process can contain one or more threads.\",\"order_index\":1,\"created_at\":\"2026-09-17T08:27:36.337Z\",\"updated_at\":\"2026-09-17T08:27:36.337Z\"}],\"mcq_options\":[{\"id\":9,\"question_id\":38,\"option_key\":\"A\",\"option_text\":\"A database\",\"is_correct\":false,\"created_at\":\"2026-09-17T08:27:36.339Z\",\"updated_at\":\"2026-09-17T08:27:36.339Z\"},{\"id\":10,\"question_id\":38,\"option_key\":\"B\",\"option_text\":\"A compiler\",\"is_correct\":false,\"created_at\":\"2026-09-17T08:27:36.342Z\",\"updated_at\":\"2026-09-17T08:27:36.342Z\"},{\"id\":11,\"question_id\":38,\"option_key\":\"C\",\"option_text\":\"A unit of execution\",\"is_correct\":true,\"created_at\":\"2026-09-17T08:27:36.343Z\",\"updated_at\":\"2026-09-17T08:27:36.343Z\"},{\"id\":12,\"question_id\":38,\"option_key\":\"D\",\"option_text\":\"A storage device\",\"is_correct\":false,\"created_at\":\"2026-09-17T08:27:36.344Z\",\"updated_at\":\"2026-09-17T08:27:36.344Z\"}],\"created_at\":\"2026-09-17T08:27:36.326Z\",\"updated_at\":\"2026-09-17T08:27:36.326Z\"},{\"id\":39,\"level_id\":12,\"title\":\"RAM\",\"prompt\":\"Which type of memory is volatile?\",\"difficulty\":\"Easy\",\"type\":\"mcq\",\"detail\":{\"id\":39,\"question_id\":39,\"constraints\":\"\",\"expected_approach\":\"\",\"expected_complexity\":\"\",\"ideal_answer\":\"\",\"scenario\":\"\",\"correct_option\":\"A\",\"explanation\":\"RAM