uce K.\"],\"ideal_answer\":\"\",\"interview_tips\":[\"Ask why a normal sliding-window approach does not work when negative numbers are present.\"],\"open_test_cases\":[{\"explanation\":\"\",\"input\":\"3\\n1 1 1\\n2\",\"output\":\"2\"}],\"options\":null,\"rubrics\":null,\"scenario\":\"\",\"starter_code\":\"\",\"starter_code_cpp\":\"\",\"starter_code_java\":\"\",\"starter_code_js\":\"\",\"starter_code_py\":\"\",\"talking_points\":null,\"tradeoffs\":null},\"prompt\":\"Given an integer array and an integer K, count the number of contiguous subarrays whose sum equals K.\",\"rubrics\":null,\"talking_points\":null,\"templates\":[],\"test_cases\":[{\"explanation\":\"\",\"input\":\"3\\n1 1 1\\n2\",\"output\":\"2\"}],\"title\":\"Subarray Sum Equals K\",\"tradeoffs\":null,\"type\":\"coding\"},\"current_question_id\":9,\"end_requested_by\":0,\"ended_at\":null,\"id\":1,\"interviewee\":{\"name\":\"Peer Candidate\",\"roll_no\":\"CANDIDATE\",\"department\":\"Student Peer\"},\"interviewee_id\":4,\"interviewer\":{\"name\":\"Jaison David M\",\"email\":\"jaisondavidm.cs25@bitsathy.ac.in\",\"roll_no\":\"7376251CS221\",\"department\":\"CSE\"},\"interviewer_id\":3,\"interviewer_rubrics\":\"\",\"last_executed_at\":null,\"last_execution_json\":\"\",\"last_execution_passed\":0,\"last_execution_total\":0,\"last_execution_type\":\"\",\"last_execution_verdict\":\"\",\"level\":{\"id\":1,\"track_id\":1,\"level_number\":1,\"name\":\"Arrays, Strings \\u0026 HashMaps\",\"description\":\"Fundamental data structures and two-pointer techniques\",\"mode\":\"coding\",\"duration_minutes\":45,\"question_count\":1,\"questions\":[{\"id\":1,\"level_id\":1,\"title\":\"Two Sum with Target Lookup\",\"prompt\":\"Given an array of integers and a target integer, find the indices of two different elements whose sum equals the target. Print the two indices in increasing order. Exactly one valid pair exists.\",\"difficulty\":\"Easy\",\"type\":\"coding\",\"detail\":{\"id\":1,\"question_id\":1,\"constraints\":\"2 \\u00