n1 \\u003c= word.length \\u003c= 100\\nWords contain lowercase English letters.\\nTime Limit: 2.0s\\nMemory Limit: 256MB\",\"correct_option\":\"\",\"expected_approach\":\"Create a character-frequency signature for each word and use that signature as a HashMap key. Words with the same signature belong to the same group.\",\"expected_complexity\":\"Time: O(N * L), Space: O(N * L)\",\"explanation\":\"\",\"hints\":[\"Anagrams have the same character frequencies.\"],\"ideal_answer\":\"\",\"interview_tips\":[\"Ask the candidate to compare a sorted-string key with a frequency-based key.\"],\"open_test_cases\":[{\"explanation\":\"\",\"input\":\"6\\neat tea tan ate nat bat\",\"output\":\"eat tea ate\\ntan nat\\nbat\"}],\"options\":null,\"rubrics\":null,\"scenario\":\"\",\"starter_code\":\"\",\"starter_code_cpp\":\"\",\"starter_code_java\":\"\",\"starter_code_js\":\"\",\"starter_code_py\":\"\",\"talking_points\":null,\"tradeoffs\":null},\"prompt\":\"Given N strings, group strings that are anagrams of each other. Print each group on a separate line. Words within each group should remain in their original input order.\",\"rubrics\":null,\"talking_points\":null,\"templates\":[],\"test_cases\":[{\"explanation\":\"\",\"input\":\"6\\neat tea tan ate nat bat\",\"output\":\"eat tea ate\\ntan nat\\nbat\"}],\"title\":\"Group Anagrams\",\"tradeoffs\":null,\"type\":\"coding\"},\"current_question_id\":4,\"end_requested_by\":0,\"ended_at\":null,\"id\":2,\"interviewee\":{\"name\":\"Peer Candidate\",\"roll_no\":\"CANDIDATE\",\"department\":\"Student Peer\"},\"interviewee_id\":3,\"interviewer\":{\"name\":\"JagaPrasanth S\",\"email\":\"jagaprasanths.cs25@bitsathy.ac.in\",\"roll_no\":\"7376251CS219\",\"department\":\"CSE\"},\"interviewer_id\":4,\"interviewer_rubrics\":\"\",\"last_executed_at\":null,\"last_execution_json\":\"\",\"last_execution_passed\":0,\"last_execution_total\":0,\"last_execution_type\":\"\",\"last_execution_verdict\":\"\",\"level\":{\"id\":1,\"track_id\":1,\"level_number\":1,