rrent_question\":{\"correct_option\":\"\",\"created_at\":\"2026-09-17T07:52:40.194Z\",\"detail\":{\"id\":7,\"question_id\":7,\"constraints\":\"0 \\u003c= N \\u003c= 10^5\\n-10^9 \\u003c= nums[i] \\u003c= 10^9\\nDuplicate values may exist.\\nTime Limit: 2.0s\\nMemory Limit: 256MB\",\"expected_approach\":\"Insert all values into a HashSet. Start counting a sequence only when the current value has no predecessor, then repeatedly check for the next consecutive value.\",\"expected_complexity\":\"Time: O(N) average, Space: O(N)\",\"ideal_answer\":\"\",\"scenario\":\"\",\"correct_option\":\"\",\"explanation\":\"\",\"created_at\":\"2026-09-17T07:52:40.2Z\",\"updated_at\":\"2026-09-17T07:52:40.2Z\"},\"difficulty\":\"Medium\",\"explanation\":\"\",\"id\":7,\"ideal_answer\":\"\",\"interview_tips\":[\"Ask why sorting is not required and how duplicates are handled.\"],\"level_id\":1,\"mcq_options\":null,\"options\":null,\"payload\":{\"constraints\":\"0 \\u003c= N \\u003c= 10^5\\n-10^9 \\u003c= nums[i] \\u003c= 10^9\\nDuplicate values may exist.\\nTime Limit: 2.0s\\nMemory Limit: 256MB\",\"correct_option\":\"\",\"expected_approach\":\"Insert all values into a HashSet. Start counting a sequence only when the current value has no predecessor, then repeatedly check for the next consecutive value.\",\"expected_complexity\":\"Time: O(N) average, Space: O(N)\",\"explanation\":\"\",\"hints\":[\"Try putting all numbers into a HashSet.\"],\"ideal_answer\":\"\",\"interview_tips\":[\"Ask why sorting is not required and how duplicates are handled.\"],\"open_test_cases\":[{\"explanation\":\"\",\"input\":\"6\\n100 4 200 1 3 2\",\"output\":\"4\"}],\"options\":null,\"rubrics\":null,\"scenario\":\"\",\"starter_code\":\"\",\"starter_code_cpp\":\"\",\"starter_code_java\":\"\",\"starter_code_js\":\"\",\"starter_code_py\":\"\",\"talking_points\":null,\"tradeoffs\":null},\"prompt\":\"Given an unsorted array of integers, find the length of the longest sequence of consecutive integers. The elements do no