den\":true,\"explanation\":\"\",\"order_index\":2,\"created_at\":\"2026-09-17T07:52:40.395Z\",\"updated_at\":\"2026-09-17T07:52:40.395Z\"}],\"hints\":[{\"id\":19,\"question_id\":10,\"type\":\"hint\",\"content\":\"The most recently opened bracket must be closed first.\",\"order_index\":1,\"created_at\":\"2026-09-17T07:52:40.401Z\",\"updated_at\":\"2026-09-17T07:52:40.401Z\"},{\"id\":20,\"question_id\":10,\"type\":\"interview_tip\",\"content\":\"Ask why a stack is suitable for this problem and what happens when a closing bracket appears with an empty stack.\",\"order_index\":2,\"created_at\":\"2026-09-17T07:52:40.402Z\",\"updated_at\":\"2026-09-17T07:52:40.402Z\"}],\"created_at\":\"2026-09-17T07:52:40.371Z\",\"updated_at\":\"2026-09-17T07:52:40.371Z\"}],\"created_at\":\"2026-09-17T07:44:11Z\",\"updated_at\":\"2026-09-17T07:44:25.437Z\"},\"level_id\":1,\"level_questions\":[{\"correct_option\":\"\",\"created_at\":\"2026-09-17T07:52:39.705Z\",\"detail\":{\"id\":1,\"question_id\":1,\"constraints\":\"2 \\u003c= N \\u003c= 10^5\\n-10^9 \\u003c= nums[i] \\u003c= 10^9\\nExactly one valid answer exists.\\nTime Limit: 2.0s\\nMemory Limit: 256MB\",\"expected_approach\":\"Traverse the array once and use a HashMap to store previously visited numbers and their indices. For each number, check whether target - nums[i] already exists.\",\"expected_complexity\":\"Time: O(N), Space: O(N)\",\"ideal_answer\":\"\",\"scenario\":\"\",\"correct_option\":\"\",\"explanation\":\"\",\"created_at\":\"2026-09-17T07:52:39.716Z\",\"updated_at\":\"2026-09-17T07:52:39.716Z\"},\"difficulty\":\"Easy\",\"explanation\":\"\",\"id\":1,\"ideal_answer\":\"\",\"interview_tips\":[\"Ask why a nested-loop solution becomes O(N^2).\"],\"level_id\":1,\"mcq_options\":null,\"options\":null,\"payload\":{\"constraints\":\"2 \\u003c= N \\u003c= 10^5\\n-10^9 \\u003c= nums[i] \\u003c= 10^9\\nExactly one valid answer exists.\\nTime Limit: 2.0s\\nMemory Limit: 256MB\",\"correct_option\":\"\",\"expected_approach\":\"Traverse t