:\"Traverse the array once and use a HashMap to store previously visited numbers and their indices. For each number, check whether target - nums[i] already exists.\",\"expected_complexity\":\"Time: O(N), Space: O(N)\",\"ideal_answer\":\"\",\"scenario\":\"\",\"correct_option\":\"\",\"explanation\":\"\",\"created_at\":\"2026-09-17T07:52:39.716Z\",\"updated_at\":\"2026-09-17T07:52:39.716Z\"},\"difficulty\":\"Easy\",\"id\":1,\"level_id\":1,\"mcq_options\":null,\"options\":null,\"payload\":{\"constraints\":\"2 \\u003c= N \\u003c= 10^5\\n-10^9 \\u003c= nums[i] \\u003c= 10^9\\nExactly one valid answer exists.\\nTime Limit: 2.0s\\nMemory Limit: 256MB\",\"open_test_cases\":[{\"explanation\":\"\",\"input\":\"4\\n2 7 11 15\\n9\",\"output\":\"0 1\"}],\"options\":null,\"scenario\":\"\",\"starter_code\":\"\",\"starter_code_cpp\":\"\",\"starter_code_java\":\"\",\"starter_code_js\":\"\",\"starter_code_py\":\"\"},\"prompt\":\"Given an array of integers and a target integer, find the indices of two different elements whose sum equals the target. Print the two indices in increasing order. Exactly one valid pair exists.\",\"templates\":[],\"test_cases\":[{\"explanation\":\"\",\"input\":\"4\\n2 7 11 15\\n9\",\"output\":\"0 1\"}],\"title\":\"Two Sum with Target Lookup\",\"type\":\"coding\"}],\"roles_switched\":false,\"round\":1,\"started_at\":\"2026-09-17T09:24:54.21Z\",\"status\":\"in_progress\",\"switch_count\":0,\"switch_requested_by\":0,\"track\":{\"id\":1,\"title\":\"Data Structures \\u0026 Algorithms\",\"slug\":\"dsa\",\"category\":\"Technical\",\"icon\":\"Code\",\"description\":\"Core problem solving, arrays, trees, dynamic programming, and algorithmic complexity.\",\"created_at\":\"2026-09-17T07:43:11Z\",\"updated_at\":\"2026-09-17T07:43:11Z\"},\"track_id\":1}},\"status\":\"success\"}','','2026-09-17 09:25:00.337'),(1009,4,'jagaprasanths.cs25@bitsathy.ac.in','JagaPrasanth S','student','GET','/api/v1/interviews/sessions/4','','2a09:bac1:3680:128::29e:38','Mozilla/5.0 (Windows NT 1