ter\":{\"id\":3,\"name\":\"Jaison David M\",\"email\":\"jaisondavidm.cs25@bitsathy.ac.in\",\"roll_no\":\"7376251CS221\",\"department\":\"CSE\",\"role\":\"student\",\"last_login_at\":\"2026-09-17T09:24:47.84Z\",\"has_active_session\":false,\"created_at\":\"2026-09-17T06:56:03.26Z\",\"updated_at\":\"2026-09-17T09:26:23.895Z\"},\"reported_user_id\":4,\"reported_user\":{\"id\":4,\"name\":\"JagaPrasanth S\",\"email\":\"jagaprasanths.cs25@bitsathy.ac.in\",\"roll_no\":\"7376251CS219\",\"department\":\"CSE\",\"role\":\"student\",\"last_login_at\":\"2026-09-17T09:22:02.127Z\",\"has_active_session\":false,\"created_at\":\"2026-09-17T06:56:38.831Z\",\"updated_at\":\"2026-09-17T09:22:02.128Z\"},\"asked_credentials\":true,\"incident_type\":\"credential_solicitation\",\"details\":\"\",\"status\":\"pending\",\"created_at\":\"2026-09-17T09:26:13.544Z\",\"updated_at\":\"2026-09-17T09:26:13.544Z\"}],\"session\":{\"id\":4,\"track_id\":1,\"track\":{\"id\":1,\"title\":\"Data Structures \\u0026 Algorithms\",\"slug\":\"dsa\",\"category\":\"Technical\",\"icon\":\"Code\",\"description\":\"Core problem solving, arrays, trees, dynamic programming, and algorithmic complexity.\",\"created_at\":\"2026-09-17T07:43:11Z\",\"updated_at\":\"2026-09-17T07:43:11Z\"},\"level_id\":1,\"level\":{\"id\":1,\"track_id\":1,\"level_number\":1,\"name\":\"Arrays, Strings \\u0026 HashMaps\",\"description\":\"Fundamental data structures and two-pointer techniques\",\"mode\":\"coding\",\"duration_minutes\":45,\"question_count\":1,\"questions\":[{\"id\":1,\"level_id\":1,\"title\":\"Two Sum with Target Lookup\",\"prompt\":\"Given an array of integers and a target integer, find the indices of two different elements whose sum equals the target. Print the two indices in increasing order. Exactly one valid pair exists.\",\"difficulty\":\"Easy\",\"type\":\"coding\",\"created_at\":\"2026-09-17T07:52:39.705Z\",\"updated_at\":\"2026-09-17T07:52:39.705Z\"},{\"id\":2,\"level_id\":1,\"title\":\"Valid Anagram\",\"prompt\":\"Given two strings, determine whether they are anagrams of each other. Two strings are anagrams if they contain exactly the same characters with the same frequencies.\",\"difficulty\":\"Easy\",\"type\":\"coding\",\"created_at\":\"2026-09-17T07:52:39.811Z\",\"updated_at\":\"2026-09-17T07:52:39.811Z\"},{\"id\":3,\"level_id\":1,\"title\":\"First Non-Repeating Character\",\"prompt\":\"Given a string, find the index of the first character that appears exactly once. If no such character exists, print -1.\",\"difficulty\":\"Easy\",\"type\":\"coding\",\"created_at\":\"2026-09-17T07:52:39.891Z\",\"updated_at\":\"2026-09-17T07:52:39.891Z\"},{\"id\":4,\"level_id\":1,\"title\":\"Group Anagrams\",\"prompt\":\"Given N strings, group strings that are anagrams of each other. Print each group on a separate line. Words within each group should remain in their original input order.\",\"difficulty\":\"Medium\",\"type\":\"coding\",\"created_at\":\"2026-09-17T07:52:39.974Z\",\"updated_at\":\"2026-09-17T07:52:39.974Z\"},{\"id\":5,\"level_id\":1,\"title\":\"Longest Substring Without Repeating Characters\",\"prompt\":\"Given a string, find the length of the longest substring that contains no repeated characters.\",\"difficulty\":\"Medium\",\"type\":\"coding\",\"created_at\":\"2026-09-17T07:52:40.051Z\",\"updated_at\":\"2026-09-17T07:52:40.051Z\"},{\"id\":6,\"level_id\":1,\"title\":\"Majority Element\",\"prompt\":\"Given an array of integers, find the element that appears more than N/2 times. A majority element is guaranteed to exist.\",\"difficulty\":\"Easy\",\"type\":\"coding\",\"created_at\":\"2026-09-17T07:52:40.12Z\",\"updated_at\":\"2026-09-17T07:52:40.12Z\"},{\"id\":7,\"level_id\":1,\"title\":\"Longest Consecutive Sequence\",\"prompt\":\"Given an unsorted array of integers, find the length of the longest sequence of consecutive integers. The elements do not need to appear next to each other in the input array.\",\"difficulty\":\"Medium\",\"type\":\"coding\",\"created_at\":\"2026-09-17T07:52