_approach\":\"Traverse the array once and use a HashMap to store previously visited numbers and their indices. For each number, check whether target - nums[i] already exists.\",\"expected_complexity\":\"Time: O(N), Space: O(N)\",\"ideal_answer\":\"\",\"scenario\":\"\",\"correct_option\":\"\",\"explanation\":\"\",\"created_at\":\"2026-09-17T07:52:39.716Z\",\"updated_at\":\"2026-09-17T07:52:39.716Z\"},\"difficulty\":\"Easy\",\"id\":1,\"level_id\":1,\"mcq_options\":null,\"options\":null,\"payload\":{\"constraints\":\"2 \\u003c= N \\u003c= 10^5\\n-10^9 \\u003c= nums[i] \\u003c= 10^9\\nExactly one valid answer exists.\\nTime Limit: 2.0s\\nMemory Limit: 256MB\",\"open_test_cases\":[{\"explanation\":\"\",\"input\":\"4\\n2 7 11 15\\n9\",\"output\":\"0 1\"}],\"options\":null,\"scenario\":\"\",\"starter_code\":\"\",\"starter_code_cpp\":\"\",\"starter_code_java\":\"\",\"starter_code_js\":\"\",\"starter_code_py\":\"\"},\"prompt\":\"Given an array of integers and a target integer, find the indices of two different elements whose sum equals the target. Print the two indices in increasing order. Exactly one valid pair exists.\",\"templates\":[],\"test_cases\":[{\"explanation\":\"\",\"input\":\"4\\n2 7 11 15\\n9\",\"output\":\"0 1\"}],\"title\":\"Two Sum with Target Lookup\",\"type\":\"coding\"},\"current_question_id\":1,\"end_requested_by\":0,\"ended_at\":null,\"id\":5,\"interviewee\":{\"name\":\"JagaPrasanth S\",\"email\":\"jagaprasanths.cs25@bitsathy.ac.in\",\"roll_no\":\"7376251CS219\",\"department\":\"CSE\"},\"interviewee_id\":4,\"interviewer\":{\"name\":\"Peer Interviewer\",\"roll_no\":\"INTERVIEWER\",\"department\":\"Student Assessor\"},\"interviewer_id\":3,\"interviewer_rubrics\":\"\",\"last_executed_at\":null,\"last_execution_json\":\"\",\"last_execution_passed\":0,\"last_execution_total\":0,\"last_execution_type\":\"\",\"last_execution_verdict\":\"\",\"level\":{\"id\":1,\"track_id\":1,\"level_number\":1,\"name\":\"Arrays, Strings \\u0026 HashMaps\",\"description\":\"Funda