den\":true,\"explanation\":\"\",\"order_index\":2,\"created_at\":\"2026-09-17T07:52:39.833Z\",\"updated_at\":\"2026-09-17T07:52:39.833Z\"}],\"hints\":[{\"id\":3,\"question_id\":2,\"type\":\"hint\",\"content\":\"Think about how to count the frequency of each character.\",\"order_index\":1,\"created_at\":\"2026-09-17T07:52:39.846Z\",\"updated_at\":\"2026-09-17T07:52:39.846Z\"},{\"id\":4,\"question_id\":2,\"type\":\"interview_tip\",\"content\":\"Ask whether sorting both strings is necessary and what its complexity would be.\",\"order_index\":2,\"created_at\":\"2026-09-17T07:52:39.848Z\",\"updated_at\":\"2026-09-17T07:52:39.848Z\"}],\"created_at\":\"2026-09-17T07:52:39.811Z\",\"updated_at\":\"2026-09-17T07:52:39.811Z\"},{\"id\":3,\"level_id\":1,\"title\":\"First Non-Repeating Character\",\"prompt\":\"Given a string, find the index of the first character that appears exactly once. If no such character exists, print -1.\",\"difficulty\":\"Easy\",\"type\":\"coding\",\"detail\":{\"id\":3,\"question_id\":3,\"constraints\":\"1 \\u003c= s.length \\u003c= 10^5\\ns consists of lowercase English letters.\\nTime Limit: 2.0s\\nMemory Limit: 256MB\",\"expected_approach\":\"Build a frequency map for all characters, then make a second pass through the string and return the index of the first character whose frequency is one.\",\"expected_complexity\":\"Time: O(N), Space: O(K)\",\"ideal_answer\":\"\",\"scenario\":\"\",\"correct_option\":\"\",\"explanation\":\"\",\"created_at\":\"2026-09-17T07:52:39.9Z\",\"updated_at\":\"2026-09-17T07:52:39.9Z\"},\"test_cases\":[{\"id\":5,\"question_id\":3,\"input\":\"leetcode\",\"expected_output\":\"0\",\"is_hidden\":false,\"explanation\":\"\",\"order_index\":1,\"created_at\":\"2026-09-17T07:52:39.915Z\",\"updated_at\":\"2026-09-17T07:52:39.915Z\"},{\"id\":6,\"question_id\":3,\"input\":\"aabbcc\",\"expected_output\":\"-1\",\"is_hidden\":true,\"explanation\":\"\",\"order_index\":2,\"created_at\":\"2026-09-17T07:52:39.917Z\",\"updated_at\":\"2026-09-17T0