7Z\"}],\"hints\":[{\"id\":5,\"question_id\":3,\"type\":\"hint\",\"content\":\"First count how many times every character occurs.\",\"order_index\":1,\"created_at\":\"2026-09-17T07:52:39.926Z\",\"updated_at\":\"2026-09-17T07:52:39.926Z\"},{\"id\":6,\"question_id\":3,\"type\":\"interview_tip\",\"content\":\"Ask why two passes still result in O(N) time.\",\"order_index\":2,\"created_at\":\"2026-09-17T07:52:39.932Z\",\"updated_at\":\"2026-09-17T07:52:39.932Z\"}],\"created_at\":\"2026-09-17T07:52:39.891Z\",\"updated_at\":\"2026-09-17T07:52:39.891Z\"},{\"id\":4,\"level_id\":1,\"title\":\"Group Anagrams\",\"prompt\":\"Given N strings, group strings that are anagrams of each other. Print each group on a separate line. Words within each group should remain in their original input order.\",\"difficulty\":\"Medium\",\"type\":\"coding\",\"detail\":{\"id\":4,\"question_id\":4,\"constraints\":\"1 \\u003c= N \\u003c= 10^4\\n1 \\u003c= word.length \\u003c= 100\\nWords contain lowercase English letters.\\nTime Limit: 2.0s\\nMemory Limit: 256MB\",\"expected_approach\":\"Create a character-frequency signature for each word and use that signature as a HashMap key. Words with the same signature belong to the same group.\",\"expected_complexity\":\"Time: O(N * L), Space: O(N * L)\",\"ideal_answer\":\"\",\"scenario\":\"\",\"correct_option\":\"\",\"explanation\":\"\",\"created_at\":\"2026-09-17T07:52:39.983Z\",\"updated_at\":\"2026-09-17T07:52:39.983Z\"},\"test_cases\":[{\"id\":7,\"question_id\":4,\"input\":\"6\\neat tea tan ate nat bat\",\"expected_output\":\"eat tea ate\\ntan nat\\nbat\",\"is_hidden\":false,\"explanation\":\"\",\"order_index\":1,\"created_at\":\"2026-09-17T07:52:39.988Z\",\"updated_at\":\"2026-09-17T07:52:39.988Z\"},{\"id\":8,\"question_id\":4,\"input\":\"5\\nabc cba bac xyz zyx\",\"expected_output\":\"abc cba bac\\nxyz zyx\",\"is_hidden\":true,\"explanation\":\"\",\"order_index\":2,\"created_at\":\"2026-09-17T07:52:39.994Z\",\"updated_at\":\"2026-09-17T07:52:39.994Z\"}]