17T07:52:39.761Z\"}],\"created_at\":\"2026-09-17T07:52:39.705Z\",\"updated_at\":\"2026-09-17T07:52:39.705Z\"},{\"id\":2,\"level_id\":1,\"title\":\"Valid Anagram\",\"prompt\":\"Given two strings, determine whether they are anagrams of each other. Two strings are anagrams if they contain exactly the same characters with the same frequencies.\",\"difficulty\":\"Easy\",\"type\":\"coding\",\"detail\":{\"id\":2,\"question_id\":2,\"constraints\":\"1 \\u003c= s.length, t.length \\u003c= 10^5\\nStrings contain lowercase English letters.\\nTime Limit: 2.0s\\nMemory Limit: 256MB\",\"expected_approach\":\"Count the frequency of every character in the first string and compare it with the frequency of characters in the second string using a HashMap or frequency array.\",\"expected_complexity\":\"Time: O(N), Space: O(K)\",\"ideal_answer\":\"\",\"scenario\":\"\",\"correct_option\":\"\",\"explanation\":\"\",\"created_at\":\"2026-09-17T07:52:39.82Z\",\"updated_at\":\"2026-09-17T07:52:39.82Z\"},\"test_cases\":[{\"id\":3,\"question_id\":2,\"input\":\"anagram\\nnagaram\",\"expected_output\":\"true\",\"is_hidden\":false,\"explanation\":\"\",\"order_index\":1,\"created_at\":\"2026-09-17T07:52:39.831Z\",\"updated_at\":\"2026-09-17T07:52:39.831Z\"},{\"id\":4,\"question_id\":2,\"input\":\"rat\\ncar\",\"expected_output\":\"false\",\"is_hidden\":true,\"explanation\":\"\",\"order_index\":2,\"created_at\":\"2026-09-17T07:52:39.833Z\",\"updated_at\":\"2026-09-17T07:52:39.833Z\"}],\"hints\":[{\"id\":3,\"question_id\":2,\"type\":\"hint\",\"content\":\"Think about how to count the frequency of each character.\",\"order_index\":1,\"created_at\":\"2026-09-17T07:52:39.846Z\",\"updated_at\":\"2026-09-17T07:52:39.846Z\"},{\"id\":4,\"question_id\":2,\"type\":\"interview_tip\",\"content\":\"Ask whether sorting both strings is necessary and what its complexity would be.\",\"order_index\":2,\"created_at\":\"2026-09-17T07:52:39.848Z\",\"updated_at\":\"2026-09-17T07:52:39.848Z\"}],\"created_at\":\"2026-09-17T07:52:39.811Z\",\"updated_at\":\"2026-09-17T07:52:39.811Z\"},{\"id\":3,\"level_id\":1,\"title\":\"First Non-Repeating Character\",\"prompt\":\"Given a string, find the index of the first character that appears exactly once. If no such character exists, print -1.\",\"difficulty\":\"Easy\",\"type\":\"coding\",\"detail\":{\"id\":3,\"question_id\":3,\"constraints\":\"1 \\u003c= s.length \\u003c= 10^5\\ns consists of lowercase English letters.\\nTime Limit: 2.0s\\nMemory Limit: 256MB\",\"expected_approach\":\"Build a frequency map for all characters, then make a second pass through the string and return the index of the first character whose frequency is one.\",\"expected_complexity\":\"Time: O(N), Space: O(K)\",\"ideal_answer\":\"\",\"scenario\":\"\",\"correct_option\":\"\",\"explanation\":\"\",\"created_at\":\"2026-09-17T07:52:39.9Z\",\"updated_at\":\"2026-09-17T07:52:39.9Z\"},\"test_cases\":[{\"id\":5,\"question_id\":3,\"input\":\"leetcode\",\"expected_output\":\"0\",\"is_hidden\":false,\"explanation\":\"\",\"order_index\":1,\"created_at\":\"2026-09-17T07:52:39.915Z\",\"updated_at\":\"2026-09-17T07:52:39.915Z\"},{\"id\":6,\"question_id\":3,\"input\":\"aabbcc\",\"expected_output\":\"-1\",\"is_hidden\":true,\"explanation\":\"\",\"order_index\":2,\"created_at\":\"2026-09-17T07:52:39.917Z\",\"updated_at\":\"2026-09-17T07:52:39.917Z\"}],\"hints\":[{\"id\":5,\"question_id\":3,\"type\":\"hint\",\"content\":\"First count how many times every character occurs.\",\"order_index\":1,\"created_at\":\"2026-09-17T07:52:39.926Z\",\"updated_at\":\"2026-09-17T07:52:39.926Z\"},{\"id\":6,\"question_id\":3,\"type\":\"interview_tip\",\"content\":\"Ask why two passes still result in O(N) time.\",\"order_index\":2,\"created_at\":\"2026-09-17T07:52:39.932Z\",\"updated_at\":\"2026-09-17T07:52:39.932Z\"}],\"created_at\":\"2026-09-17T07:52:39.891Z\",\"updated_at\":\"2026-09-17T07:52:39.891Z\"},{\"id\":4,\"level_id\":1,\"title\":\"Group Anagrams\",\"prompt\":\"Given N strings, group strings that a