pt\":\"Given a string, find the length of the longest substring that contains no repeated characters.\",\"difficulty\":\"Medium\",\"type\":\"coding\",\"detail\":{\"id\":5,\"question_id\":5,\"constraints\":\"0 \\u003c= s.length \\u003c= 10^5\\ns consists of printable ASCII characters.\\nTime Limit: 2.0s\\nMemory Limit: 256MB\",\"expected_approach\":\"Use a sliding window with two pointers and a HashMap storing the most recent index of each character.\",\"expected_complexity\":\"Time: O(N), Space: O(K)\",\"ideal_answer\":\"\",\"scenario\":\"\",\"correct_option\":\"\",\"explanation\":\"\",\"created_at\":\"2026-09-17T07:52:40.058Z\",\"updated_at\":\"2026-09-17T07:52:40.058Z\"},\"test_cases\":[{\"id\":9,\"question_id\":5,\"input\":\"abcabcbb\",\"expected_output\":\"3\",\"is_hidden\":false,\"explanation\":\"\",\"order_index\":1,\"created_at\":\"2026-09-17T07:52:40.069Z\",\"updated_at\":\"2026-09-17T07:52:40.069Z\"},{\"id\":10,\"question_id\":5,\"input\":\"pwwkew\",\"expected_output\":\"3\",\"is_hidden\":true,\"explanation\":\"\",\"order_index\":2,\"created_at\":\"2026-09-17T07:52:40.073Z\",\"updated_at\":\"2026-09-17T07:52:40.073Z\"}],\"hints\":[{\"id\":9,\"question_id\":5,\"type\":\"hint\",\"content\":\"Maintain a window that contains only unique characters.\",\"order_index\":1,\"created_at\":\"2026-09-17T07:52:40.083Z\",\"updated_at\":\"2026-09-17T07:52:40.083Z\"},{\"id\":10,\"question_id\":5,\"type\":\"interview_tip\",\"content\":\"Ask how the left pointer should move when a duplicate character is found.\",\"order_index\":2,\"created_at\":\"2026-09-17T07:52:40.085Z\",\"updated_at\":\"2026-09-17T07:52:40.085Z\"}],\"created_at\":\"2026-09-17T07:52:40.051Z\",\"updated_at\":\"2026-09-17T07:52:40.051Z\"},{\"id\":6,\"level_id\":1,\"title\":\"Majority Element\",\"prompt\":\"Given an array of integers, find the element that appears more than N/2 times. A majority element is guaranteed to exist.\",\"difficulty\":\"Easy\",\"type\":\"coding\",\"detail\":{\"id\":6,\"question_id\":