oding\",\"detail\":{\"id\":1,\"question_id\":1,\"constraints\":\"2 \\u003c= N \\u003c= 10^5\\n-10^9 \\u003c= nums[i] \\u003c= 10^9\\nExactly one valid answer exists.\\nTime Limit: 2.0s\\nMemory Limit: 256MB\",\"expected_approach\":\"Traverse the array once and use a HashMap to store previously visited numbers and their indices. For each number, check whether target - nums[i] already exists.\",\"expected_complexity\":\"Time: O(N), Space: O(N)\",\"ideal_answer\":\"\",\"scenario\":\"\",\"correct_option\":\"\",\"explanation\":\"\",\"created_at\":\"2026-09-17T07:52:39.716Z\",\"updated_at\":\"2026-09-17T07:52:39.716Z\"},\"test_cases\":[{\"id\":1,\"question_id\":1,\"input\":\"4\\n2 7 11 15\\n9\",\"expected_output\":\"0 1\",\"is_hidden\":false,\"explanation\":\"\",\"order_index\":1,\"created_at\":\"2026-09-17T07:52:39.741Z\",\"updated_at\":\"2026-09-17T07:52:39.741Z\"},{\"id\":2,\"question_id\":1,\"input\":\"5\\n3 3 8 2 10\\n6\",\"expected_output\":\"0 1\",\"is_hidden\":true,\"explanation\":\"\",\"order_index\":2,\"created_at\":\"2026-09-17T07:52:39.747Z\",\"updated_at\":\"2026-09-17T07:52:39.747Z\"}],\"hints\":[{\"id\":1,\"question_id\":1,\"type\":\"hint\",\"content\":\"Can you store already visited numbers and look for target - current number?\",\"order_index\":1,\"created_at\":\"2026-09-17T07:52:39.753Z\",\"updated_at\":\"2026-09-17T07:52:39.753Z\"},{\"id\":2,\"question_id\":1,\"type\":\"interview_tip\",\"content\":\"Ask why a nested-loop solution becomes O(N^2).\",\"order_index\":2,\"created_at\":\"2026-09-17T07:52:39.761Z\",\"updated_at\":\"2026-09-17T07:52:39.761Z\"}],\"created_at\":\"2026-09-17T07:52:39.705Z\",\"updated_at\":\"2026-09-17T07:52:39.705Z\"},{\"id\":2,\"level_id\":1,\"title\":\"Valid Anagram\",\"prompt\":\"Given two strings, determine whether they are anagrams of each other. Two strings are anagrams if they contain exactly the same characters with the same frequencies.\",\"difficulty\":\"Easy\",\"type\":\"coding\",\"detail\":{\"id\":2,\"question_id\":2,\