.395Z\",\"updated_at\":\"2026-09-17T07:52:40.395Z\"}],\"hints\":[{\"id\":19,\"question_id\":10,\"type\":\"hint\",\"content\":\"The most recently opened bracket must be closed first.\",\"order_index\":1,\"created_at\":\"2026-09-17T07:52:40.401Z\",\"updated_at\":\"2026-09-17T07:52:40.401Z\"},{\"id\":20,\"question_id\":10,\"type\":\"interview_tip\",\"content\":\"Ask why a stack is suitable for this problem and what happens when a closing bracket appears with an empty stack.\",\"order_index\":2,\"created_at\":\"2026-09-17T07:52:40.402Z\",\"updated_at\":\"2026-09-17T07:52:40.402Z\"}],\"created_at\":\"2026-09-17T07:52:40.371Z\",\"updated_at\":\"2026-09-17T07:52:40.371Z\"}],\"created_at\":\"2026-09-17T07:44:11Z\",\"updated_at\":\"2026-09-17T07:44:25.437Z\"},\"level_id\":1,\"level_questions\":[{\"correct_option\":\"\",\"created_at\":\"2026-09-17T07:52:39.811Z\",\"detail\":{\"id\":2,\"question_id\":2,\"constraints\":\"1 \\u003c= s.length, t.length \\u003c= 10^5\\nStrings contain lowercase English letters.\\nTime Limit: 2.0s\\nMemory Limit: 256MB\",\"expected_approach\":\"Count the frequency of every character in the first string and compare it with the frequency of characters in the second string using a HashMap or frequency array.\",\"expected_complexity\":\"Time: O(N), Space: O(K)\",\"ideal_answer\":\"\",\"scenario\":\"\",\"correct_option\":\"\",\"explanation\":\"\",\"created_at\":\"2026-09-17T07:52:39.82Z\",\"updated_at\":\"2026-09-17T07:52:39.82Z\"},\"difficulty\":\"Easy\",\"explanation\":\"\",\"id\":2,\"ideal_answer\":\"\",\"interview_tips\":[\"Ask whether sorting both strings is necessary and what its complexity would be.\"],\"level_id\":1,\"mcq_options\":null,\"options\":null,\"payload\":{\"constraints\":\"1 \\u003c= s.length, t.length \\u003c= 10^5\\nStrings contain lowercase English letters.\\nTime Limit: 2.0s\\nMemory Limit: 256MB\",\"correct_option\":\"\",\"expected_approach\":\"Count the frequency of every character in the first string and compare it with the fre