9-17T07:52:39.891Z\"},{\"id\":4,\"level_id\":1,\"title\":\"Group Anagrams\",\"prompt\":\"Given N strings, group strings that are anagrams of each other. Print each group on a separate line. Words within each group should remain in their original input order.\",\"difficulty\":\"Medium\",\"type\":\"coding\",\"detail\":{\"id\":4,\"question_id\":4,\"constraints\":\"1 \\u003c= N \\u003c= 10^4\\n1 \\u003c= word.length \\u003c= 100\\nWords contain lowercase English letters.\\nTime Limit: 2.0s\\nMemory Limit: 256MB\",\"expected_approach\":\"Create a character-frequency signature for each word and use that signature as a HashMap key. Words with the same signature belong to the same group.\",\"expected_complexity\":\"Time: O(N * L), Space: O(N * L)\",\"ideal_answer\":\"\",\"scenario\":\"\",\"correct_option\":\"\",\"explanation\":\"\",\"created_at\":\"2026-09-17T07:52:39.983Z\",\"updated_at\":\"2026-09-17T07:52:39.983Z\"},\"test_cases\":[{\"id\":7,\"question_id\":4,\"input\":\"6\\neat tea tan ate nat bat\",\"expected_output\":\"eat tea ate\\ntan nat\\nbat\",\"is_hidden\":false,\"explanation\":\"\",\"order_index\":1,\"created_at\":\"2026-09-17T07:52:39.988Z\",\"updated_at\":\"2026-09-17T07:52:39.988Z\"},{\"id\":8,\"question_id\":4,\"input\":\"5\\nabc cba bac xyz zyx\",\"expected_output\":\"abc cba bac\\nxyz zyx\",\"is_hidden\":true,\"explanation\":\"\",\"order_index\":2,\"created_at\":\"2026-09-17T07:52:39.994Z\",\"updated_at\":\"2026-09-17T07:52:39.994Z\"}],\"hints\":[{\"id\":7,\"question_id\":4,\"type\":\"hint\",\"content\":\"Anagrams have the same character frequencies.\",\"order_index\":1,\"created_at\":\"2026-09-17T07:52:40Z\",\"updated_at\":\"2026-09-17T07:52:40Z\"},{\"id\":8,\"question_id\":4,\"type\":\"interview_tip\",\"content\":\"Ask the candidate to compare a sorted-string key with a frequency-based key.\",\"order_index\":2,\"created_at\":\"2026-09-17T07:52:40.002Z\",\"updated_at\":\"2026-09-17T07:52:40.002Z\"}],\"created_at\":\"2026-09-17T07:52:39.974Z\",\"updated_at\":\"2026-09-17T07:52:39.974Z\"},{\"id\":5,\"level_id\":1,\"title\":\"Longest Substring Without Repeating Characters\",\"prompt\":\"Given a string, find the length of the longest substring that contains no repeated characters.\",\"difficulty\":\"Medium\",\"type\":\"coding\",\"detail\":{\"id\":5,\"question_id\":5,\"constraints\":\"0 \\u003c= s.length \\u003c= 10^5\\ns consists of printable ASCII characters.\\nTime Limit: 2.0s\\nMemory Limit: 256MB\",\"expected_approach\":\"Use a sliding window with two pointers and a HashMap storing the most recent index of each character.\",\"expected_complexity\":\"Time: O(N), Space: O(K)\",\"ideal_answer\":\"\",\"scenario\":\"\",\"correct_option\":\"\",\"explanation\":\"\",\"created_at\":\"2026-09-17T07:52:40.058Z\",\"updated_at\":\"2026-09-17T07:52:40.058Z\"},\"test_cases\":[{\"id\":9,\"question_id\":5,\"input\":\"abcabcbb\",\"expected_output\":\"3\",\"is_hidden\":false,\"explanation\":\"\",\"order_index\":1,\"created_at\":\"2026-09-17T07:52:40.069Z\",\"updated_at\":\"2026-09-17T07:52:40.069Z\"},{\"id\":10,\"question_id\":5,\"input\":\"pwwkew\",\"expected_output\":\"3\",\"is_hidden\":true,\"explanation\":\"\",\"order_index\":2,\"created_at\":\"2026-09-17T07:52:40.073Z\",\"updated_at\":\"2026-09-17T07:52:40.073Z\"}],\"hints\":[{\"id\":9,\"question_id\":5,\"type\":\"hint\",\"content\":\"Maintain a window that contains only unique characters.\",\"order_index\":1,\"created_at\":\"2026-09-17T07:52:40.083Z\",\"updated_at\":\"2026-09-17T07:52:40.083Z\"},{\"id\":10,\"question_id\":5,\"type\":\"interview_tip\",\"content\":\"Ask how the left pointer should move when a duplicate character is found.\",\"order_index\":2,\"created_at\":\"2026-09-17T07:52:40.085Z\",\"updated_at\":\"2026-09-17T07:52:40.085Z\"}],\"created_at\":\"2026-09-17T07:52:40.051Z\",\"updated_at\":\"2026-09-17T07:52:40.051Z\"},{\"id\":6,\"level_id\":1,\"title\":\"Majority Element\",\"prompt\":\"Given an array of integers, find the element that appears more than N/2 times. 