\":\"\",\"explanation\":\"\",\"created_at\":\"2026-09-17T07:52:40.382Z\",\"updated_at\":\"2026-09-17T07:52:40.382Z\"},\"test_cases\":[{\"id\":19,\"question_id\":10,\"input\":\"{[()]}\",\"expected_output\":\"true\",\"is_hidden\":false,\"explanation\":\"\",\"order_index\":1,\"created_at\":\"2026-09-17T07:52:40.388Z\",\"updated_at\":\"2026-09-17T07:52:40.388Z\"},{\"id\":20,\"question_id\":10,\"input\":\"([)]\",\"expected_output\":\"false\",\"is_hidden\":true,\"explanation\":\"\",\"order_index\":2,\"created_at\":\"2026-09-17T07:52:40.395Z\",\"updated_at\":\"2026-09-17T07:52:40.395Z\"}],\"hints\":[{\"id\":19,\"question_id\":10,\"type\":\"hint\",\"content\":\"The most recently opened bracket must be closed first.\",\"order_index\":1,\"created_at\":\"2026-09-17T07:52:40.401Z\",\"updated_at\":\"2026-09-17T07:52:40.401Z\"},{\"id\":20,\"question_id\":10,\"type\":\"interview_tip\",\"content\":\"Ask why a stack is suitable for this problem and what happens when a closing bracket appears with an empty stack.\",\"order_index\":2,\"created_at\":\"2026-09-17T07:52:40.402Z\",\"updated_at\":\"2026-09-17T07:52:40.402Z\"}],\"created_at\":\"2026-09-17T07:52:40.371Z\",\"updated_at\":\"2026-09-17T07:52:40.371Z\"}],\"created_at\":\"2026-09-17T07:44:11Z\",\"updated_at\":\"2026-09-17T07:44:25.437Z\"},\"level_id\":1,\"level_questions\":null,\"roles_switched\":true,\"round\":2,\"started_at\":\"2026-09-17T09:28:12.953Z\",\"status\":\"completed\",\"switch_count\":1,\"switch_requested_by\":0,\"track\":{\"id\":1,\"title\":\"Data Structures \\u0026 Algorithms\",\"slug\":\"dsa\",\"category\":\"Technical\",\"icon\":\"Code\",\"description\":\"Core problem solving, arrays, trees, dynamic programming, and algorithmic complexity.\",\"created_at\":\"2026-09-17T07:43:11Z\",\"updated_at\":\"2026-09-17T07:43:11Z\"},\"track_id\":1}},\"status\":\"success\"}','','2026-09-17 09:39:42.186'),(2022,4,'jagaprasanths.cs25@bitsathy.ac.in','JagaPrasanth S','student','POST','/api/v1/interviews/sessions/5/security-report