INSERT INTO `interview_levels` VALUES (1,1,1,'Arrays, Strings & HashMaps','Fundamental data structures and two-pointer techniques','coding',45,1,'2026-09-17 07:44:11.000','2026-09-17 07:44:25.437',NULL),(2,1,2,'Trees, Graphs & Recursion','Tree traversals, BFS/DFS algorithms, and topological sorting','coding',50,1,'2026-09-17 07:44:11.000','2026-09-17 07:44:35.989',NULL),(3,1,3,'Dynamic Programming & Optimization','State transitions, memoization, and hard algorithmic challenges','coding',60,1,'2026-09-17 07:44:11.000','2026-09-17 07:44:42.721',NULL),(4,2,1,'High-Level System Design','Designing scalable URL shorteners, rate limiters, and cache layers','whiteboard',45,1,'2026-09-17 07:44:11.000','2026-09-17 07:44:11.000',NULL),(5,2,2,'Large-Scale Distributed Systems','Designing YouTube, Uber, or messaging systems with partitioning and CAP theorem','whiteboard',60,1,'2026-09-17 07:44:11.000','2026-09-17 07:44:11.000',NULL),(6,3,1,'Relational Queries & Complex Joins','Interactive SQL playground: aggregations, subqueries, and window functions','database',45,1,'2026-09-17 07:44:11.000','2026-09-17 07:55:49.616',NULL),(7,3,2,'Schema Design & Query Optimization','Indexing strategies, query execution plans, and transaction isolation','database',50,1,'2026-09-17 07:44:11.000','2026-09-17 07:55:56.111',NULL),(8,4,1,'Component Architecture & State','React component patterns, hooks, and DOM manipulation','frontend',45,1,'2026-09-17 07:44:11.000','2026-09-17 07:56:14.562',NULL),(9,4,2,'Complex UI & Performance Tuning','Virtualization, rendering optimizations, and rich interactive widgets','frontend',50,1,'2026-09-17 07:44:11.000','2026-09-17 07:44:11.000',NULL),(10,5,1,'API Design & Middleware Auth','CRUD endpoint design, JWT auth middleware, and error handling','backend',45,1,'2026-09-17 07:44:11.000','2026-09-17 07:56:26.479',NULL),(11,5,2,'Concurrency & Resilient Services','Goroutines/threads, Redis caching, worker pools, and rate limiting','backend',50,1,'2026-09-17 07:44:11.000','2026-09-17 07:56:35.889',NULL),(12,6,1,'Core CS Quick Quiz','OS scheduling, memory management, TCP/IP, and SQL concepts','mcq',25,10,'2026-09-17 07:44:11.000','2026-09-17 08:28:34.619',NULL),(13,6,2,'Advanced System Concepts MCQ','Locking mechanisms, distributed consensus, and networking protocols','mcq',30,10,'2026-09-17 07:44:11.000','2026-09-17 08:28:49.321',NULL),(14,7,1,'Situational & STAR Format Q&A','Describe past project challenges, teamwork, and deliverables under pressure','verbal_qa',30,5,'2026-09-17 07:44:11.000','2026-09-17 07:56:55.016',NULL),(15,7,2,'Leadership & Conflict Management','Cross-team communication, mentorship, and technical decision making','verbal_qa',40,5,'2026-09-17 07:44:11.000','2026-09-17 07:56:59.115',NULL);
