INSERT INTO `interview_question_code_templates` VALUES (1,21,'sql','CREATE TABLE departments (\n  id INTEGER PRIMARY KEY,\n  name VARCHAR(100) NOT NULL\n);\n\nCREATE TABLE employees (\n  id INTEGER PRIMARY KEY,\n  name VARCHAR(100) NOT NULL,\n  department_id INTEGER,\n  salary DECIMAL(10,2) NOT NULL,\n  FOREIGN KEY (department_id) REFERENCES departments(id)\n);\n\nINSERT INTO departments VALUES\n(1, \'Engineering\'),\n(2, \'HR\'),\n(3, \'Finance\');\n\nINSERT INTO employees VALUES\n(101, \'Alice\', 1, 90000),\n(102, \'Bob\', 1, 110000),\n(103, \'Charlie\', 1, 105000),\n(104, \'David\', 2, 70000),\n(105, \'Eva\', 2, 85000),\n(106, \'Frank\', 3, 95000);','2026-09-17 07:59:35.695','2026-09-17 07:59:35.695'),(2,22,'sql','CREATE TABLE customers (\n  id INTEGER PRIMARY KEY,\n  name VARCHAR(100) NOT NULL,\n  email VARCHAR(255) UNIQUE NOT NULL\n);\n\nCREATE TABLE orders (\n  id INTEGER PRIMARY KEY,\n  customer_id INTEGER,\n  status VARCHAR(50) NOT NULL,\n  total_amount DECIMAL(10,2) NOT NULL,\n  created_at TIMESTAMP NOT NULL,\n  FOREIGN KEY (customer_id) REFERENCES customers(id)\n);','2026-09-17 07:59:35.734','2026-09-17 07:59:35.734'),(3,23,'sql','CREATE TABLE categories (\n  id INTEGER PRIMARY KEY,\n  name VARCHAR(100) NOT NULL\n);\n\nCREATE TABLE products (\n  id INTEGER PRIMARY KEY,\n  name VARCHAR(150) NOT NULL,\n  category_id INTEGER,\n  FOREIGN KEY (category_id) REFERENCES categories(id)\n);\n\nCREATE TABLE orders (\n  id INTEGER PRIMARY KEY,\n  status VARCHAR(50) NOT NULL\n);\n\nCREATE TABLE order_items (\n  order_id INTEGER,\n  product_id INTEGER,\n  quantity INTEGER NOT NULL,\n  FOREIGN KEY (order_id) REFERENCES orders(id),\n  FOREIGN KEY (product_id) REFERENCES products(id)\n);','2026-09-17 07:59:35.776','2026-09-17 07:59:35.776'),(4,24,'sql','CREATE TABLE departments (\n  id INTEGER PRIMARY KEY,\n  name VARCHAR(100) NOT NULL\n);\n\nCREATE TABLE employees (\n  id INTEGER PRIMARY KEY,\n  name VARCHAR(100) NOT NULL,\n  department_id INTEGER,\n  salary DECIMAL(10,2) NOT NULL,\n  FOREIGN KEY (department_id) REFERENCES departments(id)\n);','2026-09-17 07:59:35.824','2026-09-17 07:59:35.824'),(5,25,'sql','CREATE TABLE customers (\n  id INTEGER PRIMARY KEY,\n  name VARCHAR(100) NOT NULL\n);\n\nCREATE TABLE categories (\n  id INTEGER PRIMARY KEY,\n  name VARCHAR(100) NOT NULL\n);\n\nCREATE TABLE products (\n  id INTEGER PRIMARY KEY,\n  name VARCHAR(150) NOT NULL,\n  category_id INTEGER,\n  price DECIMAL(10,2) NOT NULL,\n  FOREIGN KEY (category_id) REFERENCES categories(id)\n);\n\nCREATE TABLE orders (\n  id INTEGER PRIMARY KEY,\n  customer_id INTEGER,\n  status VARCHAR(50) NOT NULL,\n  FOREIGN KEY (customer_id) REFERENCES customers(id)\n);\n\nCREATE TABLE order_items (\n  order_id INTEGER,\n  product_id INTEGER,\n  quantity INTEGER NOT NULL,\n  FOREIGN KEY (order_id) REFERENCES orders(id),\n  FOREIGN KEY (product_id) REFERENCES products(id)\n);','2026-09-17 07:59:35.875','2026-09-17 07:59:35.875'),(6,26,'javascript','import React from \'react\';\n\nconst products = [\n  { id: 1, name: \'Laptop\', price: 50000 },\n  { id: 2, name: \'Mouse\', price: 1000 },\n  { id: 3, name: \'Keyboard\', price: 2000 }\n];\n\nexport default function App() {\n  return (\n    <div>\n      <h1>Products</h1>\n      {/* Display products here */}\n    </div>\n  );\n}','2026-09-17 08:01:12.096','2026-09-17 08:01:12.096'),(7,27,'javascript','import React, { useState } from \'react\';\n\nexport default function App() {\n  const [count, setCount] = useState(0);\n\n  return (\n    <div>\n      <h1>Counter</h1>\n      <p>{count}</p>\n      {/* Add buttons here */}\n    </div>\n  );\n}','2026-09-17 08:01:12.143','2026-09-17 08:01:12.143'),(8,28,'javascript','import React, { useState } from \'react\';\n\nconst users = [\'Alice\', \'Bob\', \'Charlie\', \'David\'];\n\nexport default function App() {\n  const [search, setSearch] = useState(\'\');\n\n  return (\n    <div>\n      <h1>Users</h1>\n      <input\n        type=\"text\"\n        placeholder=\"Search user\"\n        value={search}\n        onChange={(e) => setSearch(e.target.value)}\n      />\n      {/* Display filtered users here */}\n    </div>\n  );\n}','2026-09-17 08:01:12.197','2026-09-17 08:01:12.197'),(9,29,'javascript','import React, { useState } from \'react\';\n\nexport default function App() {\n  const [task, setTask] = useState(\'\');\n  const [todos, setTodos] = useState([]);\n\n  return (\n    <div>\n      <h1>Todo List</h1>\n      <input\n        value={task}\n        onChange={(e) => setTask(e.target.value)}\n        placeholder=\"Enter a task\"\n      />\n      <button>Add</button>\n      {/* Display todos here */}\n    </div>\n  );\n}','2026-09-17 08:01:12.260','2026-09-17 08:01:12.260'),(10,30,'javascript','import React, { useState } from \'react\';\n\nexport default function App() {\n  const [showPassword, setShowPassword] = useState(false);\n\n  return (\n    <div>\n      <h1>Password</h1>\n      <input\n        type={showPassword ? \'text\' : \'password\'}\n        placeholder=\"Enter password\"\n      />\n      <button onClick={() => setShowPassword(!showPassword)}>\n        Show / Hide\n      </button>\n    </div>\n  );\n}','2026-09-17 08:01:12.296','2026-09-17 08:01:12.296');
