INSERT INTO `interview_question_hints` VALUES (1,1,'hint','Can you store already visited numbers and look for target - current number?',1,'2026-09-17 07:52:39.753','2026-09-17 07:52:39.753'),(2,1,'interview_tip','Ask why a nested-loop solution becomes O(N^2).',2,'2026-09-17 07:52:39.761','2026-09-17 07:52:39.761'),(3,2,'hint','Think about how to count the frequency of each character.',1,'2026-09-17 07:52:39.846','2026-09-17 07:52:39.846'),(4,2,'interview_tip','Ask whether sorting both strings is necessary and what its complexity would be.',2,'2026-09-17 07:52:39.848','2026-09-17 07:52:39.848'),(5,3,'hint','First count how many times every character occurs.',1,'2026-09-17 07:52:39.926','2026-09-17 07:52:39.926'),(6,3,'interview_tip','Ask why two passes still result in O(N) time.',2,'2026-09-17 07:52:39.932','2026-09-17 07:52:39.932'),(7,4,'hint','Anagrams have the same character frequencies.',1,'2026-09-17 07:52:40.000','2026-09-17 07:52:40.000'),(8,4,'interview_tip','Ask the candidate to compare a sorted-string key with a frequency-based key.',2,'2026-09-17 07:52:40.002','2026-09-17 07:52:40.002'),(9,5,'hint','Maintain a window that contains only unique characters.',1,'2026-09-17 07:52:40.083','2026-09-17 07:52:40.083'),(10,5,'interview_tip','Ask how the left pointer should move when a duplicate character is found.',2,'2026-09-17 07:52:40.085','2026-09-17 07:52:40.085'),(11,6,'hint','You can first think about counting frequencies with a HashMap.',1,'2026-09-17 07:52:40.155','2026-09-17 07:52:40.155'),(12,6,'interview_tip','Ask whether the candidate can reduce the auxiliary space to O(1).',2,'2026-09-17 07:52:40.162','2026-09-17 07:52:40.162'),(13,7,'hint','Try putting all numbers into a HashSet.',1,'2026-09-17 07:52:40.217','2026-09-17 07:52:40.217'),(14,7,'interview_tip','Ask why sorting is not required and how duplicates are handled.',2,'2026-09-17 07:52:40.217','2026-09-17 07:52:40.217'),(15,8,'hint','For every position, think about the product of elements on its left and right.',1,'2026-09-17 07:52:40.273','2026-09-17 07:52:40.273'),(16,8,'interview_tip','Ask why division is problematic when the array contains zero.',2,'2026-09-17 07:52:40.278','2026-09-17 07:52:40.278'),(17,9,'hint','Think about prefix sums and what previous sum would be needed to produce K.',1,'2026-09-17 07:52:40.334','2026-09-17 07:52:40.334'),(18,9,'interview_tip','Ask why a normal sliding-window approach does not work when negative numbers are present.',2,'2026-09-17 07:52:40.335','2026-09-17 07:52:40.335'),(19,10,'hint','The most recently opened bracket must be closed first.',1,'2026-09-17 07:52:40.401','2026-09-17 07:52:40.401'),(20,10,'interview_tip','Ask why a stack is suitable for this problem and what happens when a closing bracket appears with an empty stack.',2,'2026-09-17 07:52:40.402','2026-09-17 07:52:40.402'),(21,11,'talking_point','Consider Base62 encoding with a distributed ID generator for creating short URLs.',1,'2026-09-17 07:55:23.382','2026-09-17 07:55:23.382'),(22,11,'talking_point','Use Redis caching for frequently accessed short URLs.',2,'2026-09-17 07:55:23.383','2026-09-17 07:55:23.383'),(23,11,'tradeoff','Discuss 301 versus 302 redirects and their impact on caching, server load, and analytics.',3,'2026-09-17 07:55:23.384','2026-09-17 07:55:23.384'),(24,11,'interview_tip','Ask how the database should be sharded as the number of URLs grows.',4,'2026-09-17 07:55:23.385','2026-09-17 07:55:23.385'),(25,12,'talking_point','Consider WebSockets for persistent real-time connections.',1,'2026-09-17 07:55:23.436','2026-09-17 07:55:23.436'),(26,12,'talking_point','Use a message queue such as Kafka to decouple message ingestion from delivery.',2,'2026-09-17 07:55:23.445','2026-09-17 07:55:23.445'),(27,12,'tradeoff','Discuss at-most-once, at-least-once, and effectively-once message delivery.',3,'2026-09-17 07:55:23.446','2026-09-17 07:55:23.446'),(28,12,'interview_tip','Ask how messages are delivered when the recipient is temporarily offline.',4,'2026-09-17 07:55:23.447','2026-09-17 07:55:23.447'),(29,13,'talking_point','Use object storage for video files and a CDN for global delivery.',1,'2026-09-17 07:55:23.483','2026-09-17 07:55:23.483'),(30,13,'talking_point','Transcode uploaded videos into multiple resolutions and bitrates.',2,'2026-09-17 07:55:23.483','2026-09-17 07:55:23.483'),(31,13,'tradeoff','Discuss storage cost versus video quality and the number of generated resolutions.',3,'2026-09-17 07:55:23.484','2026-09-17 07:55:23.484'),(32,13,'interview_tip','Ask how the system handles a sudden traffic spike for a viral video.',4,'2026-09-17 07:55:23.486','2026-09-17 07:55:23.486'),(33,14,'talking_point','Separate order management, payment, restaurant, and delivery services.',1,'2026-09-17 07:55:23.545','2026-09-17 07:55:23.545'),(34,14,'talking_point','Use asynchronous events for order status updates and delivery tracking.',2,'2026-09-17 07:55:23.549','2026-09-17 07:55:23.549'),(35,14,'tradeoff','Discuss strong consistency for orders and payments versus eventual consistency for restaurant availability and tracking.',3,'2026-09-17 07:55:23.550','2026-09-17 07:55:23.550'),(36,14,'interview_tip','Ask how duplicate payment requests and duplicate orders are prevented.',4,'2026-09-17 07:55:23.553','2026-09-17 07:55:23.553'),(37,15,'talking_point','Use geospatial indexing to find nearby available drivers efficiently.',1,'2026-09-17 07:55:23.648','2026-09-17 07:55:23.648'),(38,15,'talking_point','Use WebSockets or similar persistent connections for real-time location updates.',2,'2026-09-17 07:55:23.650','2026-09-17 07:55:23.650'),(39,15,'tradeoff','Discuss location-update frequency versus network, CPU, and storage costs.',3,'2026-09-17 07:55:23.653','2026-09-17 07:55:23.653'),(40,15,'interview_tip','Ask how the system prevents two passengers from being assigned the same driver.',4,'2026-09-17 07:55:23.666','2026-09-17 07:55:23.666'),(41,16,'talking_point','Consider token bucket or sliding-window algorithms.',1,'2026-09-17 07:55:23.749','2026-09-17 07:55:23.749'),(42,16,'talking_point','Use Redis or another distributed store for shared counters.',2,'2026-09-17 07:55:23.754','2026-09-17 07:55:23.754'),(43,16,'tradeoff','Discuss exact global limits versus local limits with lower latency.',3,'2026-09-17 07:55:23.762','2026-09-17 07:55:23.762'),(44,16,'interview_tip','Ask what happens when the Redis cluster becomes temporarily unavailable.',4,'2026-09-17 07:55:23.765','2026-09-17 07:55:23.765'),(45,17,'talking_point','Use a message queue between event producers and notification workers.',1,'2026-09-17 07:55:23.825','2026-09-17 07:55:23.825'),(46,17,'talking_point','Use retry queues and dead-letter queues for failed notifications.',2,'2026-09-17 07:55:23.830','2026-09-17 07:55:23.830'),(47,17,'tradeoff','Discuss delivery guarantees versus duplicate notifications.',3,'2026-09-17 07:55:23.831','2026-09-17 07:55:23.831'),(48,17,'interview_tip','Ask how notification preferences and user-specific rate limits should be enforced.',4,'2026-09-17 07:55:23.832','2026-09-17 07:55:23.832'),(49,18,'talking_point','Use object storage with metadata stored separately in a database.',1,'2026-09-17 07:55:23.897','2026-09-17 07:55:23.897'),(50,18,'talking_point','Consider multipart uploads for large files and CDN caching for frequently downloaded files.',2,'2026-09-17 07:55:23.899','2026-09-17 07:55:23.899'),(51,18,'tradeoff','Discuss replication level, durability, storage cost, and access latency.',3,'2026-09-17 07:55:23.900','2026-09-17 07:55:23.900'),(52,18,'interview_tip','Ask how concurrent updates to the same file should be handled.',4,'2026-09-17 07:55:23.902','2026-09-17 07:55:23.902'),(53,19,'talking_point','Use caching and read replicas for high-volume product browsing.',1,'2026-09-17 07:55:23.948','2026-09-17 07:55:23.948'),(54,19,'talking_point','Use atomic inventory operations to prevent overselling during high-demand sales.',2,'2026-09-17 07:55:23.949','2026-09-17 07:55:23.949'),(55,19,'tradeoff','Discuss database consistency versus availability for inventory and product information.',3,'2026-09-17 07:55:23.950','2026-09-17 07:55:23.950'),(56,19,'interview_tip','Ask how the system handles thousands of users attempting to purchase the last item simultaneously.',4,'2026-09-17 07:55:23.950','2026-09-17 07:55:23.950'),(57,20,'talking_point','Consider Operational Transformation or Conflict-free Replicated Data Types for concurrent editing.',1,'2026-09-17 07:55:24.009','2026-09-17 07:55:24.009'),(58,20,'talking_point','Use WebSockets for real-time updates and a persistent store for document snapshots and history.',2,'2026-09-17 07:55:24.014','2026-09-17 07:55:24.014'),(59,20,'tradeoff','Discuss centralized operation ordering with OT versus client-side convergence with CRDTs.',3,'2026-09-17 07:55:24.016','2026-09-17 07:55:24.016'),(60,20,'interview_tip','Ask how document snapshotting prevents replaying a very large number of historical operations.',4,'2026-09-17 07:55:24.017','2026-09-17 07:55:24.017'),(61,21,'hint','Use a window function with PARTITION BY department_id and ORDER BY salary DESC.',1,'2026-09-17 07:59:35.699','2026-09-17 07:59:35.699'),(62,21,'interview_tip','Evaluate whether the candidate understands the difference between ROW_NUMBER(), RANK(), and DENSE_RANK().',2,'2026-09-17 07:59:35.703','2026-09-17 07:59:35.703'),(63,22,'hint','A LEFT JOIN can preserve customers even when they have no matching recent completed order.',1,'2026-09-17 07:59:35.740','2026-09-17 07:59:35.740'),(64,22,'interview_tip','Check whether the candidate understands why putting the filtering condition in WHERE instead of ON can change LEFT JOIN behavior.',2,'2026-09-17 07:59:35.741','2026-09-17 07:59:35.741'),(65,23,'hint','First calculate total quantity for each product, then rank products inside each category.',1,'2026-09-17 07:59:35.779','2026-09-17 07:59:35.779'),(66,23,'interview_tip','Evaluate the candidate\'s ability to combine multiple JOINs, GROUP BY, aggregation, and window functions.',2,'2026-09-17 07:59:35.780','2026-09-17 07:59:35.780'),(67,24,'hint','You can calculate the department average using AVG() with PARTITION BY department_id.',1,'2026-09-17 07:59:35.826','2026-09-17 07:59:35.826'),(68,24,'interview_tip','Check whether the candidate can avoid unnecessary correlated subqueries when a window function can solve the problem.',2,'2026-09-17 07:59:35.828','2026-09-17 07:59:35.828'),(69,25,'hint','Use COUNT(DISTINCT product_id) and COUNT(DISTINCT category_id) with HAVING.',1,'2026-09-17 07:59:35.877','2026-09-17 07:59:35.877'),(70,25,'interview_tip','Evaluate whether the candidate understands the difference between WHERE and HAVING when filtering aggregated results.',2,'2026-09-17 07:59:35.880','2026-09-17 07:59:35.880'),(71,26,'hint','Use products.map() to display each product.',1,'2026-09-17 08:01:12.106','2026-09-17 08:01:12.106'),(72,27,'hint','Use setCount(count + 1) for increasing and setCount(count - 1) for decreasing.',1,'2026-09-17 08:01:12.147','2026-09-17 08:01:12.147'),(73,28,'hint','Use filter() and includes() to find matching users.',1,'2026-09-17 08:01:12.210','2026-09-17 08:01:12.210'),(74,29,'hint','Use setTodos([...todos, task]) to add a new task.',1,'2026-09-17 08:01:12.261','2026-09-17 08:01:12.261'),(75,30,'hint','Change the input type between \'text\' and \'password\' using the showPassword state.',1,'2026-09-17 08:01:12.306','2026-09-17 08:01:12.306'),(76,31,'hint','Check the request method and validate the user name before creating the user.',1,'2026-09-17 08:02:22.687','2026-09-17 08:02:22.687'),(77,32,'hint','Extract the ID from the URL and search for the matching user.',1,'2026-09-17 08:02:22.729','2026-09-17 08:02:22.729'),(78,33,'hint','Use filter() when a category is provided.',1,'2026-09-17 08:02:22.775','2026-09-17 08:02:22.775'),(79,34,'hint','Find the user first, then update its name.',1,'2026-09-17 08:02:22.811','2026-09-17 08:02:22.811'),(80,35,'hint','Find the task and remove it from the list.',1,'2026-09-17 08:02:22.854','2026-09-17 08:02:22.854'),(81,36,'interview_tip','An operating system manages hardware and provides services to applications.',1,'2026-09-17 08:27:36.258','2026-09-17 08:27:36.258'),(82,37,'interview_tip','Think about what happens when you run a program.',1,'2026-09-17 08:27:36.296','2026-09-17 08:27:36.296'),(83,38,'interview_tip','A process can contain one or more threads.',1,'2026-09-17 08:27:36.337','2026-09-17 08:27:36.337'),(84,39,'interview_tip','Volatile memory loses its data when power is removed.',1,'2026-09-17 08:27:36.374','2026-09-17 08:27:36.374'),(85,40,'interview_tip','The CPU is responsible for executing program instructions.',1,'2026-09-17 08:27:36.418','2026-09-17 08:27:36.418'),(86,41,'interview_tip','Think about a stack of plates.',1,'2026-09-17 08:27:36.457','2026-09-17 08:27:36.457'),(87,42,'interview_tip','Think about people waiting in a line.',1,'2026-09-17 08:27:36.488','2026-09-17 08:27:36.488'),(88,43,'interview_tip','Each search step removes approximately half of the elements.',1,'2026-09-17 08:27:36.523','2026-09-17 08:27:36.523'),(89,44,'interview_tip','Array indexing allows direct access to an element.',1,'2026-09-17 08:27:36.557','2026-09-17 08:27:36.557'),(90,45,'interview_tip','Linked list nodes are connected using references or pointers.',1,'2026-09-17 08:27:36.590','2026-09-17 08:27:36.590'),(91,46,'interview_tip','Hashing is designed for fast key-based lookup.',1,'2026-09-17 08:27:36.623','2026-09-17 08:27:36.623'),(92,47,'interview_tip','The name binary refers to two.',1,'2026-09-17 08:27:36.658','2026-09-17 08:27:36.658'),(93,48,'interview_tip','BFS processes nodes level by level.',1,'2026-09-17 08:27:36.691','2026-09-17 08:27:36.691'),(94,49,'interview_tip','DFS explores one path deeply before moving to another.',1,'2026-09-17 08:27:36.721','2026-09-17 08:27:36.721'),(95,50,'interview_tip','SQL stands for Structured Query Language.',1,'2026-09-17 08:27:36.756','2026-09-17 08:27:36.756'),(96,51,'interview_tip','A primary key value must uniquely identify a record.',1,'2026-09-17 08:27:36.784','2026-09-17 08:27:36.784'),(97,52,'interview_tip','A foreign key usually references a primary or unique key.',1,'2026-09-17 08:27:36.808','2026-09-17 08:27:36.808'),(98,53,'interview_tip','Normalization organizes data to reduce unnecessary repetition.',1,'2026-09-17 08:27:36.841','2026-09-17 08:27:36.841'),(99,54,'interview_tip','GET is generally used when the client wants to read data.',1,'2026-09-17 08:27:36.874','2026-09-17 08:27:36.874'),(100,55,'interview_tip','Think about submitting a form to create something on a server.',1,'2026-09-17 08:27:36.905','2026-09-17 08:27:36.905'),(101,56,'interview_tip','Remember the common \'Not Found\' response.',1,'2026-09-17 08:27:36.925','2026-09-17 08:27:36.925'),(102,57,'interview_tip','5xx status codes generally indicate server-side errors.',1,'2026-09-17 08:27:36.967','2026-09-17 08:27:36.967'),(103,58,'interview_tip','TCP focuses on reliable and ordered delivery.',1,'2026-09-17 08:27:37.006','2026-09-17 08:27:37.006'),(104,59,'interview_tip','UDP trades some reliability features for lower overhead.',1,'2026-09-17 08:27:37.043','2026-09-17 08:27:37.043'),(105,60,'interview_tip','DNS acts like a naming system for network resources.',1,'2026-09-17 08:27:37.092','2026-09-17 08:27:37.092'),(106,61,'interview_tip','Think about keeping an object\'s data and behavior together.',1,'2026-09-17 08:27:37.133','2026-09-17 08:27:37.133'),(107,62,'interview_tip','A child class can reuse functionality from a parent class.',1,'2026-09-17 08:27:37.188','2026-09-17 08:27:37.188'),(108,63,'interview_tip','Think of the same method call behaving differently for different objects.',1,'2026-09-17 08:27:37.234','2026-09-17 08:27:37.234'),(109,64,'interview_tip','A compiler processes source code before or during program execution.',1,'2026-09-17 08:27:37.275','2026-09-17 08:27:37.275'),(110,65,'rubric','Clearly explains the situation and the candidate\'s role in the conflict.',1,'2026-09-17 08:30:41.671','2026-09-17 08:30:41.671'),(111,65,'rubric','Shows active listening, respectful communication, and problem-solving.',2,'2026-09-17 08:30:41.672','2026-09-17 08:30:41.672'),(112,65,'interview_tip','Probe the candidate: What would you do differently if the same conflict happened again?',3,'2026-09-17 08:30:41.686','2026-09-17 08:30:41.686'),(113,66,'rubric','Provides a specific example where the candidate voluntarily took responsibility.',1,'2026-09-17 08:30:41.721','2026-09-17 08:30:41.721'),(114,66,'rubric','Explains how the candidate coordinated or supported other team members.',2,'2026-09-17 08:30:41.722','2026-09-17 08:30:41.722'),(115,66,'interview_tip','Probe the candidate: How did you handle a teammate who was not contributing?',3,'2026-09-17 08:30:41.722','2026-09-17 08:30:41.722'),(116,67,'rubric','Takes responsibility instead of blaming others.',1,'2026-09-17 08:30:41.753','2026-09-17 08:30:41.753'),(117,67,'rubric','Demonstrates learning and corrective action after the mistake.',2,'2026-09-17 08:30:41.753','2026-09-17 08:30:41.753'),(118,67,'interview_tip','Probe the candidate: What specific change did you make after this experience?',3,'2026-09-17 08:30:41.754','2026-09-17 08:30:41.754'),(119,68,'rubric','Explains how priorities were identified and time was managed.',1,'2026-09-17 08:30:41.786','2026-09-17 08:30:41.786'),(120,68,'rubric','Shows calm decision-making and focus under pressure.',2,'2026-09-17 08:30:41.787','2026-09-17 08:30:41.787'),(121,68,'interview_tip','Probe the candidate: How did you decide what to do first?',3,'2026-09-17 08:30:41.788','2026-09-17 08:30:41.788'),(122,69,'rubric','Shows teamwork, empathy, and willingness to support others.',1,'2026-09-17 08:30:41.834','2026-09-17 08:30:41.834'),(123,69,'rubric','Explains how the candidate helped without simply doing the work for the teammate.',2,'2026-09-17 08:30:41.835','2026-09-17 08:30:41.835'),(124,69,'interview_tip','Probe the candidate: How did you make sure the teammate understood the solution?',3,'2026-09-17 08:30:41.835','2026-09-17 08:30:41.835'),(125,70,'rubric','Clearly explains the options and factors considered before making the decision.',1,'2026-09-17 08:30:41.857','2026-09-17 08:30:41.857'),(126,70,'rubric','Demonstrates accountability for the final decision.',2,'2026-09-17 08:30:41.858','2026-09-17 08:30:41.858'),(127,70,'interview_tip','Probe the candidate: What information was most important when making the decision?',3,'2026-09-17 08:30:41.863','2026-09-17 08:30:41.863'),(128,71,'rubric','Shows openness to feedback without becoming defensive.',1,'2026-09-17 08:30:41.889','2026-09-17 08:30:41.889'),(129,71,'rubric','Provides a specific improvement made based on the feedback.',2,'2026-09-17 08:30:41.889','2026-09-17 08:30:41.889'),(130,71,'interview_tip','Probe the candidate: What was the most useful part of the feedback?',3,'2026-09-17 08:30:41.890','2026-09-17 08:30:41.890'),(131,72,'rubric','Clearly explains the unexpected change and its impact.',1,'2026-09-17 08:30:41.919','2026-09-17 08:30:41.919'),(132,72,'rubric','Demonstrates flexibility, problem-solving, and communication.',2,'2026-09-17 08:30:41.919','2026-09-17 08:30:41.919'),(133,72,'interview_tip','Probe the candidate: How did you communicate the changed plan to others?',3,'2026-09-17 08:30:41.920','2026-09-17 08:30:41.920'),(134,73,'rubric','Shows positive communication and understanding of team members.',1,'2026-09-17 08:30:41.953','2026-09-17 08:30:41.953'),(135,73,'rubric','Explains specific actions taken to improve team motivation.',2,'2026-09-17 08:30:41.953','2026-09-17 08:30:41.953'),(136,73,'interview_tip','Probe the candidate: How did you know your approach was working?',3,'2026-09-17 08:30:41.954','2026-09-17 08:30:41.954'),(137,74,'rubric','Accepts responsibility and avoids blaming teammates.',1,'2026-09-17 08:30:41.973','2026-09-17 08:30:41.973'),(138,74,'rubric','Shows ownership, communication, and corrective action.',2,'2026-09-17 08:30:41.974','2026-09-17 08:30:41.974'),(139,74,'interview_tip','Probe the candidate: What did you learn about taking ownership from this experience?',3,'2026-09-17 08:30:41.975','2026-09-17 08:30:41.975');
