INSERT INTO `interview_questions` VALUES (1,1,'Two Sum with Target Lookup','Given an array of integers and a target integer, find the indices of two different elements whose sum equals the target. Print the two indices in increasing order. Exactly one valid pair exists.','Easy','coding','2026-09-17 07:52:39.705','2026-09-17 07:52:39.705',NULL),(2,1,'Valid Anagram','Given two strings, determine whether they are anagrams of each other. Two strings are anagrams if they contain exactly the same characters with the same frequencies.','Easy','coding','2026-09-17 07:52:39.811','2026-09-17 07:52:39.811',NULL),(3,1,'First Non-Repeating Character','Given a string, find the index of the first character that appears exactly once. If no such character exists, print -1.','Easy','coding','2026-09-17 07:52:39.891','2026-09-17 07:52:39.891',NULL),(4,1,'Group Anagrams','Given N strings, group strings that are anagrams of each other. Print each group on a separate line. Words within each group should remain in their original input order.','Medium','coding','2026-09-17 07:52:39.974','2026-09-17 07:52:39.974',NULL),(5,1,'Longest Substring Without Repeating Characters','Given a string, find the length of the longest substring that contains no repeated characters.','Medium','coding','2026-09-17 07:52:40.051','2026-09-17 07:52:40.051',NULL),(6,1,'Majority Element','Given an array of integers, find the element that appears more than N/2 times. A majority element is guaranteed to exist.','Easy','coding','2026-09-17 07:52:40.120','2026-09-17 07:52:40.120',NULL),(7,1,'Longest Consecutive Sequence','Given an unsorted array of integers, find the length of the longest sequence of consecutive integers. The elements do not need to appear next to each other in the input array.','Medium','coding','2026-09-17 07:52:40.194','2026-09-17 07:52:40.194',NULL),(8,1,'Product of Array Except Self','Given an integer array, return an array where each position contains the product of every element except the element at that position. Division is not allowed.','Medium','coding','2026-09-17 07:52:40.252','2026-09-17 07:52:40.252',NULL),(9,1,'Subarray Sum Equals K','Given an integer array and an integer K, count the number of contiguous subarrays whose sum equals K.','Medium','coding','2026-09-17 07:52:40.307','2026-09-17 07:52:40.307',NULL),(10,1,'Valid Parentheses','Given a string containing only (), {}, and [], determine whether the brackets are valid. Every opening bracket must have the correct closing bracket, and brackets must close in the correct order.','Easy','coding','2026-09-17 07:52:40.371','2026-09-17 07:52:40.371',NULL),(11,4,'Design a URL Shortener','Design a scalable URL shortening service that converts long URLs into short aliases and redirects users to the original URL.','Medium','whiteboard','2026-09-17 07:55:23.367','2026-09-17 07:55:23.367',NULL),(12,4,'Design a Real-Time Chat System','Design a real-time messaging platform that supports one-to-one and group conversations with message delivery, online presence, and message history.','Medium','whiteboard','2026-09-17 07:55:23.431','2026-09-17 07:55:23.431',NULL),(13,4,'Design a Video Streaming Platform','Design a video streaming service where users can upload videos, browse available content, and stream videos with minimal buffering.','Medium','whiteboard','2026-09-17 07:55:23.477','2026-09-17 07:55:23.477',NULL),(14,4,'Design an Online Food Delivery System','Design an online food delivery platform where customers can discover restaurants, place orders, make payments, and track delivery status in real time.','Medium','whiteboard','2026-09-17 07:55:23.525','2026-09-17 07:55:23.525',NULL),(15,4,'Design a Ride-Sharing System','Design a ride-sharing platform that allows passengers to request rides, matches them with nearby drivers, and tracks rides in real time.','Hard','whiteboard','2026-09-17 07:55:23.618','2026-09-17 07:55:23.618',NULL),(16,4,'Design a Distributed Rate Limiter','Design a distributed rate-limiting service that protects APIs from excessive requests while supporting multiple application servers.','Medium','whiteboard','2026-09-17 07:55:23.717','2026-09-17 07:55:23.717',NULL),(17,4,'Design a Notification System','Design a notification platform capable of sending push notifications, emails, and SMS messages based on events generated by different applications.','Medium','whiteboard','2026-09-17 07:55:23.811','2026-09-17 07:55:23.811',NULL),(18,4,'Design a Distributed File Storage System','Design a cloud file-storage service where users can upload, download, organize, and share files across multiple devices.','Hard','whiteboard','2026-09-17 07:55:23.870','2026-09-17 07:55:23.870',NULL),(19,4,'Design an E-Commerce Platform','Design a scalable e-commerce platform where users can browse products, search inventory, add items to carts, place orders, and complete payments.','Medium','whiteboard','2026-09-17 07:55:23.935','2026-09-17 07:55:23.935',NULL),(20,4,'Design a Real-Time Collaborative Document Editor','Architect a real-time collaborative text editor that allows multiple users to edit the same document simultaneously while resolving conflicts and maintaining document history.','Hard','whiteboard','2026-09-17 07:55:23.988','2026-09-17 07:55:23.988',NULL),(21,6,'Employee Department Salary Analysis','Write a SQL query to find the top 3 highest-paid employees in each department, including the employee name, department name, and salary.','Medium','database','2026-09-17 07:59:35.693','2026-09-17 07:59:35.693',NULL),(22,6,'Customers Without Recent Orders','Write a SQL query to find customers who have not placed any completed orders during the last 6 months.','Medium','database','2026-09-17 07:59:35.728','2026-09-17 07:59:35.728',NULL),(23,6,'Product Sales With Category Ranking','Write a SQL query to find the highest-selling product in each category based on total quantity sold.','Hard','database','2026-09-17 07:59:35.767','2026-09-17 07:59:35.767',NULL),(24,6,'Depar